INSERT INTO public.catalog_chapter VALUES ('8ee39f72-2bc4-4a37-b288-6b2a86d03b8b', '2026-11-19 12:31:17.803103-03', '2026-11-19 12:31:17.803103-03', true, NULL, 'El Traje Nuevo del Emperador', 1, '<?xml version="1.0" encoding="utf-8"?><!DOCTYPE html>
<html epub:prefix="z3998: http://www.daisy.org/z3998/2012/vocab/structure/, se: http://standardebooks.org/vocab/1.0" lang="en-US" xml:lang="en-US" xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
