INSERT INTO public.catalog_chapter VALUES ('9c0be2b6-9f41-48eb-b206-10b473e24c33', '2026-11-19 12:31:18.200184-03', '2026-11-19 12:31:18.200184-03', true, NULL, 'los hermanos de mowgli', 1, '<?xml version="1.0" encoding="utf-8"?><!DOCTYPE html>
<html epub:prefix="z3998: http://www.daisy.org/z3998/2012/vocab/structure/, se: http://standardebooks.org/vocab/1.0" lang="en-US" xml:lang="en-US" xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
