INSERT INTO public.catalog_chapter VALUES ('886f034e-8eea-4e93-bbc1-36b913fef820', '2026-11-19 12:31:18.323254-03', '2026-11-19 12:31:18.323254-03', true, NULL, 'Los zapatos rojos', 1, '<?xml version=''1.0'' encoding=''utf-8''?><html epub:prefix="z3998: http://www.daisy.org/z3998/2012/vocab/structure/, se: http://standardebooks.org/vocab/1.0" lang="en-US" xml:lang="en-US" xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
