INSERT INTO public.catalog_chapter VALUES ('e1fe7a3c-cccd-4ef1-9e74-6e5d81462b10', '2026-11-19 12:31:18.384526-03', '2026-11-19 12:31:18.384526-03', true, NULL, 'Moraleja', 1, '<?xml version=''1.0'' encoding=''utf-8''?><html xml:lang="" xmlns="http://www.w3.org/1999/xhtml">
<head>
<title>Microsoft Word - Perrault, Charles - Pulgarcito.rtf</title>
<meta content="pdftohtml 0.36" name="generator"/>
