INSERT INTO public.games_bookminigame VALUES ('4a271792-202b-4559-9377-ec94f7a26989', '2026-11-19 12:31:19.689325-03', '2026-11-19 12:31:19.689325-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Caperucita llevaba comida a su abuelita.", "isTrue": true}, {"text": "Caperucita se encontró con un oso en el bosque.", "isTrue": false}, {"text": "El lobo le sugirió tomar el camino más corto.", "isTrue": false}], "passage_text": "Caperucita Roja caminaba por el bosque para llevarle una cesta con comida a su abuelita enferma. En el camino, se encontró con el lobo feroz, quien le sugirió tomar el camino más largo.", "time_per_statement": 7}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('106f4fc4-8edb-46c9-9c03-614a245620a6', '2026-11-19 12:31:19.692858-03', '2026-11-19 12:31:19.692858-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El lobo llegó a la casa antes que Caperucita.", "isTrue": true}, {"text": "El lobo se escondió debajo de la mesa.", "isTrue": false}, {"text": "El lobo usó la ropa de la abuela.", "isTrue": true}], "passage_text": "El lobo llegó primero a la casa de la abuela, se vistió con su ropa y se metió en la cama esperando a Caperucita.", "time_per_statement": 7}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('a9c3d53b-9267-4b6c-bd38-b397d620b31d', '2026-11-19 12:31:19.695991-03', '2026-11-19 12:31:19.695991-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Qué dientes tan grandes tienes!", "isCorrect": true}, {"text": "¡Qué flores tan bonitas llevas!", "isCorrect": false}, {"text": "¡Hola abuelita, vine a cantar!", "isCorrect": false}, {"text": "¡Me gusta mucho tu sombrero!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/lobo_sorprendido.png"}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('15cd241c-1d80-4092-99c3-33c593747a54', '2026-11-19 12:31:19.696994-03', '2026-11-19 12:31:19.696994-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Te traje unas galletas, abuelita!", "isCorrect": true}, {"text": "¡Tengo mucho miedo del lobo!", "isCorrect": false}, {"text": "¡Me he perdido en el bosque!", "isCorrect": false}, {"text": "¡Prefiero comer pastel de manzana!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/caperucita_feliz.png"}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('7725554a-6d14-447f-9851-a5ad3efb4c95', '2026-11-19 12:31:19.699993-03', '2026-11-19 12:31:19.699993-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El Cazador", "Lobo Feroz", "La Abuelita", "Caperucita", "El Leñador"], "imageSrc": "assets/images/pixelado/lobo_disfrazado.png", "correctCharacter": "Lobo Feroz"}], "total_time": 7}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('b83da91f-160c-4eb6-961b-5709c43bf7b7', '2026-11-19 12:31:19.701025-03', '2026-11-19 12:31:19.701025-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["El Leñador", "El Cazador", "El Lobo", "El Padre", "El Guardabosques"], "imageSrc": "assets/images/pixelado/cazador_bosque.png", "correctCharacter": "El Cazador"}], "total_time": 7}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('9a2c3a7c-9407-4ced-8c09-47e642856a1a', '2026-11-19 12:31:19.702992-03', '2026-11-19 12:31:19.702992-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 101, "altText": "Caperucita con capa roja", "imageSrc": "assets/images/contra/caperucita_roja_1.png", "isContradiction": false}, {"id": 102, "altText": "Canasta con pan", "imageSrc": "assets/images/contra/caperucita_canasta.png", "isContradiction": false}, {"id": 103, "altText": "Caperucita vistiendo capa azul", "imageSrc": "assets/images/contra/caperucita_azul.png", "isContradiction": true}, {"id": 104, "altText": "Camino en el bosque", "imageSrc": "assets/images/contra/bosque_camino.png", "isContradiction": false}], "explanation": "La imagen de contradicción muestra a Caperucita con una capa azul brillante.", "premiseText": "Caperucita vestía una capa roja y llevaba una canasta con pan y miel para su abuelita."}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('c568a0a9-0513-4fa0-a9de-a13a949b3d07', '2026-11-19 12:31:19.704022-03', '2026-11-19 12:31:19.704022-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 105, "altText": "Lobo con gorro de dormir", "imageSrc": "assets/images/contra/lobo_gorro.png", "isContradiction": false}, {"id": 106, "altText": "Casa de la abuelita", "imageSrc": "assets/images/contra/casa_abuela.png", "isContradiction": false}, {"id": 107, "altText": "Lobo vistiendo una corona de rey", "imageSrc": "assets/images/contra/lobo_corona.png", "isContradiction": true}, {"id": 108, "altText": "Cama de la abuelita", "imageSrc": "assets/images/contra/cama_abuela.png", "isContradiction": false}], "explanation": "La contradicción muestra al lobo usando una corona de rey en lugar del gorro de dormir.", "premiseText": "El lobo feroz llegó primero a la casa de la abuelita y se disfrazó con su gorro de dormir."}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('041cd133-cc67-405f-8749-bb40c6a1e8f3', '2026-11-19 12:31:19.706992-03', '2026-11-19 12:31:19.706992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El encuentro en el bosque", "fragments": [{"id": 1, "text": "Caperucita recibe la canasta de comida y se despide cariñosamente de su madre."}, {"id": 2, "text": "Al entrar al bosque, se distrae juntando flores silvestres a la orilla del camino."}, {"id": 3, "text": "Un lobo astuto se le acerca con amabilidad y le pregunta hacia dónde se dirige."}, {"id": 4, "text": "La niña le confiesa ingenuamente que va a visitar a su abuelita enferma."}, {"id": 5, "text": "El lobo le sugirió tomar el camino más largo mientras él corre por el atajo."}]}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('533f3b65-0537-4e1f-abeb-49b45aef9ab0', '2026-11-19 12:31:19.707992-03', '2026-11-19 12:31:19.707992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El rescate en la cabaña", "fragments": [{"id": 1, "text": "El lobo entra a la casa de la abuela, la encierra y se viste con su ropa de dormir."}, {"id": 2, "text": "Caperucita llega a la cabaña y nota sorprendida el gran tamaño de los ojos de su abuela."}, {"id": 3, "text": "Al preguntar por sus enormes dientes, el lobo salta de la cama para atraparla."}, {"id": 4, "text": "Los fuertes gritos de auxilio de la niña son escuchados por un leñador cercano."}, {"id": 5, "text": "El leñador entra rápidamente a la casa, libra a la abuela y espanta al lobo para siempre."}]}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('d9c6c1a3-5e48-441e-acc3-746b59946f4a', '2026-11-19 12:31:19.709993-03', '2026-11-19 12:31:19.709993-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["orejas", "manos", "zapatos", "sombreros"], "timeLeft": 7.0, "textAfter": "tan grandes tienes, abuelita! —dijo la niña extrañada.", "textBefore": "¡Qué", "correctWord": "orejas"}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('a615a646-3997-4a2a-8658-d6508506abc2', '2026-11-19 12:31:19.711018-03', '2026-11-19 12:31:19.711018-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["oírte", "comerte", "abrazarte", "mirarte"], "timeLeft": 7.0, "textAfter": "mejor —respondió el lobo disfrazado en la cama.", "textBefore": "¡Qué orejas tan grandes tienes! —Son para", "correctWord": "oírte"}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('e0d5ca2c-121d-48c2-aff8-2ec24a86ee7f', '2026-11-19 12:31:19.732992-03', '2026-11-19 12:31:19.732992-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Aquí dentro el lobo no podrá hacernos nada!", "isCorrect": true}, {"text": "¡Tengo que construir otra casa de paja!", "isCorrect": false}, {"text": "¡El lobo es nuestro nuevo amigo!", "isCorrect": false}, {"text": "¡Salgamos a jugar al jardín!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/cerdito_aliviado.png"}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('227a374d-959f-47e5-9dc0-33175c12489d', '2026-11-19 12:31:19.713995-03', '2026-11-19 12:31:19.713995-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "Caperucita Roja", "imageUrl": "assets/images/testigo/caperucita_bosque.png", "questions": [{"prompt": "¿De qué color es la capa/caperuza de la niña?", "options": ["Rojo", "Azul", "Verde", "Amarillo"], "correctOption": "Rojo"}, {"prompt": "¿Qué animal aparece acechando en la escena?", "options": ["El Lobo", "El Oso", "El Zorro", "El Cazador"], "correctOption": "El Lobo"}, {"prompt": "¿Qué objeto lleva Caperucita en la mano/brazo?", "options": ["Una canasta", "Un farol", "Un paraguas", "Un libro"], "correctOption": "Una canasta"}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('1b90141b-9617-4db4-bbdd-b43349e510a8', '2026-11-19 12:31:19.715993-03', '2026-11-19 12:31:19.715993-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "Cabaña de la Abuela", "imageUrl": "assets/images/testigo/casa_abuelita.png", "questions": [{"prompt": "¿Qué objeto había sobre la mesa junto a la cama de la abuela?", "options": ["Un florero con rosas", "Una lámpara encendida", "Un vaso de agua", "Un libro abierto"], "correctOption": "Un florero con rosas"}, {"prompt": "¿Qué prenda llevaba puesta el personaje recostado?", "options": ["Un gorro de dormir", "Una corona", "Un sombrero de paja", "Un casco"], "correctOption": "Un gorro de dormir"}, {"prompt": "¿De qué color eran las cortinas de la ventana de la cabaña?", "options": ["Rojas con cuadros blancos", "Verdes lisas", "Azules con flores", "Amarillas"], "correctOption": "Rojas con cuadros blancos"}]}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('f78ab17f-5488-4d22-85ce-b8af535196cc', '2026-11-19 12:31:19.718993-03', '2026-11-19 12:31:19.718993-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Cesta de pan", "imageUrl": "assets/images/cazador-intrusos/cesta-pan.png", "isIntruder": false}, {"id": "item-2", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-3", "name": "Lobo disfrazado", "imageUrl": "assets/images/cazador-intrusos/lobo-disfrazado.png", "isIntruder": false}, {"id": "item-4", "name": "Manta roja", "imageUrl": "assets/images/cazador-intrusos/manta-roja.png", "isIntruder": false}, {"id": "item-5", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-6", "name": "Extintor de incendios", "imageUrl": "assets/images/cazador-intrusos/extintor-incendios.png", "isIntruder": true}], "title": "La Cabaña de la Abuela", "bgImageUrl": "assets/images/cazador-intrusos/cabana-abuela-bg.jpg", "textDescription": "Al entrar en la cabaña, Caperucita vio a su abuela recostada bajo una manta roja en su cama de madera. Sobre la mesa descansaba la cesta de pan, mientras el lobo disfrazado observaba pacientemente."}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('db166824-8540-4ca2-b571-8645e8b647c3', '2026-11-19 12:31:19.719992-03', '2026-11-19 12:31:19.719992-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Capa roja", "imageUrl": "assets/images/cazador-intrusos/capa-roja.png", "isIntruder": false}, {"id": "item-2", "name": "Flores silvestres", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-3", "name": "Mariposas", "imageUrl": "assets/images/cazador-intrusos/mariposa.png", "isIntruder": false}, {"id": "item-4", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-5", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-6", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}], "title": "El Sendero del Bosque", "bgImageUrl": "assets/images/cazador-intrusos/bosque-bg.jpg", "textDescription": "Caperucita caminaba entre los frondosos árboles llevando su capa roja, rodeada de hermosas flores silvestres y pequeñas mariposas que volaban a su alrededor."}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('95ccef80-fd80-4e69-ae08-da57e3e81fc9', '2026-11-19 12:31:19.722991-03', '2026-11-19 12:31:19.722991-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/caperucita-cesta.jpg", "storyTitle": "Caperucita Roja", "targetArea": {"top": 26, "left": 60, "width": 15, "height": 15}, "textSnippet": "Oculta entre las gruesas ramas del gran roble en medio del bosque, una pequeña cesta con manzanas descansaba olvidada.", "targetObjectName": "Cesta con manzanas"}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('d1988218-63c4-425e-bdb3-9deb94419d62', '2026-11-19 12:31:19.723993-03', '2026-11-19 12:31:19.723993-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/caperucita-dormitorio.jpg", "storyTitle": "Caperucita Roja", "targetArea": {"top": 29, "left": 72, "width": 26, "height": 26}, "textSnippet": "Asomado detrás de la cortina del dormitorio, se podían ver las puntiagudas orejas del lobo acechando la llegada de la niña.", "targetObjectName": "Gorro del lobo"}', 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
