INSERT INTO public.games_bookminigame VALUES ('f98cee8f-96d4-490e-a85b-e6566cbe1b7f', '2026-11-19 12:31:19.729992-03', '2026-11-19 12:31:19.729992-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El primer cerdito hizo su casa de madera.", "isTrue": false}, {"text": "El hermano mayor usó ladrillos.", "isTrue": true}, {"text": "La casa de paja se construyó muy rápido.", "isTrue": true}], "passage_text": "El primer cerdito construyó su casa de paja rápidamente para irse a jugar, mientras que el hermano mayor trabajó duro en su casa de ladrillos.", "time_per_statement": 7}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('0c5b551c-8b2b-41f9-8252-c61beeb5036e', '2026-11-19 12:31:19.730993-03', '2026-11-19 12:31:19.730993-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El lobo derribó la casa de ladrillo.", "isTrue": false}, {"text": "La casa de madera se cayó con el soplido.", "isTrue": true}, {"text": "El lobo usó un martillo para romper las casas.", "isTrue": false}], "passage_text": "El lobo sopló y sopló hasta derrumbar las casas de paja y madera, pero la casa de ladrillo resistió sin moverse.", "time_per_statement": 7}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('d798484a-d1be-42e1-ae0f-6ca97e2c6dc7', '2026-11-19 12:31:19.731993-03', '2026-11-19 12:31:19.731993-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Soplaré y soplaré y tu casa derribaré!", "isCorrect": true}, {"text": "¡Por favor, déjame entrar a tomar té!", "isCorrect": false}, {"text": "¡Construyeron una linda casa!", "isCorrect": false}, {"text": "¡Vengo a entregarles una carta!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/lobo_furioso.png"}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
