INSERT INTO public.games_bookminigame VALUES ('9a5369d1-bbda-473e-b9d4-c3895cd653ac', '2026-11-19 12:31:19.736992-03', '2026-11-19 12:31:19.736992-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 201, "altText": "Cerdito colocando ladrillos", "imageSrc": "assets/images/contra/cerdito_construyendo_ladrillos.png", "isContradiction": false}, {"id": 202, "altText": "Casa de ladrillos rojos", "imageSrc": "assets/images/contra/casa_ladrillos_roja.png", "isContradiction": false}, {"id": 203, "altText": "Casa de ladrillos verdes", "imageSrc": "assets/images/contra/casa_ladrillos_verde.png", "isContradiction": true}, {"id": 204, "altText": "Herramientas de albañil", "imageSrc": "assets/images/contra/herramientas_construccion.png", "isContradiction": false}], "explanation": "La imagen de contradicción muestra la casa pintada completamente de color verde brillante.", "premiseText": "El cerdito mayor trabajó duro colocando ladrillos rojos para construir una casa resistente."}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('dac5e8dc-d835-4152-8e76-e3ebe979b386', '2026-11-19 12:31:19.737992-03', '2026-11-19 12:31:19.737992-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 205, "altText": "Lobo soplando fuerte", "imageSrc": "assets/images/contra/lobo_soplando.png", "isContradiction": false}, {"id": 206, "altText": "Paja volando por el aire", "imageSrc": "assets/images/contra/casa_paja_volando.png", "isContradiction": false}, {"id": 207, "altText": "Lobo sosteniendo un secador de pelo", "imageSrc": "assets/images/contra/lobo_secador.png", "isContradiction": true}, {"id": 208, "altText": "Cerdito corriendo asustado", "imageSrc": "assets/images/contra/cerdito_huyendo.png", "isContradiction": false}], "explanation": "La contradicción muestra al lobo intentando derribar la casa soplando con un secador de pelo en lugar de su propia boca.", "premiseText": "El lobo intentó derribar la primera casa soplando con gran fuerza."}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('52feb185-15cf-4a94-977c-320670176116', '2026-11-19 12:31:19.739994-03', '2026-11-19 12:31:19.739994-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La construcción de los hogares", "fragments": [{"id": 1, "text": "Tres hermanos cerditos deciden construir sus propias casas en el campo."}, {"id": 2, "text": "El menor, perezoso, edifica una cabaña simple usando paja en pocos minutos."}, {"id": 3, "text": "El segundo hermano recolecta ramas secas y arma su casita de madera."}, {"id": 4, "text": "El hermano mayor trabaja duro todo el día colocando ladrillos y cemento."}, {"id": 5, "text": "Al caer la noche, los tres cerditos se refugian tranquilos en sus viviendas."}]}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('7321c786-f743-408d-bde4-8541fc7b1a45', '2026-11-19 12:31:19.740996-03', '2026-11-19 12:31:19.740996-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El soplo del lobo", "fragments": [{"id": 1, "text": "El lobo hambriento llega a la casa de paja y exige que le abran la puerta."}, {"id": 2, "text": "Sopla con fuerza y derriba la paja, haciendo correr al primer cerdito hacia la casa de madera."}, {"id": 3, "text": "El lobo sopla nuevamente y destruye la madera, obligando a los hermanos a huir."}, {"id": 4, "text": "Ambos se refugian en la sólida casa de ladrillo junto al hermano mayor."}, {"id": 5, "text": "El lobo sopla hasta cansarse pero no logra mover ni un solo ladrillo."}]}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('9b539ba3-6bf3-43e2-94e6-4d1e2fc0dc54', '2026-11-19 12:31:19.743993-03', '2026-11-19 12:31:19.743993-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["derribaré", "pintaré", "limpiaré", "abriré"], "timeLeft": 7.0, "textAfter": "! —gritó con fuerza el lobo feroz.", "textBefore": "¡Soplaré y soplaré y tu casa", "correctWord": "derribaré"}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
