INSERT INTO public.games_bookminigame VALUES ('0d387e0c-7bb9-4502-949f-8c006a524a63', '2026-11-19 12:31:19.747993-03', '2026-11-19 12:31:19.747993-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "Construcción de la Casa de Ladrillos", "imageUrl": "assets/images/testigo/construccion_ladrillo.png", "questions": [{"prompt": "¿Qué herramienta tenía el cerdito mayor en la mano?", "options": ["Una cuchara de albañil", "Un martillo", "Una pala", "Un serrucho"], "correctOption": "Una cuchara de albañil"}, {"prompt": "¿De qué color eran los ladrillos amontonados?", "options": ["Rojos", "Grises", "Amarillos", "Azules"], "correctOption": "Rojos"}, {"prompt": "¿Qué llevaba puesto en la cabeza el cerdito constructor?", "options": ["Un casco amarillo de protección", "Un gorro rojo", "Un sombrero de paja", "Nada"], "correctOption": "Un casco amarillo de protección"}]}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
