INSERT INTO public.games_bookminigame VALUES ('5a303eef-d61a-4a97-961c-7844a3e46f6c', '2026-11-19 12:31:19.810993-03', '2026-11-19 12:31:19.810993-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/bosque-migas.jpg", "storyTitle": "Hansel y Gretel", "targetArea": {"top": 61, "left": 63, "width": 25, "height": 25}, "textSnippet": "Oculto entre la densa hojarasca del camino, un pequeño pájaro blanco picoteaba las últimas migas de pan dejadas por Hansel.", "targetObjectName": "Pájaro blanco"}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('6868c978-375f-471b-8664-7581cb8a3a2e', '2026-11-19 12:31:19.750992-03', '2026-11-19 12:31:19.750992-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Ladrillos", "imageUrl": "assets/images/cazador-intrusos/ladrillos.png", "isIntruder": false}, {"id": "item-2", "name": "Balde de cemento", "imageUrl": "assets/images/cazador-intrusos/balde-cemento.png", "isIntruder": false}, {"id": "item-3", "name": "Cuchara de albañil", "imageUrl": "assets/images/cazador-intrusos/cuchara-albanil.png", "isIntruder": false}, {"id": "item-4", "name": "Regla de madera", "imageUrl": "assets/images/cazador-intrusos/regla-madera.png", "isIntruder": false}, {"id": "item-5", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-6", "name": "Secador de pelo", "imageUrl": "assets/images/cazador-intrusos/secador-pelo.png", "isIntruder": true}], "title": "El Taller del Cerdito Mayor", "bgImageUrl": "assets/images/cazador-intrusos/construccion-cerdito-bg.jpg", "textDescription": "En la zona de construcción, el cerdito mayor organizaba los materiales indispensables: un montón de sólidos ladrillos, un balde de cemento listo para usarse, una plana regla de madera y su cuchara de albañil."}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('b32a5283-98ec-4846-8c3d-c85a2ff89c2e', '2026-11-19 12:31:19.751993-03', '2026-11-19 12:31:19.751993-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Atado de paja", "imageUrl": "assets/images/cazador-intrusos/paja.png", "isIntruder": false}, {"id": "item-2", "name": "Tablones de madera", "imageUrl": "assets/images/cazador-intrusos/tablones.png", "isIntruder": false}, {"id": "item-3", "name": "Cuerda de amarre", "imageUrl": "assets/images/cazador-intrusos/cuerda.png", "isIntruder": false}, {"id": "item-4", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-5", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-6", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}], "title": "El Claro del Bosque", "bgImageUrl": "assets/images/cazador-intrusos/claro-bosque-bg.jpg", "textDescription": "Cerca del bosque, los dos hermanos menores preparaban sus hogares. Uno juntaba atados de paja seca mientras que el otro acomodaba tablones de madera resistente."}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('7857af4f-a9b1-4832-98e4-ede78dc128f0', '2026-11-19 12:31:19.752994-03', '2026-11-19 12:31:19.752994-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/casa-ladrillos.jpg", "storyTitle": "Los tres cerditos", "targetArea": {"top": 27, "left": 45, "width": 30, "height": 30}, "textSnippet": "Cerca de la parte superior de la resistente pared roja, sobresalía la chimenea por donde el lobo intentaría entrar.", "targetObjectName": "Chimenea de ladrillos"}', '1c177207-1c00-4208-b2d0-a641a78f4258', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
