INSERT INTO public.games_bookminigame VALUES ('358e2f53-d45f-4700-9d0f-9bbce56a9dd5', '2026-11-19 12:31:19.758993-03', '2026-11-19 12:31:19.758993-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El joven heredó un gran castillo.", "isTrue": false}, {"text": "El gato pidió unas botas y un saco.", "isTrue": true}, {"text": "El gato prometió ayudar a su dueño.", "isTrue": true}], "passage_text": "Un joven molinero heredó solo un gato, pero el animal le prometió que si le daba un par de botas y un saco, lo haría muy rico.", "time_per_statement": 7}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('d636d8b9-3db4-416a-8f86-4095e5aaf0d0', '2026-11-19 12:31:19.759992-03', '2026-11-19 12:31:19.759992-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El ogro se convirtió en un gran león primero.", "isTrue": true}, {"text": "El gato se hizo amigo del ogro.", "isTrue": false}, {"text": "El gato se comió al ogro transformado en ratón.", "isTrue": true}], "passage_text": "El gato engañó al malvado ogro pidiéndole que se convirtiera en un pequeño ratón, momento en el cual se lo comió para quedarse con su castillo.", "time_per_statement": 7}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('f39e6ad7-ba88-4ac8-83d9-5184f1382c3c', '2026-11-19 12:31:19.761991-03', '2026-11-19 12:31:19.761991-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Socorro! ¡El Marqués de Carabás se está ahogando en el río!", "isCorrect": true}, {"text": "¡Miren qué pez tan grande he atrapado para cenar!", "isCorrect": false}, {"text": "¡Hola Rey, venimos a cantar una hermosa canción!", "isCorrect": false}, {"text": "¡Tengo mucho frío, necesito que me presten ropa!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/gato_gritando.png"}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('39c4258e-9449-4351-8f10-d28fda37640c', '2026-11-19 12:31:19.762993-03', '2026-11-19 12:31:19.762993-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Puedo transformarme en un feroz y enorme león!", "isCorrect": true}, {"text": "¡Soy un pequeño ratoncito que busca queso!", "isCorrect": false}, {"text": "¡Bienvenidos a mi fiesta en el gran castillo!", "isCorrect": false}, {"text": "¡Me da mucho miedo la magia y los trucos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/ogro_fiero.png"}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
