INSERT INTO public.games_bookminigame VALUES ('378132a8-ac55-4987-bfb7-a4ad01b91f19', '2026-11-19 12:31:19.768992-03', '2026-11-19 12:31:19.768992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La herencia del molinero", "fragments": [{"id": 1, "text": "Un viejo molinero fallece dejando únicamente un astuto gato al menor de sus hijos."}, {"id": 2, "text": "El joven se lamenta por su suerte, temiendo no tener cómo ganarse la vida."}, {"id": 3, "text": "El gato habla con su amo y le pide un par de botas altas y una bolsa de tela."}, {"id": 4, "text": "El felino sale al monte y atrapa un conejo usando una trampa ingeniosa."}, {"id": 5, "text": "Lleva la presa al palacio real ofreciéndola como obsequio del Marqués de Carabás."}]}]}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('fa3efcf9-647d-4e83-8470-6e671b471358', '2026-11-19 12:31:19.769993-03', '2026-11-19 12:31:19.769993-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El encuentro con el Ogro", "fragments": [{"id": 1, "text": "El gato marcha hacia el castillo de un poderoso y temido ogro mago."}, {"id": 2, "text": "Desafía al ogro preguntándole si es capaz de transformarse en un gran león."}, {"id": 3, "text": "El ogro demuestra su poder convirtiéndose en una enorme fiera que asusta al gato."}, {"id": 4, "text": "El felino lo reta a convertirse en un animal diminuto como un simple ratón."}, {"id": 5, "text": "El ogro se transforma en ratón y el gato salta instantáneamente sobre él comiéndoselo."}]}]}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('57f55e36-95c0-458c-876a-f98185c8fa8b', '2026-11-19 12:31:19.771993-03', '2026-11-19 12:31:19.771993-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["botas", "monedas", "armas", "riendas"], "timeLeft": 7.0, "textAfter": "y veréis de lo que soy capaz.", "textBefore": "No os preocupéis, mi señor, solo dadme unas", "correctWord": "botas"}]}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('d073a6ff-550d-4999-9c7e-dc1fde631e35', '2026-11-19 12:31:19.772999-03', '2026-11-19 12:31:19.772999-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["Carabás", "Molinero", "Castillo", "Real"], "timeLeft": 7.0, "textAfter": "—dijo el gato al rey.", "textBefore": "Os entrego este regalo de parte del famoso Marqués de", "correctWord": "Carabás"}]}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('1f917d80-7c32-4b37-8781-25f4110548c7', '2026-11-19 12:31:19.774992-03', '2026-11-19 12:31:19.774992-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El Gato ante el Rey", "imageUrl": "assets/images/testigo/gato_rey.png", "questions": [{"prompt": "¿De qué color era la pluma del sombrero del gato?", "options": ["Roja", "Blanca", "Azul", "Dorada"], "correctOption": "Roja"}, {"prompt": "¿Qué animal traía el gato dentro de su saco?", "options": ["Un conejo", "Un pato", "Un pez", "Un ratón"], "correctOption": "Un conejo"}, {"prompt": "¿Qué accesorio llevaba el Rey en sus manos?", "options": ["Un cetro dorado", "Una espada", "Un mapa del reino", "Un abanico"], "correctOption": "Un cetro dorado"}]}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
