INSERT INTO public.games_bookminigame VALUES ('ca11d701-b790-4c5d-94c8-96def511876c', '2026-11-19 12:31:19.780995-03', '2026-11-19 12:31:19.780995-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/gato-trono.jpg", "storyTitle": "El gato con botas", "targetArea": {"top": 83, "left": 69, "width": 30, "height": 30}, "textSnippet": "Junto al trono real, ocultas a la sombra de los pesados mantos del rey, relucían las botas de cuero bien lustradas del minino.", "targetObjectName": "Botas del gato"}', '1dc4012c-e28d-434b-8b29-8a3934a3d9bf', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
