INSERT INTO public.games_bookminigame VALUES ('5f4970be-3965-4d27-9a17-64eb144ec107', '2026-11-19 12:31:19.787994-03', '2026-11-19 12:31:19.787994-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Hansel usó piedras blancas la primera vez.", "isTrue": true}, {"text": "Los pájaros se comieron las migas de pan.", "isTrue": true}, {"text": "Los niños encontraron el camino fácilmente.", "isTrue": false}], "passage_text": "Hansel lanzó migas de pan al suelo para recordar el camino de regreso a casa, pero los pájaros del bosque se las comieron todas.", "time_per_statement": 7}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('b684b5a4-5f43-4d22-9a71-98fd13e881e7', '2026-11-19 12:31:19.788995-03', '2026-11-19 12:31:19.788995-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La casa estaba hecha de madera vieja.", "isTrue": false}, {"text": "Una amable abuelita vivía en la casa.", "isTrue": false}, {"text": "La casa estaba cubierta de dulces.", "isTrue": true}], "passage_text": "En medio del bosque encontraron una casita hecha de caramelos y chocolates. La anciana que vivía allí era en realidad una bruja malvada.", "time_per_statement": 7}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('da9a7fa4-87e5-411b-9e46-1de844f83cde', '2026-11-19 12:31:19.790993-03', '2026-11-19 12:31:19.790993-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Niños, entren a comer unos dulces!", "isCorrect": true}, {"text": "¡Sálvenme de este bosque oscuro!", "isCorrect": false}, {"text": "¡No toquen mi casa de madera!", "isCorrect": false}, {"text": "¡Voy a regalarles mi varita mágica!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/bruja_malvada.png"}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('3e44e8b0-496b-49c8-8cb4-e56968697afb', '2026-11-19 12:31:19.791992-03', '2026-11-19 12:31:19.791992-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡No sé cómo mirar dentro del horno, enséñame cómo entra una persona!", "isCorrect": true}, {"text": "¡Bruja, voy a prepararte una sopa deliciosa!", "isCorrect": false}, {"text": "¡Déjame salir corriendo a buscar ayuda al bosque!", "isCorrect": false}, {"text": "¡Quiero encender el fuego para cocinar pan!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/gretel_valiente.png"}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
