INSERT INTO public.games_bookminigame VALUES ('0115383f-d6dd-42b5-b304-4160f6e7dcf0', '2026-11-19 12:31:19.811992-03', '2026-11-19 12:31:19.811992-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/cocina-bruja.jpg", "storyTitle": "Hansel y Gretel", "targetArea": {"top": 54, "left": 66, "width": 29, "height": 29}, "textSnippet": "Cerca del gran horno de barro, amarrada a un clavo de la pared, colgaba la pesada llave dorada que abría la jaula de hierro.", "targetObjectName": "Llave de la jaula"}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('da94947b-2b88-491d-8b10-769b32ea2d47', '2026-11-19 12:31:19.796993-03', '2026-11-19 12:31:19.796993-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 405, "altText": "Casa hecha de golosinas", "imageSrc": "assets/images/contra/casa_dulce.png", "isContradiction": false}, {"id": 406, "altText": "Ventanas de azúcar", "imageSrc": "assets/images/contra/ventana_caramelo.png", "isContradiction": false}, {"id": 407, "altText": "Casa rústica de troncos", "imageSrc": "assets/images/contra/casa_madera_troncos.png", "isContradiction": true}, {"id": 408, "altText": "Techo de chocolate", "imageSrc": "assets/images/contra/techo_chocolate.png", "isContradiction": false}], "explanation": "La contradicción muestra una casa hecha completamente de troncos de madera.", "premiseText": "La casita del bosque estaba construida completamente de dulces, chocolates y galletas."}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('4970e3d6-3d6f-4316-a5bf-b4305f883640', '2026-11-19 12:31:19.798991-03', '2026-11-19 12:31:19.798991-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "Perdidos en la espesura", "fragments": [{"id": 1, "text": "Debido a la escasez de comida, los niños son llevados a lo profundo del bosque."}, {"id": 2, "text": "Hansel deja caer pequeños pedazos de pan en el sendero para recordar el regreso."}, {"id": 3, "text": "Al intentar volver, descubren desconsolados que los pájaros se comieron todas las migas."}, {"id": 4, "text": "Caminam sin rumbo durante días entre los densos árboles buscando refugio."}, {"id": 5, "text": "A lo lejos divisan una extraña casita hecha enteramente de pan de jengibre."}]}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('e30c0fc5-6478-4e9a-98b5-dbeac15127fe', '2026-11-19 12:31:19.799992-03', '2026-11-19 12:31:19.799992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El engaño a la bruja", "fragments": [{"id": 1, "text": "Una malvada bruja atrapa a Hansel en una jaula y pone a Gretel a cocinar."}, {"id": 2, "text": "Como la bruja ve muy poco, Hansel le muestra un hueso de pollo para simular estar flaco."}, {"id": 3, "text": "Cansada de esperar, la bruja decide encender el horno de barro para cocinarlo."}, {"id": 4, "text": "Gretel engaña a la bruja pidiéndole que le muestre cómo revisar el fuego."}, {"id": 5, "text": "La niña empuja a la bruja dentro del horno, libera a su hermano y huyen con perlas."}]}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('9fc51fd8-ef5d-4042-96bc-706ca1d31ac2', '2026-11-19 12:31:19.801993-03', '2026-11-19 12:31:19.801993-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["azúcar", "plástico", "piedra", "madera"], "timeLeft": 7.0, "textAfter": "transparente —dijo Hansel antes de probar un pedazo.", "textBefore": "¡Miren! La ventana de esta casa está hecha de", "correctWord": "azúcar"}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('f330fa9f-1006-45ce-b7dc-44c653f69c70', '2026-11-19 12:31:19.801993-03', '2026-11-19 12:31:19.801993-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["pastel", "zapato", "juguete", "sombrero"], "timeLeft": 7.0, "textAfter": "de chocolate —dijo la anciana a Gretel.", "textBefore": "Abre la boca y prueba este delicioso", "correctWord": "pastel"}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('e9bf2fcb-0c9c-447b-aa8c-2445e19fc2a7', '2026-11-19 12:31:19.803993-03', '2026-11-19 12:31:19.803993-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La Casa de Dulces", "imageUrl": "assets/images/testigo/casa_dulces_frente.png", "questions": [{"prompt": "¿De qué eran las paletas de la entrada de la casa de dulces?", "options": ["De espiral rosado y blanco", "De chocolate oscuro", "De caramelo azul", "De gelatina verde"], "correctOption": "De espiral rosado y blanco"}, {"prompt": "¿Qué dulce formaba las tejas del techo de la casita?", "options": ["Galletas de jengibre", "Chicles", "Gomitas de ositos", "Mermelada"], "correctOption": "Galletas de jengibre"}, {"prompt": "¿De qué material estaba hecha la cerca alrededor del jardín?", "options": ["Bastones de caramelo", "Barras de chocolate", "Madera barnizada", "Caramelos duros"], "correctOption": "Bastones de caramelo"}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('10e3639e-85cc-4997-8829-87b49ebbb1f9', '2026-11-19 12:31:19.804993-03', '2026-11-19 12:31:19.804993-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "En el Horno de la Bruja", "imageUrl": "assets/images/testigo/bruja_horno.png", "questions": [{"prompt": "¿Qué sostenía Gretel en la mano cerca del horno?", "options": ["Una escoba de paja", "Un plato de sopa", "Una llave de hierro", "Una varita"], "correctOption": "Una escoba de paja"}, {"prompt": "¿De qué material estaba hecha la puerta del horno iluminado?", "options": ["Hierro forjado oscuro", "Madera de roble", "Piedra tallada", "Cobre brillante"], "correctOption": "Hierro forjado oscuro"}, {"prompt": "¿Qué colgaba del techo sobre la zona del horno?", "options": ["Atados de hierbas secas", "Sartenes de cocina", "Jaulas de pájaros", "Candelabros de hierro"], "correctOption": "Atados de hierbas secas"}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('14a50c60-fc62-4f75-9b2f-c09253ccf7d4', '2026-11-19 12:31:19.806994-03', '2026-11-19 12:31:19.806994-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Pan de jengibre", "imageUrl": "assets/images/cazador-intrusos/jengibre.png", "isIntruder": false}, {"id": "item-2", "name": "Tejas de chocolate", "imageUrl": "assets/images/cazador-intrusos/chocolate.png", "isIntruder": false}, {"id": "item-3", "name": "Bastón de caramelo", "imageUrl": "assets/images/cazador-intrusos/baston-caramelo.png", "isIntruder": false}, {"id": "item-4", "name": "Caluga de manjar", "imageUrl": "assets/images/cazador-intrusos/caluga.png", "isIntruder": false}, {"id": "item-5", "name": "Hamburguesa con queso", "imageUrl": "assets/images/cazador-intrusos/hamburguesa.png", "isIntruder": true}, {"id": "item-6", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}], "title": "La Fachada Dulce", "bgImageUrl": "assets/images/cazador-intrusos/casa-dulce-bg.jpg", "textDescription": "Los niños sorprendidos contemplaron la fachada repleta de sabrosas golosinas: paredes hechas de pan de jengibre, tejas cubiertas de chocolate, bastones de caramelo flanqueando la puerta y calugas de manjar."}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('13e772b2-e8f9-4f89-8830-c29a42585779', '2026-11-19 12:31:19.807996-03', '2026-11-19 12:31:19.807996-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Horno de barro", "imageUrl": "assets/images/cazador-intrusos/horno.png", "isIntruder": false}, {"id": "item-2", "name": "Jaula de hierro", "imageUrl": "assets/images/cazador-intrusos/jaula.png", "isIntruder": false}, {"id": "item-3", "name": "Cofre de perlas", "imageUrl": "assets/images/cazador-intrusos/cofre.png", "isIntruder": false}, {"id": "item-4", "name": "Monopatín", "imageUrl": "assets/images/cazador-intrusos/monopatin.png", "isIntruder": true}, {"id": "item-5", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}, {"id": "item-6", "name": "Sartén eléctrico", "imageUrl": "assets/images/cazador-intrusos/sarten.png", "isIntruder": true}], "title": "Interior de la Cabaña", "bgImageUrl": "assets/images/cazador-intrusos/interior-bruja-bg.jpg", "textDescription": "Dentro de la cocina de la bruja se podía ver un gran horno de barro encendido, una jaula de hierro donde estaba Hansel y un cofre colmado de perlas y piedras preciosas."}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('3003950a-8f3d-4e77-a07c-02cdbba28893', '2026-11-19 12:31:19.813994-03', '2026-11-19 12:31:19.813994-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El Escape del Horno", "panels": [{"id": 1, "image": "assets/images/comics/hansel5.png"}, {"id": 2, "image": "assets/images/comics/hansel6.png"}, {"id": 3, "image": "assets/images/comics/hansel7.png"}, {"id": 4, "image": "assets/images/comics/hansel8.png"}]}', 'c8eb5df6-2ff9-4015-9da1-635b0ce04862', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('2ba86fab-fe7f-4f56-9aa2-5573b6d9c294', '2026-11-19 12:31:19.817992-03', '2026-11-19 12:31:19.817992-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El patito era idéntico a sus hermanos.", "isTrue": false}, {"text": "Los animales de la granja eran amables con él.", "isTrue": false}, {"text": "El patito decidió irse de la granja.", "isTrue": true}], "passage_text": "Un pequeño pajarito nació en un nido de patos. Era más grande y de color diferente a sus hermanos, por lo que todos en la granja se burlaban de él.", "time_per_statement": 7}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('a9bf6aa1-4142-4f17-895a-29c8885790e4', '2026-11-19 12:31:19.819022-03', '2026-11-19 12:31:19.819022-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El patito se convirtió en un gran ganso.", "isTrue": false}, {"text": "Se dio cuenta de su cambio al verse en el agua.", "isTrue": true}, {"text": "Se transformó en un hermoso cisne blanco.", "isTrue": true}], "passage_text": "Pasó el frío invierno y al llegar la primavera, el patito se miró en el reflejo del agua y descubrió que se había transformado en un hermoso cisne blanco.", "time_per_statement": 7}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c6665dba-b38e-4eca-95f2-2167019a2337', '2026-11-19 12:31:19.819991-03', '2026-11-19 12:31:19.819991-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "Nadie quiere jugar conmigo por ser diferente...", "isCorrect": true}, {"text": "¡Soy el pato más rápido del estanque!", "isCorrect": false}, {"text": "¡Qué bonita es mi granja!", "isCorrect": false}, {"text": "¡Me encanta nadar con mis hermanos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/patito_triste.png"}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('4fc52fde-35e5-42d4-b14f-aafd2b724cb2', '2026-11-19 12:31:19.820991-03', '2026-11-19 12:31:19.820991-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡No soy un pato feo, soy un cisne!", "isCorrect": true}, {"text": "¡Extraño ser un pequeño patito gris!", "isCorrect": false}, {"text": "¡Nunca aprenderé a volar!", "isCorrect": false}, {"text": "¡Quiero regresar a la granja de pollos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/cisne_majestuoso.png"}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('a1ef7510-4c71-48f0-b744-7795deef0d8b', '2026-11-19 12:31:19.821992-03', '2026-11-19 12:31:19.821992-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Mamá Pata", "Patito Feo", "Pollito", "Cisne", "Pavo Real"], "imageSrc": "assets/images/pixelado/patito_nacimiento.png", "correctCharacter": "Patito Feo"}], "total_time": 7}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('8573ad70-9a97-4d43-95c5-3a6fbee31601', '2026-11-19 12:31:19.823022-03', '2026-11-19 12:31:19.823022-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Bosque Nevado", "Granja de Animales", "Lago Congelado", "Nido de Pájaros", "Molino de Viento"], "imageSrc": "assets/images/pixelado/granja_animales.png", "correctCharacter": "Granja de Animales"}], "total_time": 7}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('ba504611-e346-4362-912c-b42227a41ab3', '2026-11-19 12:31:19.824992-03', '2026-11-19 12:31:19.824992-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 501, "altText": "Patito entre la nieve", "imageSrc": "assets/images/contra/patito_nieve.png", "isContradiction": false}, {"id": 502, "altText": "Estanque invernal", "imageSrc": "assets/images/contra/estanque_congelado.png", "isContradiction": false}, {"id": 503, "altText": "Patito en la playa tropical", "imageSrc": "assets/images/contra/patito_playa.png", "isContradiction": true}, {"id": 504, "altText": "Patito solo en el agua", "imageSrc": "assets/images/contra/patito_triste.png", "isContradiction": false}], "explanation": "La contradicción muestra al ave nadando bajo un sol de verano con palmeras alrededor.", "premiseText": "El pequeño ave nadaba solitario en el estanque durante la fría época de invierno."}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('6ee19f15-5928-43fe-ab13-36bce59382d4', '2026-11-19 12:31:19.826026-03', '2026-11-19 12:31:19.826026-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 505, "altText": "Patito nadando en el estanque", "imageSrc": "assets/images/contra/patito_nadando_estanque.png", "isContradiction": false}, {"id": 506, "altText": "Grupo de cisnes blancos", "imageSrc": "assets/images/contra/cisnes_blancos.png", "isContradiction": false}, {"id": 507, "altText": "Grupo de flamencos rosados", "imageSrc": "assets/images/contra/flamencos_rosados.png", "isContradiction": true}, {"id": 508, "altText": "Agua cristalina del estanque", "imageSrc": "assets/images/contra/agua_estanque.png", "isContradiction": false}], "explanation": "La imagen de contradicción muestra al patito nadando hacia un grupo de flamencos rosados en lugar de los cisnes blancos.", "premiseText": "El patito nadó alegremente hacia el centro del estanque para reunirse con los hermosos cisnes."}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('46959f3d-5492-4a58-b130-8ceda77156fe', '2026-11-19 12:31:19.827992-03', '2026-11-19 12:31:19.827992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El nacimiento en el corral", "fragments": [{"id": 1, "text": "Una mamá pato incuba sus huevos en un nido escondido cerca del estanque."}, {"id": 2, "text": "El último huevo en romper el cascarón revela un pajarillo grande y gris."}, {"id": 3, "text": "Las demás aves de la granja lo molestan constantemente por su apariencia."}, {"id": 4, "text": "El triste patito decide huir durante la noche para no estorbar a su familia."}, {"id": 5, "text": "Vaga sin destino soportando heladas y tempestades a lo largo de los meses."}]}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('977078d8-e8f3-4269-946b-5156c6469c98', '2026-11-19 12:31:19.827992-03', '2026-11-19 12:31:19.827992-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La transformación primaveral", "fragments": [{"id": 1, "text": "El sol vuelve a brillar marcando el inicio de una cálida primavera."}, {"id": 2, "text": "El patito despliega sus alas descubriendo que son más fuertes y grandes."}, {"id": 3, "text": "Aterriza en un lago donde ve nadar a tres majestuosas aves blancas."}, {"id": 4, "text": "Baja la cabeza con timidez y observa atentamente su propio reflejo en el cristalino agua."}, {"id": 5, "text": "Se da cuenta jubiloso de que no era un pato feo, sino un hermoso cisne."}]}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('e235f657-4195-45d1-b025-7c64c3d6abf0', '2026-11-19 12:31:19.829993-03', '2026-11-19 12:31:19.829993-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["primavera", "noche", "lluvia", "tormenta"], "timeLeft": 7.0, "textAfter": "y todo cambiará.", "textBefore": "No te preocupes por tu aspecto, pronto llegará la", "correctWord": "primavera"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('9aaae364-d648-47d0-b797-354b5106755e', '2026-11-19 12:31:19.830991-03', '2026-11-19 12:31:19.830991-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["cisne", "ganso", "halcón", "pavo"], "timeLeft": 7.0, "textAfter": "! —exclamó con alegría.", "textBefore": "¡Miren! ¡No soy un pato, soy un elegante", "correctWord": "cisne"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('684852dc-b54a-469b-95ef-83ff887692cb', '2026-11-19 12:31:19.831993-03', '2026-11-19 12:31:19.831993-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El Nacimiento en la Granja", "imageUrl": "assets/images/testigo/patito_nacimiento_escena.png", "questions": [{"prompt": "¿Cuántos patitos amarillos nacieron junto al patito feo?", "options": ["Cuatro", "Tres", "Cinco", "Dos"], "correctOption": "Cuatro"}, {"prompt": "¿De qué color eran las plumas del patito feo al nacer?", "options": ["Gris", "Amarillo", "Blanco", "Negro"], "correctOption": "Gris"}, {"prompt": "¿Dónde se encontraba ubicado el nido de la mamá pata?", "options": ["Junto a un matorral cerca del agua", "Dentro del granero", "Sobre un montón de paja seca", "Bajo un puente de madera"], "correctOption": "Junto a un matorral cerca del agua"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('641f12c2-bff7-4b07-a3e1-5ed518636f2f', '2026-11-19 12:31:19.833002-03', '2026-11-19 12:31:19.833002-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El Reflejo en el Estanque", "imageUrl": "assets/images/testigo/cisne_reflejo.png", "questions": [{"prompt": "¿Qué planta florecía al lado del estanque cuando se vio en el agua?", "options": ["Lirios de agua", "Girasoles", "Rosas rojas", "Tulipanes"], "correctOption": "Lirios de agua"}, {"prompt": "¿Qué figura proyectaba el agua al mirar su propio reflejo?", "options": ["Un elegante cisne blanco", "Un pato gris", "Un ganso silvestre", "Un ave dorada"], "correctOption": "Un elegante cisne blanco"}, {"prompt": "¿Cómo estaba el clima al momento de mirarse en el estanque?", "options": ["Soleado de primavera", "Lluvioso de otoño", "Nevado de invierno", "Nublado"], "correctOption": "Soleado de primavera"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('6a14fb25-6044-41a2-bf03-2b28fd885bb2', '2026-11-19 12:31:19.834992-03', '2026-11-19 12:31:19.834992-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Mamá Pata", "imageUrl": "assets/images/cazador-intrusos/pata.png", "isIntruder": false}, {"id": "item-2", "name": "Gallina", "imageUrl": "assets/images/cazador-intrusos/gallina.png", "isIntruder": false}, {"id": "item-3", "name": "Pavo Real", "imageUrl": "assets/images/cazador-intrusos/pavo.png", "isIntruder": false}, {"id": "item-4", "name": "Ganso", "imageUrl": "assets/images/cazador-intrusos/ganso.png", "isIntruder": false}, {"id": "item-5", "name": "Pingüino de la Antártida", "imageUrl": "assets/images/cazador-intrusos/pinguino.png", "isIntruder": true}, {"id": "item-6", "name": "Submarino", "imageUrl": "assets/images/cazador-intrusos/submarino.png", "isIntruder": true}], "title": "El Corral de la Granja", "bgImageUrl": "assets/images/cazador-intrusos/corral-granja-bg.jpg", "textDescription": "En el concurrido corral convivían armoniosamente Mamá Pata encubando sus huevos, una gallina cacareando, un pavo real desplegando sus plumas y un pequeño ganso."}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('d9902582-75f5-4690-a9c6-0d41bbdd503d', '2026-11-19 12:31:19.835994-03', '2026-11-19 12:31:19.835994-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Juncos verdes", "imageUrl": "assets/images/cazador-intrusos/juncos.png", "isIntruder": false}, {"id": "item-2", "name": "Flores de lirio", "imageUrl": "assets/images/cazador-intrusos/lirios.png", "isIntruder": false}, {"id": "item-3", "name": "Cisne blanco", "imageUrl": "assets/images/cazador-intrusos/cisne.png", "isIntruder": false}, {"id": "item-4", "name": "Pista de esquí", "imageUrl": "assets/images/cazador-intrusos/esqui.png", "isIntruder": true}, {"id": "item-5", "name": "Raqueta de tenis", "imageUrl": "assets/images/cazador-intrusos/raqueta.png", "isIntruder": true}, {"id": "item-6", "name": "Lámpara de pie", "imageUrl": "assets/images/cazador-intrusos/lampara.png", "isIntruder": true}], "title": "El Lago Primaveral", "bgImageUrl": "assets/images/cazador-intrusos/lago-primaveral-bg.jpg", "textDescription": "Al llegar la primavera, el estanque brillaba rodeado de frondosos juncos verdes, hermosas flores de lirio flotando en el cristalino estanque y majestuosos cisnes blancos nadando en libertad."}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('fce97ffa-2704-401d-b1fa-82c34b1db39a', '2026-11-19 12:31:19.838994-03', '2026-11-19 12:31:19.838994-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/corral-huevos.jpg", "storyTitle": "El patito feo", "targetArea": {"top": 70, "left": 39, "width": 18, "height": 18}, "textSnippet": "Oculto entre la paja seca del rincón del corral, sobresalía un huevo considerablemente más grande que los demás.", "targetObjectName": "Huevo grande"}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('73c6d865-090e-40de-909b-5e0c5b763366', '2026-11-19 12:31:19.838994-03', '2026-11-19 12:31:19.838994-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/estanque-reflejo.jpg", "storyTitle": "El patito feo", "targetArea": {"top": 59, "left": 47, "width": 32, "height": 32}, "textSnippet": "Justo al centro del tranquilo estanque, la silueta reflejada de un esbelto cuello blanco se revelaba claramente sobre el agua.", "targetObjectName": "Reflejo del cisne"}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('5d9666e9-4b72-47aa-ab56-2991de8391f1', '2026-11-19 12:31:19.840991-03', '2026-11-19 12:31:19.840991-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Nacimiento y Rechazo", "panels": [{"id": 1, "image": "assets/images/comics/patito1.png"}, {"id": 2, "image": "assets/images/comics/patito2.png"}, {"id": 3, "image": "assets/images/comics/patito3.png"}, {"id": 4, "image": "assets/images/comics/patito4.png"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('3536c90a-5c56-4771-8a45-bb90641f6a1c', '2026-11-19 12:31:19.841994-03', '2026-11-19 12:31:19.841994-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La Transformación", "panels": [{"id": 1, "image": "assets/images/comics/patito5.png"}, {"id": 2, "image": "assets/images/comics/patito6.png"}, {"id": 3, "image": "assets/images/comics/patito7.png"}, {"id": 4, "image": "assets/images/comics/patito8.png"}]}', '8287b2a4-aad3-47e0-95e4-d70e13bd182c', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('78221a2a-efc6-40db-b6a1-c311cbf91754', '2026-11-19 12:31:20.960131-03', '2026-11-19 12:31:20.960131-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "La sirenita era la menor de seis hermanas.", "isTrue": true}, {"text": "La sirenita era hija del carpintero del mar.", "isTrue": false}, {"text": "La abuela les hablaba del mundo de los humanos.", "isTrue": true}], "passage_text": "La sirenita era la más joven de las seis hijas del rey del mar. Su abuela les contaba historias del mundo de los humanos", "time_per_statement": 7}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c4eb8efc-bc3c-44d1-8ee6-a8284d74ab25', '2026-11-19 12:31:20.971136-03', '2026-11-19 12:31:20.971136-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La sirenita salvó al príncipe de ahogarse.", "isTrue": true}, {"text": "Lo dejó en la orilla, cerca de un templo.", "isTrue": true}, {"text": "El príncipe se fue a vivir al fondo del mar.", "isTrue": false}], "passage_text": "Durante una tormenta, el barco del príncipe se hundió. La sirenita lo sostuvo sobre las olas y lo dejó en la orilla, cerca d eun templo.", "time_per_statement": 7}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('e5523cd7-5b76-4ec7-89fe-5fc23d38a2ac', '2026-11-19 12:31:20.973129-03', '2026-11-19 12:31:20.973129-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Quiero volver a dormir en mi concha!", "isCorrect": false}, {"text": "¡Qué hambre tengo, voy a pescar algo!", "isCorrect": false}, {"text": "¡Nunca había visto un barco tan hermoso, lleno de luces!", "isCorrect": true}, {"text": "¡Mi abuela me llama para cenar!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/sirenita_asombrada.png", "imageDescription": "La sirenita (cola de pez verde, cabello largo castaño) asomada sobre las olas de noche, con los ojos muy abiertos, mirando un gran barco iluminado con farolillos de colores."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('af094031-9c32-4e46-a78e-acac4bb68e8e', '2026-11-19 12:31:20.975132-03', '2026-11-19 12:31:20.975132-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Bienvenida a mi fiesta de cumpleaños!", "isCorrect": false}, {"text": "Te daré piernas, pero a cambio me entregarás tu hermosa voz.", "isCorrect": true}, {"text": "¡Qué lindo día para nadar con los delfines!", "isCorrect": false}, {"text": "¡Toma mi corona de perlas, es un regalo!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/bruja_del_mar.png", "imageDescription": "La bruja del mar, de aspecto misterioso, rodeada de serpientes de agua y pulpos, con una sonrisa maliciosa frente a un caldero burbujeante en una cueva submarina."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('5760274b-cc65-41fd-8295-a7dc91fefe24', '2026-11-19 12:31:20.976698-03', '2026-11-19 12:31:20.976698-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El rey del mar", "Un marinero", "El capitán del barco", "La bruja del mar", "El príncipe"], "imageSrc": "assets/images/pixelado/sirenita_principe_cubierta.png", "correctCharacter": "El príncipe", "imageDescription": "Joven príncipe de pie en la cubierta de su barco, de noche, con ropa elegante de fiesta y una capa azul, rodeado de farolillos de colores."}], "total_time": 7}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('e5b66f77-f9fc-4354-ad6f-a7c8241336b3', '2026-11-19 12:31:20.977198-03', '2026-11-19 12:31:20.977198-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["La cueva de la bruja", "El palacio del rey del mar", "Un templo en la orilla", "El barco del príncipe", "Un castillo en la montaña"], "imageSrc": "assets/images/pixelado/sirenita_palacio_coral.png", "correctCharacter": "El palacio del rey del mar", "imageDescription": "Palacio submarino de coral y conchas de colores, con torres de caracolas y algas ondulando alrededor, peces de colores nadando, luz azulada del fondo del mar."}], "total_time": 7}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('3a21809f-2bbf-4689-892c-4435c993974f', '2026-11-19 12:31:20.979207-03', '2026-11-19 12:31:20.979207-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 601, "altText": "Templo blanco junto a la orilla", "imageSrc": "assets/images/contra/sirenita_templo_orilla.png", "isContradiction": false, "imageDescription": "Un templo blanco con columnas junto a la playa, al amanecer."}, {"id": 602, "altText": "El príncipe sobre un árbol", "imageSrc": "assets/images/contra/sirenita_principe_arbol.png", "isContradiction": true, "imageDescription": "La sirenita en el agua, mirando hacia arriba, mientras el príncipe está acostado sobre la copa de un árbol cerca de la costa."}, {"id": 603, "altText": "La sirenita nadando con el príncipe", "imageSrc": "assets/images/contra/sirenita_nadando_principe.png", "isContradiction": false, "imageDescription": "La sirenita nadando entre olas llevando al príncipe inconsciente con la cabeza fuera del agua."}, {"id": 604, "altText": "El príncipe tendido en la arena", "imageSrc": "assets/images/contra/sirenita_principe_arena.png", "isContradiction": false, "imageDescription": "El príncipe dormido o inconsciente sobre la arena de una playa, con espuma de mar tocando sus pies."}], "explanation": "La imagen contradictoria muestra a la sirenita dejando al príncipe en la copa de un árbol en lugar de en la arena.", "premiseText": "La sirenita salvó al príncipe y lo dejó tendido sobre la arena de la orilla."}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('aa9bddf0-ba4e-4345-882a-0c19af3bd6f8', '2026-11-19 12:31:20.980187-03', '2026-11-19 12:31:20.980187-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 611, "altText": "Camino de algas viscosas", "imageSrc": "assets/images/contra/sirenita_camino_algas.png", "isContradiction": false, "imageDescription": "Un sendero sombrío entre algas verdes oscuras y pólipos viscosos en el fondo marino."}, {"id": 612, "altText": "Casa soleada con flores", "imageSrc": "assets/images/contra/sirenita_casa_flores.png", "isContradiction": true, "imageDescription": "Una casita luminosa y alegre con un jardín de flores rosadas y amarillas, bajo un sol brillante."}, {"id": 613, "altText": "Pulpos en el fondo oscuro", "imageSrc": "assets/images/contra/sirenita_pulpos.png", "isContradiction": false, "imageDescription": "Pulpos gigantes de tentáculos largos enredados entre algas oscuras en aguas muy oscuras."}, {"id": 614, "altText": "Caldero burbujeante", "imageSrc": "assets/images/contra/sirenita_caldero.png", "isContradiction": false, "imageDescription": "Un gran caldero negro hirviendo con burbujas verdes sobre un fuego azul, en una cueva."}], "explanation": "La imagen contradictoria muestra la casa de la bruja soleada, con un jardín lleno de flores de colores.", "premiseText": "La bruja del mar vivía en un lugar oscuro del fondo del océano, rodeada de pulpos y plantas viscosas."}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('0aaeb5be-801e-4b9b-b982-416ad2ecc21d', '2026-11-19 12:31:20.981197-03', '2026-11-19 12:31:20.981197-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La sirenita conoce al príncipe", "fragments": [{"id": 1, "text": "La sirenita cumple quince años y por fin puede subir a la superficie del mar."}, {"id": 2, "text": "Desde el agua observa un gran barco donde se celebra el cumpleaños de un apuesto príncipe."}, {"id": 3, "text": "Una terrible tormenta hunde el barco y el príncipe cae al mar."}, {"id": 4, "text": "La sirenita lo sostiene sobre las olas y lo deja a salvo en la orilla."}, {"id": 5, "text": "Una joven del templo cercano encuentra al príncipe y lo ayuda."}]}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('d6f95062-82dc-476f-aea5-c4a4cd9ec124', '2026-11-19 12:31:20.982197-03', '2026-11-19 12:31:20.982197-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El trato con la bruja", "fragments": [{"id": 1, "text": "La sirenita no puede olvidar al príncipe y desea vivir entre los humanos."}, {"id": 2, "text": "Viaja hasta la cueva de la bruja del mar, atravesando aguas peligrosas."}, {"id": 3, "text": "La bruja le prepara una poción a cambio de su hermosa voz."}, {"id": 4, "text": "La sirenita bebe la poción y su cola de pez se convierte en piernas."}, {"id": 5, "text": "El príncipe la encuentra en la playa y la lleva a su palacio."}]}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('4977638e-54e7-4579-97b3-a16119f9cc9d', '2026-11-19 12:31:20.984196-03', '2026-11-19 12:31:20.984196-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["débil", "hermosa", "grave", "ronca"], "timeLeft": 7.0, "textAfter": "de todo el océano.", "textBefore": "La sirenita tenía la voz más", "correctWord": "hermosa"}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('a86e6644-aafa-4e68-8b8d-08a082ab7af2', '2026-11-19 12:31:20.985196-03', '2026-11-19 12:31:20.985196-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["collar", "anillo", "voz", "corona"], "timeLeft": 7.0, "textAfter": "—dijo la bruja del mar.", "textBefore": "—Te daré piernas para caminar, pero a cambio me entregarás tu", "correctWord": "voz"}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('88589b4a-d88b-409b-a973-fafce94e4a1b', '2026-11-19 12:31:20.986195-03', '2026-11-19 12:31:20.986195-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El barco del príncipe", "imageUrl": "assets/images/testigo/sirenita_barco_noche.png", "questions": [{"prompt": "¿Qué iluminaba el barco?", "options": ["Farolillos de colores", "Un faro gigante", "Velas blancas pequeñas", "Antorchas rojas"], "correctOption": "Farolillos de colores"}, {"prompt": "¿Cuántos mástiles tenía el barco?", "options": ["Uno", "Tres", "Dos", "Cuatro"], "correctOption": "Tres"}, {"prompt": "¿De qué color era la capa del príncipe?", "options": ["Azul", "Roja", "Negra", "Verde"], "correctOption": "Azul"}], "imageDescription": "De noche, un gran barco de tres mástiles con velas blancas, iluminado por muchos farolillos de colores; en la cubierta, un príncipe de cabello oscuro con una capa azul; en el mar, la sirenita asomada mirando."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('14986cee-71d8-47ce-acd3-2510c30e9c9d', '2026-11-19 12:31:20.987195-03', '2026-11-19 12:31:20.987195-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El jardín de la sirenita", "imageUrl": "assets/images/testigo/sirenita_jardin_estatua.png", "questions": [{"prompt": "¿De qué material era la estatua?", "options": ["Hierro", "Oro", "Madera", "Mármol blanco"], "correctOption": "Mármol blanco"}, {"prompt": "¿De qué color eran las flores alrededor?", "options": ["Rojas", "Azules", "Amarillas", "Blancas"], "correctOption": "Rojas"}, {"prompt": "¿Cuántos peces amarillos se veían?", "options": ["Dos", "Tres", "Uno", "Cinco"], "correctOption": "Tres"}], "imageDescription": "Jardín submarino en el fondo del mar, con una estatua de mármol blanco de un joven en el centro, rodeada de flores de coral rojas; tres peces pequeños amarillos nadando; la sirenita sentada junto a la estatua."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('c4c6c4ad-2cef-4a28-8e45-77ff2365704b', '2026-11-19 12:31:20.989195-03', '2026-11-19 12:31:20.989195-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-2", "name": "Estrella de mar", "imageUrl": "assets/images/cazador-intrusos/estrella-mar.png", "isIntruder": false, "imageDescription": "Estrella de mar anaranjada de cinco puntas, estilo ilustración infantil, fondo transparente."}, {"id": "item-3", "name": "Coral rojo", "imageUrl": "assets/images/cazador-intrusos/coral-rojo.png", "isIntruder": false, "imageDescription": "Rama de coral rojo brillante con varias ramificaciones, fondo transparente."}, {"id": "item-4", "name": "Cofre del tesoro", "imageUrl": "assets/images/cazador-intrusos/cofre.png", "isIntruder": false}, {"id": "item-5", "name": "Submarino", "imageUrl": "assets/images/cazador-intrusos/submarino.png", "isIntruder": true}, {"id": "item-6", "name": "Concha con perla", "imageUrl": "assets/images/cazador-intrusos/concha-perla.png", "isIntruder": false, "imageDescription": "Concha marina rosada abierta con una perla blanca brillante en el centro, fondo transparente."}], "title": "El jardín de la sirenita", "bgImageUrl": "assets/images/cazador-intrusos/sirenita-jardin-bg.jpg", "textDescription": "En el fondo del mar, el jardín de la sirenita brillaba con estrellas de mar, corales rojos, un cofre hundido lleno de tesoros y una concha con una perla.", "bgImageDescription": "Fondo marino azul turquesa con rayos de luz desde la superficie, arena clara y algas suaves, sin objetos en primer plano (espacio libre para colocar 6 objetos)."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('b096c785-3b6e-4be1-bbed-76b8ad221bb6', '2026-11-19 12:31:20.990194-03', '2026-11-19 12:31:20.990194-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-2", "name": "Farolillos de colores", "imageUrl": "assets/images/cazador-intrusos/farolillos.png", "isIntruder": false, "imageDescription": "Tres farolillos de papel de colores (rojo, amarillo y azul) encendidos, colgando de una cuerda, fondo transparente."}, {"id": "item-3", "name": "Radio a pilas", "imageUrl": "assets/images/cazador-intrusos/radio.png", "isIntruder": true}, {"id": "item-4", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}, {"id": "item-5", "name": "Cuerda de barco", "imageUrl": "assets/images/cazador-intrusos/cuerda.png", "isIntruder": false}, {"id": "item-6", "name": "Tablones de madera", "imageUrl": "assets/images/cazador-intrusos/tablones.png", "isIntruder": false}], "title": "La fiesta en el barco", "bgImageUrl": "assets/images/cazador-intrusos/sirenita-barco-bg.jpg", "textDescription": "En la cubierta del barco del príncipe había gruesas cuerdas, tablones de madera pulida y farolillos de colores que alumbraban la fiesta.", "bgImageDescription": "Cubierta de un barco antiguo de noche, con mástil y velas blancas al fondo y cielo estrellado; piso de madera vacío para colocar objetos."}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('22c43f9b-c13f-4358-9064-ff029e0af339', '2026-11-19 12:31:20.991195-03', '2026-11-19 12:31:20.991195-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/sirenita-orilla.jpg", "storyTitle": "La sirenita", "targetArea": {"top": 15, "left": 10, "width": 30, "height": 50}, "textSnippet": "Entre las rocas de la orilla, medio cubierto por la espuma de las olas, asomaba el techo blanco del templo donde la sirenita dejó al príncipe.", "imageDescription": "Playa al amanecer con rocas, espuma y olas, y un barco lejano a la derecha. El templo blanco con columnas es grande y ocupa la parte superior izquierda, apoyado sobre las rocas; su blanco es algo más claro y su contorno más marcado que el resto de la playa. Escena muy recargada: la orilla está llena de conchas, estrellas de mar, cangrejos, gaviotas, otras rocas de formas parecidas, un velero cercano y varias olas con espuma.", "targetObjectName": "Templo blanco"}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('74d21393-65bd-41d1-b7c2-4463bdc31155', '2026-11-19 12:31:20.992195-03', '2026-11-19 12:31:20.992195-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/sirenita-gruta-bruja.jpg", "storyTitle": "La sirenita", "targetArea": {"top": 58, "left": 55, "width": 32, "height": 31.25}, "textSnippet": "Sobre el suelo arenoso de la gruta de la bruja, entre las algas oscuras, descansaba el caldero donde preparaba la poción.", "imageDescription": "Gruta submarina oscura con algas y algunos huesos blancos. En la parte inferior derecha, un caldero negro con burbujas verdes, con un leve resplandor verdoso que lo distingue del fondo.", "targetObjectName": "Caldero de la bruja"}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('eec7b20e-3cde-4322-85dd-e099f383d937', '2026-11-19 12:31:21.0306-03', '2026-11-19 12:31:21.0306-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El rey Buby", "La Reina Madre", "Ratón Pérez", "Un gato atigrado", "Gilito"], "imageSrc": "assets/images/pixelado/raton_perez_personaje.png", "correctCharacter": "Ratón Pérez", "imageDescription": "Ratón Pérez: ratoncito gris de pie, con sombrero de paja, lentes de oro redondos, zapatos de tela cruda y cartera roja cruzada en la espalda."}], "total_time": 7}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('fa333afc-73e5-4639-913f-daf4126d492d', '2026-11-19 12:31:20.993195-03', '2026-11-19 12:31:20.993195-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "El rescate del príncipe", "panels": [{"id": 1, "image": "assets/images/comics/sirenita1.png", "imageDescription": "La sirenita asoma sobre las olas de noche y mira un barco iluminado con farolillos de colores."}, {"id": 2, "image": "assets/images/comics/sirenita2.png", "imageDescription": "Una tormenta con rayos y olas gigantes hunde el barco; el príncipe cae al agua."}, {"id": 3, "image": "assets/images/comics/sirenita3.png", "imageDescription": "La sirenita nada llevando al príncipe inconsciente sobre las olas."}, {"id": 4, "image": "assets/images/comics/sirenita4.png", "imageDescription": "La sirenita deja al príncipe sobre la arena, junto a un templo blanco, y se esconde tras la espuma."}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('d23e67c2-bcc8-4c0f-8040-6f01f8639fdf', '2026-11-19 12:31:20.994195-03', '2026-11-19 12:31:20.994195-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El precio de las piernas", "panels": [{"id": 1, "image": "assets/images/comics/sirenita5.png", "imageDescription": "La sirenita entra a la cueva oscura de la bruja del mar, con un caldero al centro."}, {"id": 2, "image": "assets/images/comics/sirenita6.png", "imageDescription": "La bruja le entrega una poción brillante dentro de un frasco, y la sirenita le entrega su voz en forma de luz."}, {"id": 3, "image": "assets/images/comics/sirenita7.png", "imageDescription": "La sirenita bebe la poción sobre una playa, con su cola de pez brillando."}, {"id": 4, "image": "assets/images/comics/sirenita8.png", "imageDescription": "La sirenita, ya con piernas, de pie en la playa, mientras el príncipe se acerca sorprendido."}]}', '5998d33d-7853-4087-bc72-87a519fc238e', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('2e6947d7-baf8-47a4-ab5c-66fc3d85bad5', '2026-11-19 12:31:20.997415-03', '2026-11-19 12:31:20.997415-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Mowgli era un cachorro de hombre.", "isTrue": true}, {"text": "Madre Loba lo cuidó como a uno de sus hijos.", "isTrue": true}, {"text": "Mowgli llegó a la cueva de los osos.", "isTrue": false}], "passage_text": "Una noche, un pequeño cachorro de hombre llegó gateando hasta la cueva de los lobos. Madre Loba lo cuidó como a uno de sus propios cachorros y lo llamó Mowgli, que significa «la rana».", "time_per_statement": 7}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('21debcc4-883f-4772-b0a2-7cb09c1b4f26', '2026-11-19 12:31:20.998453-03', '2026-11-19 12:31:20.998453-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Shere Khan era un tigre.", "isTrue": true}, {"text": "Bagheera era un oso pardo.", "isTrue": false}, {"text": "Bagheera ofreció un toro para salvar a Mowgli.", "isTrue": true}], "passage_text": "El tigre Shere Khan quería llevarse al cachorro de hombre, pero Madre Loba no se lo permitió. La pantera Bagheera ofreció un toro recién cazado para que Mowgli pudiera quedarse.", "time_per_statement": 7}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('ab549d09-7698-4ea7-9a47-aa3a1bea2660', '2026-11-19 12:31:21.000424-03', '2026-11-19 12:31:21.000424-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Qué sueño tengo, me iré a dormir!", "isCorrect": false}, {"text": "¡Aquí tienes al cachorro, llévatelo!", "isCorrect": false}, {"text": "¡Tigre, pasa y cena con nosotros!", "isCorrect": false}, {"text": "¡El cachorro de hombre es mío! ¡No te lo llevarás!", "isCorrect": true}], "emotionImage": "assets/images/emoticono/mowgli_madre_loba.png", "imageDescription": "Madre Loba, una loba gris de ojos brillantes, protegiendo con su cuerpo a un bebé humano dentro de una cueva y mostrando los colmillos hacia la entrada."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('9a9c5fdb-9fdb-40fb-be2a-2c1aade0f460', '2026-11-19 12:31:21.001423-03', '2026-11-19 12:31:21.001423-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Les traje un regalo para el cachorro!", "isCorrect": false}, {"text": "¡Qué linda cueva, me quedaré a vivir aquí!", "isCorrect": false}, {"text": "¡Entregadme al cachorro de hombre, es mi presa!", "isCorrect": true}, {"text": "¡Me siento muy solo y triste!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/mowgli_shere_khan.png", "imageDescription": "Un gran tigre de Bengala que cojea de una pata trasera, rugiendo furioso en la entrada de una cueva, con la selva de fondo."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('c4d0e5c1-5710-48ae-b331-135aa8739af3', '2026-11-19 12:31:21.002423-03', '2026-11-19 12:31:21.002423-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Tabaqui", "Shere Khan", "Baloo", "Akela", "Bagheera"], "imageSrc": "assets/images/pixelado/mowgli_baloo.png", "correctCharacter": "Baloo", "imageDescription": "Baloo, un oso pardo grande y simpático, sentado en la selva, sonriendo, con hojas y lianas detrás."}], "total_time": 7}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('a78dfd36-2c42-4317-95a3-a44024fae3eb', '2026-11-19 12:31:21.003424-03', '2026-11-19 12:31:21.003424-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Bagheera", "Shere Khan", "Baloo", "Madre Loba", "Akela"], "imageSrc": "assets/images/pixelado/mowgli_bagheera.png", "correctCharacter": "Bagheera", "imageDescription": "Bagheera, una pantera negra elegante, sentada sobre una rama gruesa en la selva, con ojos verdes brillantes."}], "total_time": 7}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('e9ee802e-edd9-438f-b54f-eb1daf107a80', '2026-11-19 12:31:21.005424-03', '2026-11-19 12:31:21.005424-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 621, "altText": "Huellas de tigre irregulares", "imageSrc": "assets/images/contra/mowgli_huellas_tigre.png", "isContradiction": false, "imageDescription": "Huellas de tigre grandes en el barro, con una de ellas más corta que las demás, en la orilla del río."}, {"id": 622, "altText": "Gatito con cascabel", "imageSrc": "assets/images/contra/mowgli_gatito.png", "isContradiction": true, "imageDescription": "Un gatito doméstico pequeño y atigrado con un collar con cascabel, sentado entre la hierba de la selva."}, {"id": 623, "altText": "Ojos de tigre en la oscuridad", "imageSrc": "assets/images/contra/mowgli_ojos_tigre.png", "isContradiction": false, "imageDescription": "Dos ojos amarillos brillando entre los arbustos de la selva de noche."}, {"id": 624, "altText": "Tigre enorme en la selva", "imageSrc": "assets/images/contra/mowgli_tigre_grande.png", "isContradiction": false, "imageDescription": "Un tigre de Bengala enorme caminando con una pata trasera coja entre la hierba alta."}], "explanation": "La imagen contradictoria muestra a Shere Khan como un pequeño gatito doméstico con un cascabel.", "premiseText": "Shere Khan era un enorme tigre que cojeaba de una pata."}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('dc58dc99-3166-44e9-85bb-cda0b8e81d9f', '2026-11-19 12:31:21.0326-03', '2026-11-19 12:31:21.0326-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Castillo de arena", "Casa de muñecas", "Botella de vidrio", "Caja de galletas", "Palacio Real"], "imageSrc": "assets/images/pixelado/raton_perez_caja_galletas.png", "correctCharacter": "Caja de galletas", "imageDescription": "Gran caja de galletas de lata redonda, con una puertita y ventanitas pequeñas, convertida en casa de ratones, dentro de un sótano con estantes de dulces."}], "total_time": 7}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('2275fa4f-24c3-4316-841f-b76140812a5a', '2026-11-19 12:31:21.006424-03', '2026-11-19 12:31:21.006424-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 631, "altText": "Madre Loba cuidando a Mowgli", "imageSrc": "assets/images/contra/mowgli_madre_loba_lame.png", "isContradiction": false, "imageDescription": "Una loba gris lamiendo la cabeza de un niño sentado entre sus cachorros."}, {"id": 632, "altText": "Cueva entre rocas", "imageSrc": "assets/images/contra/mowgli_cueva_lobos.png", "isContradiction": false, "imageDescription": "La entrada de una cueva entre rocas grandes con tres lobos descansando adentro."}, {"id": 633, "altText": "Mowgli jugando con lobeznos", "imageSrc": "assets/images/contra/mowgli_juega_lobeznos.png", "isContradiction": false, "imageDescription": "Un niño pequeño de pelo negro jugando con cachorros de lobo sobre la tierra frente a una cueva."}, {"id": 634, "altText": "Mowgli en un nido de águilas", "imageSrc": "assets/images/contra/mowgli_nido_aguilas.png", "isContradiction": true, "imageDescription": "Un niño de pelo negro durmiendo dentro de un enorme nido de ramas en la copa de un árbol altísimo, con águilas alrededor."}], "explanation": "La imagen contradictoria muestra a Mowgli durmiendo en un nido de águilas en la cima de un árbol.", "premiseText": "Mowgli, el cachorro de hombre, era criado por una familia de lobos dentro de una cueva."}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('b05e10f3-1ea8-4020-9e8d-334d8ec90456', '2026-11-19 12:31:21.007423-03', '2026-11-19 12:31:21.007423-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La llegada del cachorro de hombre", "fragments": [{"id": 1, "text": "Al caer la noche, Padre Lobo despierta y escucha las palabras del chacal Tabaqui."}, {"id": 2, "text": "Tabaqui le avisa que el tigre Shere Khan anda cazando cerca de la cueva."}, {"id": 3, "text": "Un niño pequeño llega gateando hasta la cueva de los lobos."}, {"id": 4, "text": "Shere Khan reclama al niño, pero Madre Loba lo defiende con fiereza."}, {"id": 5, "text": "Madre Loba decide criarlo junto a sus propios cachorros y lo llama Mowgli."}]}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('4caa1b75-c3e4-48da-a13a-c2b8841db569', '2026-11-19 12:31:21.008424-03', '2026-11-19 12:31:21.008424-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La Flor Roja", "fragments": [{"id": 1, "text": "Los años pasan y Mowgli crece fuerte, aprendiendo la Ley de la Selva con Baloo."}, {"id": 2, "text": "Akela, el viejo jefe, falla al cazar y la manada se prepara para quitarle el mando."}, {"id": 3, "text": "Bagheera le dice a Mowgli que debe traer la Flor Roja, el fuego, de la aldea de los hombres."}, {"id": 4, "text": "Mowgli llena una vasija de barro con brasas y regresa a la selva."}, {"id": 5, "text": "Con una rama encendida, Mowgli enfrenta a Shere Khan y se despide de la manada."}]}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('2b365e23-da48-4bb5-8f87-7826a9752223', '2026-11-19 12:31:21.010422-03', '2026-11-19 12:31:21.010422-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["tuyo", "de nadie", "mío", "perdido"], "timeLeft": 7.0, "textAfter": "! —gritó Madre Loba al tigre.", "textBefore": "—¡El cachorro de hombre es", "correctWord": "mío"}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('8977f131-22f7-4b9f-9f01-30d5eafc0ab1', '2026-11-19 12:31:21.011424-03', '2026-11-19 12:31:21.011424-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["fuego", "hielo", "agua", "viento"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "Bagheera le explicó que la Flor Roja era en realidad el", "correctWord": "fuego"}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('bfd2a7cf-2e5e-4ef9-a449-5c8b7379cdca', '2026-11-19 12:31:21.012457-03', '2026-11-19 12:31:21.012457-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El Consejo de la manada", "imageUrl": "assets/images/testigo/mowgli_consejo.png", "questions": [{"prompt": "¿Qué astro iluminaba la escena?", "options": ["La luna llena", "Una estrella fugaz", "El sol", "Un eclipse"], "correctOption": "La luna llena"}, {"prompt": "¿Qué animal negro estaba a un costado?", "options": ["Un caballo", "Un oso negro", "Una pantera", "Un gato doméstico"], "correctOption": "Una pantera"}, {"prompt": "¿Qué animal estaba de pie junto al niño?", "options": ["Un ciervo", "Un oso pardo", "Un mono", "Un elefante"], "correctOption": "Un oso pardo"}], "imageDescription": "De noche, sobre una roca grande y plana, un lobo gris viejo; alrededor, doce lobos sentados en círculo bajo una luna llena; a un costado, una pantera negra; junto a un niño pequeño, un oso pardo de pie."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('3a9b8305-cde0-4dce-8967-743b14630525', '2026-11-19 12:31:21.013425-03', '2026-11-19 12:31:21.013425-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La aldea de los hombres", "imageUrl": "assets/images/testigo/mowgli_aldea.png", "questions": [{"prompt": "¿De qué estaba hecha la vasija con fuego?", "options": ["Vidrio", "Metal", "Barro", "Madera"], "correctOption": "Barro"}, {"prompt": "¿De qué era el techo de la cabaña?", "options": ["Tejas rojas", "Madera", "Piedra", "Paja"], "correctOption": "Paja"}, {"prompt": "¿Qué animal flaco aparece junto a la cabaña?", "options": ["Una cabra", "Un perro", "Un gato", "Un cerdo"], "correctOption": "Un perro"}], "imageDescription": "Atardecer en una aldea; una cabaña de barro con techo de paja; frente a la puerta, una vasija de barro con brasas encendidas; un niño de pelo negro y largo mira escondido tras un arbusto; un perro flaco junto a la cabaña."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('f08ef53d-aa8f-4f58-b35a-f47560d12b4e', '2026-11-19 12:31:21.015423-03', '2026-11-19 12:31:21.015423-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Flores de la selva", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-2", "name": "Juncos del río", "imageUrl": "assets/images/cazador-intrusos/juncos.png", "isIntruder": false}, {"id": "item-3", "name": "Pantera negra", "imageUrl": "assets/images/cazador-intrusos/pantera-negra.png", "isIntruder": false, "imageDescription": "Pantera negra elegante sentada, de perfil, con ojos verdes brillantes, fondo transparente."}, {"id": "item-4", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-5", "name": "Mariposa", "imageUrl": "assets/images/cazador-intrusos/mariposa.png", "isIntruder": false}, {"id": "item-6", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}], "title": "La selva de Seeonee", "bgImageUrl": "assets/images/cazador-intrusos/mowgli-selva-bg.jpg", "textDescription": "La selva estaba llena de flores, mariposas y juncos junto al río, y entre las sombras se movía la silueta elegante de Bagheera, la pantera negra.", "bgImageDescription": "Selva densa y verde con un río al fondo y luz filtrada entre los árboles; suelo con hierba y espacio libre para colocar 6 objetos."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('f9fc1861-1b43-4b99-94c8-644c86c4ad7a', '2026-11-19 12:31:21.069321-03', '2026-11-19 12:31:21.069321-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["ortigas", "lana", "algodón", "seda"], "timeLeft": 7.0, "textAfter": "y no hablar hasta terminarlas.", "textBefore": "Para romper el hechizo, Elisa debía tejer once camisas con", "correctWord": "ortigas"}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('6ccfa690-d8e1-4764-8894-4c57c1725756', '2026-11-19 12:31:21.016471-03', '2026-11-19 12:31:21.016471-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Vasija de barro con brasas", "imageUrl": "assets/images/cazador-intrusos/vasija-brasas.png", "isIntruder": false, "imageDescription": "Vasija de barro marrón con brasas anaranjadas brillando en su interior, fondo transparente."}, {"id": "item-2", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-3", "name": "Rama encendida", "imageUrl": "assets/images/cazador-intrusos/rama-encendida.png", "isIntruder": false, "imageDescription": "Rama de árbol con la punta ardiendo con llamas naranjas, fondo transparente."}, {"id": "item-4", "name": "Tigre Shere Khan", "imageUrl": "assets/images/cazador-intrusos/tigre-bengala.png", "isIntruder": false, "imageDescription": "Tigre de Bengala grande, de pie y de perfil, con gesto de rugido, fondo transparente."}, {"id": "item-5", "name": "Secador de pelo", "imageUrl": "assets/images/cazador-intrusos/secador-pelo.png", "isIntruder": true}, {"id": "item-6", "name": "Extintor de incendios", "imageUrl": "assets/images/cazador-intrusos/extintor-incendios.png", "isIntruder": true}], "title": "La Flor Roja", "bgImageUrl": "assets/images/cazador-intrusos/mowgli-flor-roja-bg.jpg", "textDescription": "Mowgli corrió a la aldea y volvió con una vasija de barro llena de brasas y una rama encendida; Shere Khan, el tigre, lo esperaba entre la maleza.", "bgImageDescription": "Claro de la selva de noche, con luna llena, rocas y arbustos; suelo de tierra con espacio libre para colocar 6 objetos."}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('fabe3b60-09b2-49b4-aa39-6df1a49de253', '2026-11-19 12:31:21.018591-03', '2026-11-19 12:31:21.018591-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/mowgli-roca-consejo.jpg", "storyTitle": "Los hermanos de Mowgli", "targetArea": {"top": 10, "left": 35, "width": 30, "height": 50}, "textSnippet": "Sobre la gran Roca del Consejo, bajo la luz de la luna, el viejo lobo Akela esperaba en silencio.", "imageDescription": "Selva de noche con luna llena y una gran roca plana. Sobre la roca, en la parte central superior, un lobo gris viejo de pie, con un contorno de luz suave que lo distingue; abajo, otros lobos más pequeños sentados en círculo. Escena muy recargada: alrededor de la roca hay muchos lobos, lianas, helechos, luciérnagas, una pantera y un oso entre los árboles, y otras rocas redondeadas.", "targetObjectName": "Lobo Akela"}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('b95bfbf8-0de4-41c0-b68b-eda6cb6f9e7f', '2026-11-19 12:31:21.019601-03', '2026-11-19 12:31:21.019601-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/mowgli-orilla-rio.jpg", "storyTitle": "Los hermanos de Mowgli", "targetArea": {"top": 55, "left": 15, "width": 32, "height": 31.25}, "textSnippet": "Cerca de un tronco caído, junto al río, ardían las brasas de la vasija de barro de Mowgli.", "imageDescription": "Orilla de un río en la selva con un tronco caído y helechos. En la parte inferior izquierda, una vasija de barro con brasas anaranjadas brillando, que destaca levemente del terreno.", "targetObjectName": "Vasija de barro con brasas"}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('c14863c1-39ac-4733-876b-7b8097ee5018', '2026-11-19 12:31:21.0216-03', '2026-11-19 12:31:21.0216-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Un niño en la cueva", "panels": [{"id": 1, "image": "assets/images/comics/mowgli1.png", "imageDescription": "El chacal Tabaqui habla con Padre Lobo a la entrada de una cueva, al atardecer."}, {"id": 2, "image": "assets/images/comics/mowgli2.png", "imageDescription": "Un bebé humano gatea hacia la cueva, entre cachorros de lobo."}, {"id": 3, "image": "assets/images/comics/mowgli3.png", "imageDescription": "Shere Khan asoma su enorme cabeza por la entrada y Madre Loba lo enfrenta."}, {"id": 4, "image": "assets/images/comics/mowgli4.png", "imageDescription": "Madre Loba abraza al niño entre sus cachorros mientras el tigre se aleja."}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('4772b9a9-d125-4d42-b608-1c416fac9b1a', '2026-11-19 12:31:21.022599-03', '2026-11-19 12:31:21.022599-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La Flor Roja", "panels": [{"id": 1, "image": "assets/images/comics/mowgli5.png", "imageDescription": "Mowgli, ya mayor, escucha a Bagheera junto a una roca, de noche."}, {"id": 2, "image": "assets/images/comics/mowgli6.png", "imageDescription": "Mowgli corre hacia una aldea y llena una vasija de barro con brasas."}, {"id": 3, "image": "assets/images/comics/mowgli7.png", "imageDescription": "En el Consejo, Mowgli levanta una rama encendida frente a Shere Khan y los lobos."}, {"id": 4, "image": "assets/images/comics/mowgli8.png", "imageDescription": "Mowgli se aleja de la selva hacia la aldea mientras Baloo y Bagheera lo miran."}]}', 'be7dc7c0-764e-442c-8e4b-e13838298cba', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('ac92ccf1-26ab-4762-9a2e-f04072bac33c', '2026-11-19 12:31:21.025601-03', '2026-11-19 12:31:21.025601-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El rey Buby escribió una carta a Ratón Pérez.", "isTrue": true}, {"text": "Buby puso el diente bajo la almohada.", "isTrue": true}, {"text": "Buby guardó el diente en un cajón de su escritorio.", "isTrue": false}], "passage_text": "Al rey Buby se le cayó su primer diente. Siguiendo la costumbre, escribió una atenta carta a Ratón Pérez y puso la carta con el diente bajo su almohada.", "time_per_statement": 7}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('b543e6d6-8e74-49a2-a5cf-7a7c6d28d7f1', '2026-11-19 12:31:21.026599-03', '2026-11-19 12:31:21.026599-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Ratón Pérez vivía en una caja de galletas.", "isTrue": true}, {"text": "Ratón Pérez usaba sombrero de paja.", "isTrue": true}, {"text": "Ratón Pérez vivía en un castillo de piedra.", "isTrue": false}], "passage_text": "Ratón Pérez vivía con su familia en una caja de galletas, en el sótano de la confitería Prast. Era un ratón muy elegante, con sombrero de paja y lentes de oro.", "time_per_statement": 7}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('9aedd25b-c270-44e4-a252-d13c5899720e', '2026-11-19 12:31:21.0276-03', '2026-11-19 12:31:21.0276-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Hay un ratón con sombrero y lentes de oro sobre mi almohada!", "isCorrect": true}, {"text": "¡Mañana iré de paseo al campo con mi madre!", "isCorrect": false}, {"text": "¡Por fin terminé mis tareas del colegio!", "isCorrect": false}, {"text": "¡Qué rico estuvo el desayuno de hoy!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/raton_perez_buby_asustado.png", "imageDescription": "El pequeño rey Buby, con pijama y una corona, sentado en su cama con los ojos muy abiertos y asustado, mirando a un ratoncito con sombrero de paja y lentes que está de pie sobre su almohada."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('74651161-6e0c-46c9-8ca5-4bbff7975655', '2026-11-19 12:31:21.0296-03', '2026-11-19 12:31:21.0296-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "Buenas noches, Majestad; vengo a recoger su diente.", "isCorrect": true}, {"text": "¡Vengo a ayudarte a hornear una torta!", "isCorrect": false}, {"text": "¡Tengo frío, préstame tu abrigo!", "isCorrect": false}, {"text": "¡Fuera de aquí, ratón, no quiero verte!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/raton_perez_reverencia.png", "imageDescription": "Ratón Pérez, un ratoncito con sombrero de paja, lentes dorados, zapatos de tela y una cartera roja al hombro, quitándose el sombrero con una gran reverencia frente al rey, de noche."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('96617e3a-93f0-4107-a830-31cf8fb8e153', '2026-11-19 12:31:21.033631-03', '2026-11-19 12:31:21.033631-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 641, "altText": "Lentes de oro", "imageSrc": "assets/images/contra/raton_perez_lentes_oro.png", "isContradiction": false, "imageDescription": "Primer plano de la cara de un ratón con lentes redondos dorados."}, {"id": 642, "altText": "Ratón con casco de bombero", "imageSrc": "assets/images/contra/raton_perez_casco_bombero.png", "isContradiction": true, "imageDescription": "Un ratoncito con casco rojo de bombero y mochila verde, de pie."}, {"id": 643, "altText": "Cartera roja", "imageSrc": "assets/images/contra/raton_perez_cartera_roja.png", "isContradiction": false, "imageDescription": "Un ratón visto de espaldas con una cartera roja cruzada sobre la espalda."}, {"id": 644, "altText": "Sombrero de paja", "imageSrc": "assets/images/contra/raton_perez_sombrero_paja.png", "isContradiction": false, "imageDescription": "Un ratoncito gris con un sombrero de paja sobre la cabeza, de frente."}], "explanation": "La imagen contradictoria muestra a Ratón Pérez con casco de bombero y una mochila verde.", "premiseText": "Ratón Pérez llevaba un sombrero de paja, lentes de oro y una cartera roja."}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('a2320522-42e9-495f-97be-fbe86a1361e5', '2026-11-19 12:31:21.03522-03', '2026-11-19 12:31:21.03522-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 651, "altText": "Buby en el palacio", "imageSrc": "assets/images/contra/raton_perez_buby_palacio.png", "isContradiction": false, "imageDescription": "Un niño pequeño con corona de rey, parado en un gran salón de palacio con cortinas rojas."}, {"id": 652, "altText": "Palacio Real", "imageSrc": "assets/images/contra/raton_perez_palacio_madrid.png", "isContradiction": false, "imageDescription": "Fachada de un gran palacio de piedra clara con balcones y banderas, de día."}, {"id": 653, "altText": "Buby con su madre", "imageSrc": "assets/images/contra/raton_perez_buby_reina.png", "isContradiction": false, "imageDescription": "Un niño con corona abrazando a una reina con vestido azul y corona pequeña."}, {"id": 654, "altText": "Anciano en cabaña", "imageSrc": "assets/images/contra/raton_perez_anciano_cabana.png", "isContradiction": true, "imageDescription": "Un anciano de barba blanca larga y corona dorada sentado frente a una cabaña de madera en el bosque."}], "explanation": "La imagen contradictoria muestra a Buby como un anciano de barba larga viviendo en una cabaña del bosque.", "premiseText": "El rey Buby era un niño muy pequeño que vivía en un palacio de Madrid."}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('da602ada-831a-4e23-8d13-e39d73f17d05', '2026-11-19 12:31:21.036222-03', '2026-11-19 12:31:21.036222-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El diente del rey", "fragments": [{"id": 1, "text": "Al rey Buby se le cae su primer diente de leche."}, {"id": 2, "text": "La Reina Madre le aconseja escribir una atenta carta a Ratón Pérez."}, {"id": 3, "text": "Buby coloca la carta con el diente bajo su almohada y se queda esperando."}, {"id": 4, "text": "Ratón Pérez aparece sobre la almohada y saluda con una reverencia."}, {"id": 5, "text": "El rey, asombrado, se acerca a conversar con el ratoncito."}]}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('3a038ac8-0dfb-4793-9247-8bcb1e3486f5', '2026-11-19 12:31:21.038229-03', '2026-11-19 12:31:21.038229-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El viaje por Madrid", "fragments": [{"id": 1, "text": "Ratón Pérez explica que debe ir a recoger el diente de otro niño llamado Gilito."}, {"id": 2, "text": "El rey se vuelve tan pequeño como un ratón y sigue a Pérez por un agujero."}, {"id": 3, "text": "Ratón Pérez lo guía por agujeros y tuberías hasta el sótano de la confitería Prast."}, {"id": 4, "text": "Llegan a la caja de galletas, donde Buby conoce a la familia de Pérez."}, {"id": 5, "text": "Después van a la pobre casa de Gilito para recoger su diente."}]}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('aea77c51-f7a5-4e17-b037-f869dd51ec7d', '2026-11-19 12:31:21.039615-03', '2026-11-19 12:31:21.039615-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["guante", "abrigo", "zapato", "sombrero"], "timeLeft": 7.0, "textAfter": "hasta los pies y saludó al rey con una reverencia.", "textBefore": "Ratón Pérez se quitó el", "correctWord": "sombrero"}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('3ac3d4b3-b1ac-460e-8433-cb7100984161', '2026-11-19 12:31:21.040614-03', '2026-11-19 12:31:21.040614-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["Palacio", "Prast", "Luna", "Dulce"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "Ratón Pérez vivía en una caja de galletas, en el sótano de la confitería", "correctWord": "Prast"}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('351d3a89-cef1-4db6-9603-ac82b394d3ca', '2026-11-19 12:31:21.042615-03', '2026-11-19 12:31:21.042615-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La habitación del rey", "imageUrl": "assets/images/testigo/raton_perez_dormitorio.png", "questions": [{"prompt": "¿De qué color era el dosel de la cama?", "options": ["Amarillo", "Rojo", "Verde", "Azul"], "correctOption": "Azul"}, {"prompt": "¿Qué había sobre la mesita de noche?", "options": ["Una vela encendida", "Una lámpara eléctrica", "Un vaso de leche", "Un reloj despertador"], "correctOption": "Una vela encendida"}, {"prompt": "¿Qué había a los pies de la cama?", "options": ["Un violín", "Un perro", "Un balón", "Un osito de peluche"], "correctOption": "Un osito de peluche"}], "imageDescription": "Dormitorio de un niño rey, de noche: cama grande con dosel azul; sobre la almohada una carta cerrada con sello rojo y un pequeño diente; sobre la mesita de noche, una vela encendida; a los pies de la cama, un osito de peluche."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('3c2425dc-d4da-494a-ad5d-7dbba2e4b0fc', '2026-11-19 12:31:21.043501-03', '2026-11-19 12:31:21.043501-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La casa de Ratón Pérez", "imageUrl": "assets/images/testigo/raton_perez_casa_interior.png", "questions": [{"prompt": "¿De qué color era el delantal de la ratona?", "options": ["Azul", "Verde", "Blanco", "Rojo"], "correctOption": "Azul"}, {"prompt": "¿Qué comida había sobre la mesa?", "options": ["Sopa", "Trozos de queso", "Frutas", "Pescados"], "correctOption": "Trozos de queso"}, {"prompt": "¿De qué estaba hecha la lámpara?", "options": ["De una nuez", "De una taza", "De una cuchara", "De un dedal"], "correctOption": "De un dedal"}], "imageDescription": "Interior de una caja de galletas de lata convertida en casa de ratones: una ratona con delantal azul sirve la mesa, con trozos de queso; dos ratoncitas hijas (una con vestido rosa cantando, otra con lazo amarillo); una lámpara hecha con un dedal."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('57fbe7f7-4c25-4a04-9102-b0f1a4c2b020', '2026-11-19 12:31:22.372368-03', '2026-11-19 12:31:22.372368-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un faro", "Una torre de hielo", "El castillo cubierto de espinas", "Un palacio de oro", "Una casa de campo"], "imageSrc": "assets/images/pixelado/bella_castillo_espinas.png", "correctCharacter": "El castillo cubierto de espinas", "imageDescription": "Un castillo de piedra con torres, casi oculto por un denso seto de ramas espinosas con algunas rosas blancas."}], "total_time": 7}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('e9b3e0d5-e756-4c5c-a35a-19a081350418', '2026-11-19 12:31:21.04473-03', '2026-11-19 12:31:21.04473-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-2", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}, {"id": "item-3", "name": "Corona del rey", "imageUrl": "assets/images/cazador-intrusos/corona-rey.png", "isIntruder": false, "imageDescription": "Corona dorada con pequeñas joyas rojas y azules, tamaño pequeño, fondo transparente."}, {"id": "item-4", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-5", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-6", "name": "Carta con diente", "imageUrl": "assets/images/cazador-intrusos/carta-diente.png", "isIntruder": false, "imageDescription": "Carta cerrada con sello rojo y un diente pequeño apoyado sobre ella, fondo transparente."}], "title": "El dormitorio del rey Buby", "bgImageUrl": "assets/images/cazador-intrusos/raton-perez-dormitorio-bg.jpg", "textDescription": "En el dormitorio del pequeño rey había una cama de madera, una corona dorada y una carta con un diente esperando bajo la almohada.", "bgImageDescription": "Dormitorio infantil de palacio, de noche, con una ventana grande y una alfombra roja en el suelo, sin objetos pequeños (espacio libre para 6 objetos)."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('e93d5081-c76d-4829-a9ae-307c3107dd5b', '2026-11-19 12:31:21.046738-03', '2026-11-19 12:31:21.046738-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Lentes de oro", "imageUrl": "assets/images/cazador-intrusos/lentes-oro.png", "isIntruder": false, "imageDescription": "Lentes redondos con montura dorada, fondo transparente."}, {"id": "item-2", "name": "Caja de galletas", "imageUrl": "assets/images/cazador-intrusos/caja-galletas.png", "isIntruder": false, "imageDescription": "Caja de galletas de lata redonda y decorada, con una puertita pequeña recortada, fondo transparente."}, {"id": "item-3", "name": "Sombrero de paja", "imageUrl": "assets/images/cazador-intrusos/sombrero-paja.png", "isIntruder": false, "imageDescription": "Pequeño sombrero de paja con cinta marrón, fondo transparente."}, {"id": "item-4", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}, {"id": "item-5", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-6", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}], "title": "La casa de Ratón Pérez", "bgImageUrl": "assets/images/cazador-intrusos/raton-perez-sotano-bg.jpg", "textDescription": "En el sótano de la confitería, la casa de Ratón Pérez se veía rodeada de su sombrero de paja, sus lentes de oro y la gran caja de galletas.", "bgImageDescription": "Sótano de una confitería con estantes de madera y frascos de dulces, penumbra cálida, suelo de piedra con espacio libre para 6 objetos."}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('dbbcce04-7335-44d8-b680-6cc7be740acd', '2026-11-19 12:31:21.047738-03', '2026-11-19 12:31:21.047738-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/raton-perez-cama.jpg", "storyTitle": "Ratón Pérez", "targetArea": {"top": 35, "left": 45, "width": 50, "height": 30}, "textSnippet": "Bajo la almohada del rey, apenas asomaba una carta cerrada con un diente dentro.", "imageDescription": "Cama grande de rey vista desde arriba, con mantas azules y almohada blanca. En el centro-derecha, bajo la almohada, asoma una carta cerrada con sello rojo y un diente apoyado encima, con un contorno algo más marcado que las mantas. Escena muy recargada: la cama está llena de almohadones, peluches, libros, una corona, mantas con distintos dibujos y juguetes esparcidos.", "targetObjectName": "Carta con diente"}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('dd9c129e-4e85-46c8-84cf-37a962b9aa64', '2026-11-19 12:31:21.049833-03', '2026-11-19 12:31:21.049833-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/raton-perez-sotano.jpg", "storyTitle": "Ratón Pérez", "targetArea": {"top": 55, "left": 10, "width": 32, "height": 31.25}, "textSnippet": "En un rincón del sótano de la confitería, entre estantes de dulces, brillaba la caja de galletas donde vivía Ratón Pérez.", "imageDescription": "Sótano de confitería con estantes de frascos de dulces. En la parte inferior izquierda, una caja de galletas de lata con una puertita, de un tono algo más claro que el suelo y los estantes.", "targetObjectName": "Caja de galletas"}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('f4781a2b-0f2c-4b12-a826-d31f689c7c72', '2026-11-19 12:31:21.051739-03', '2026-11-19 12:31:21.051739-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La carta al ratón", "panels": [{"id": 1, "image": "assets/images/comics/raton_perez1.png", "imageDescription": "El rey Buby, un niño con corona, muestra con sorpresa su diente caído a su madre la reina."}, {"id": 2, "image": "assets/images/comics/raton_perez2.png", "imageDescription": "Buby escribe una carta con una pluma en su escritorio."}, {"id": 3, "image": "assets/images/comics/raton_perez3.png", "imageDescription": "Buby coloca la carta con el diente bajo su almohada y se acuesta."}, {"id": 4, "image": "assets/images/comics/raton_perez4.png", "imageDescription": "Ratón Pérez aparece sobre la almohada, con sombrero de paja y lentes de oro, y se inclina ante el rey."}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('6f29d54c-bb41-4af2-8acc-0a679f5b51ed', '2026-11-19 12:31:21.051739-03', '2026-11-19 12:31:21.05274-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La visita a la casa de Pérez", "panels": [{"id": 1, "image": "assets/images/comics/raton_perez5.png", "imageDescription": "Ratón Pérez toma de la mano al rey Buby, ya del tamaño de un ratón, junto a un agujero en la pared."}, {"id": 2, "image": "assets/images/comics/raton_perez6.png", "imageDescription": "Los dos caminan por una cañería oscura y estrecha."}, {"id": 3, "image": "assets/images/comics/raton_perez7.png", "imageDescription": "Llegan a una caja de galletas donde espera la familia de Pérez."}, {"id": 4, "image": "assets/images/comics/raton_perez8.png", "imageDescription": "Buby saluda a la ratona y a sus dos hijas, que lo reciben con alegría."}]}', '78b3a5bf-0ec7-45ce-8f02-7dd9d62d575c', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('a46c0727-16da-4eb1-818e-16d1b8c2146b', '2026-11-19 12:31:21.055738-03', '2026-11-19 12:31:21.055738-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Elisa tenía once hermanos.", "isTrue": true}, {"text": "La madrastra convirtió a los príncipes en cisnes.", "isTrue": true}, {"text": "Los príncipes eran cisnes solo durante la noche.", "isTrue": false}], "passage_text": "Elisa tenía once hermanos príncipes. Su cruel madrastra, la reina, los convirtió en cisnes salvajes que volaban de día y recuperaban su forma humana al caer la noche.", "time_per_statement": 7}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('80629fac-8b84-49bc-aa75-e2db4d730307', '2026-11-19 12:31:21.056738-03', '2026-11-19 12:31:21.056738-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Las camisas se tejieron con ortigas.", "isTrue": true}, {"text": "Elisa podía hablar mientras tejía.", "isTrue": false}, {"text": "Elisa tejió veinte camisas.", "isTrue": false}], "passage_text": "Para salvar a sus hermanos, Elisa tejió once camisas con ortigas, unas plantas que queman las manos. Mientras trabajaba, no podía pronunciar ni una sola palabra.", "time_per_statement": 7}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('82d06820-0f13-43ca-ae0d-68ae0e22c851', '2026-11-19 12:31:21.057739-03', '2026-11-19 12:31:21.057739-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Nunca he visto un cisne en mi vida!", "isCorrect": false}, {"text": "¡Son mis hermanos! ¡Esos once cisnes son mis hermanos!", "isCorrect": true}, {"text": "¡Qué lindo día para pescar!", "isCorrect": false}, {"text": "¡Estoy muy feliz de vivir en el palacio del rey!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/cisnes_elisa_reconoce.png", "imageDescription": "Elisa, una joven de cabello largo y vestido sencillo verde, en un bosque al atardecer, mirando hacia el cielo con lágrimas de emoción a once cisnes blancos que vuelan con coronas doradas."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('c3d24228-339f-46b5-ac60-b5968c78b5e8', '2026-11-19 12:31:21.058739-03', '2026-11-19 12:31:21.058739-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Volad como cisnes salvajes y alejaos de este castillo!", "isCorrect": true}, {"text": "¡Qué felices estamos todos en el palacio!", "isCorrect": false}, {"text": "¡Bienvenidos, mis queridos hijos, a cenar!", "isCorrect": false}, {"text": "¡Les regalo un baile para esta noche!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/cisnes_reina_malvada.png", "imageDescription": "La reina madrastra, con corona y vestido oscuro y mirada fría, con los brazos extendidos lanzando un hechizo hacia once jóvenes en el patio de un palacio."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('c6e28df9-d49c-45ae-833a-4a6a89dbed2a', '2026-11-19 12:31:21.060738-03', '2026-11-19 12:31:21.060738-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Una princesa del reino vecino", "Elisa", "El hada Morgana", "La reina madrastra", "La anciana del bosque"], "imageSrc": "assets/images/pixelado/cisnes_elisa.png", "correctCharacter": "Elisa", "imageDescription": "Elisa, joven de cabello largo castaño y vestido sencillo verde, de pie en un bosque con luz suave, con expresión dulce y triste."}], "total_time": 7}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('4fc150e9-b3ed-412e-9916-d042ae5b67ca', '2026-11-19 12:31:21.061817-03', '2026-11-19 12:31:21.061817-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un grupo de gaviotas", "Los once cisnes", "Los patos del estanque", "Un barco de velas blancas", "Una bandada de gansos"], "imageSrc": "assets/images/pixelado/cisnes_once_cisnes.png", "correctCharacter": "Los once cisnes", "imageDescription": "Once cisnes blancos, cada uno con una pequeña corona dorada en la cabeza, volando juntos sobre el mar al atardecer."}], "total_time": 7}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('0577f72f-9045-414c-89cc-fe607caaa2be', '2026-11-19 12:31:21.063251-03', '2026-11-19 12:31:21.063251-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 661, "altText": "Elisa con lana blanca", "imageSrc": "assets/images/contra/cisnes_elisa_lana.png", "isContradiction": true, "imageDescription": "Elisa sentada en un sillón junto a una chimenea encendida, tejiendo lana blanca y sonriendo tranquila."}, {"id": 662, "altText": "Camisa verde tejida", "imageSrc": "assets/images/contra/cisnes_camisa_verde.png", "isContradiction": false, "imageDescription": "Una camisa de color verde grisáceo, hecha de ortigas, doblada sobre el regazo de Elisa."}, {"id": 663, "altText": "Manos enrojecidas de Elisa", "imageSrc": "assets/images/contra/cisnes_manos_rojas.png", "isContradiction": false, "imageDescription": "Primer plano de dos manos de niña enrojecidas y llenas de ronchas, sosteniendo ortigas."}, {"id": 664, "altText": "Ortigas junto al cementerio", "imageSrc": "assets/images/contra/cisnes_ortigas_cementerio.png", "isContradiction": false, "imageDescription": "Ortigas verdes altas creciendo entre lápidas de un cementerio, de noche."}], "explanation": "La imagen contradictoria muestra a Elisa tejiendo con lana blanca y suave, sentada junto al fuego, sin ningún dolor.", "premiseText": "Elisa tejía camisas con ortigas verdes que le quemaban las manos."}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('269b74fa-fd18-451c-afd9-fb8091803e1b', '2026-11-19 12:31:21.064262-03', '2026-11-19 12:31:21.064262-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 671, "altText": "Cisnes al amanecer", "imageSrc": "assets/images/contra/cisnes_amanecer.png", "isContradiction": false, "imageDescription": "Cisnes blancos despegando desde la playa cuando sale el sol, el cielo es anaranjado."}, {"id": 672, "altText": "Cisnes bajo la luna", "imageSrc": "assets/images/contra/cisnes_cisnes_noche.png", "isContradiction": true, "imageDescription": "Once cisnes con coronas durmiendo sobre las rocas de una playa, bajo una luna llena y cielo estrellado."}, {"id": 673, "altText": "Príncipes al anochecer", "imageSrc": "assets/images/contra/cisnes_principes_noche.png", "isContradiction": false, "imageDescription": "Once jóvenes con coronas doradas sentados en una cueva junto a Elisa al anochecer."}, {"id": 674, "altText": "Cisnes volando de día", "imageSrc": "assets/images/contra/cisnes_bandada_dia.png", "isContradiction": false, "imageDescription": "Once cisnes volando bajo un cielo azul y soleado sobre el mar."}], "explanation": "La imagen contradictoria muestra a los hermanos convertidos en cisnes en plena noche, bajo la luna, cuando en el cuento volvían a ser príncipes.", "premiseText": "Los once hermanos eran príncipes por la noche y cisnes durante el día."}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('bab338dd-9a98-4116-938b-f5b2fabbdcd6', '2026-11-19 12:31:21.06526-03', '2026-11-19 12:31:21.06526-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La maldición de la reina", "fragments": [{"id": 1, "text": "El rey viudo se casa con una reina malvada que no quiere a sus hijos."}, {"id": 2, "text": "La reina convierte a los once príncipes en cisnes salvajes y los echa del castillo."}, {"id": 3, "text": "Elisa es enviada a vivir con una familia campesina, lejos del palacio."}, {"id": 4, "text": "Al cumplir quince años, Elisa regresa al castillo, pero su padre no la reconoce."}, {"id": 5, "text": "Elisa huye al bosque en busca de sus hermanos."}]}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('6974b3bd-2a88-4b65-aa03-dfa1491fec76', '2026-11-19 12:31:21.066261-03', '2026-11-19 12:31:21.066261-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "Las camisas de ortigas", "fragments": [{"id": 1, "text": "Los once cisnes cargan a Elisa en una red y la llevan volando sobre el mar."}, {"id": 2, "text": "En sueños, un hada le revela que debe tejer camisas con ortigas del cementerio."}, {"id": 3, "text": "Elisa teje en silencio y un rey que cazaba en el bosque se enamora de ella."}, {"id": 4, "text": "Acusada de bruja, Elisa es llevada a la hoguera mientras termina las camisas."}, {"id": 5, "text": "Los cisnes llegan volando, Elisa les lanza las camisas y los hermanos recuperan su forma humana."}]}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('ce1dc6f6-3dff-4ca6-aa33-c983ac40b5ce', '2026-11-19 12:31:21.068259-03', '2026-11-19 12:31:21.068259-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["cuervos", "águilas", "patos", "cisnes"], "timeLeft": 7.0, "textAfter": "salvajes.", "textBefore": "La cruel madrastra convirtió a los once príncipes en", "correctWord": "cisnes"}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('80343147-d34c-4ceb-93cb-83ff14e044aa', '2026-11-19 12:31:21.07026-03', '2026-11-19 12:31:21.07026-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "Los cisnes y Elisa", "imageUrl": "assets/images/testigo/cisnes_red_cisnes.png", "questions": [{"prompt": "¿Qué llevaban los cisnes sobre la cabeza?", "options": ["Nada", "Un sombrero de plumas", "Un lazo rojo", "Una pequeña corona dorada"], "correctOption": "Una pequeña corona dorada"}, {"prompt": "¿En qué llevaban a Elisa?", "options": ["En una manta", "En una red de juncos", "En una canasta de mimbre", "En una barca"], "correctOption": "En una red de juncos"}, {"prompt": "¿De qué color era el vestido de Elisa?", "options": ["Azul", "Rojo", "Blanco", "Verde"], "correctOption": "Verde"}], "imageDescription": "Atardecer sobre el mar; once cisnes blancos con una pequeña corona dorada en la cabeza vuelan llevando una red hecha de juncos en la que viaja Elisa, con un vestido verde; el sol rojo baja sobre el horizonte."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('25b9d96b-d4fb-4b62-b778-88ada5462e2a', '2026-11-19 12:31:21.071261-03', '2026-11-19 12:31:21.071261-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El cementerio de las ortigas", "imageUrl": "assets/images/testigo/cisnes_cementerio_noche.png", "questions": [{"prompt": "¿Qué animal estaba sobre una lápida?", "options": ["Un murciélago", "Un cuervo", "Un gato negro", "Un búho"], "correctOption": "Un búho"}, {"prompt": "¿Qué recogía Elisa?", "options": ["Manzanas", "Ortigas", "Setas", "Flores blancas"], "correctOption": "Ortigas"}, {"prompt": "¿Cómo estaban las manos de Elisa?", "options": ["Rojas e hinchadas", "Sucias de barro", "Cubiertas con guantes", "Vendadas"], "correctOption": "Rojas e hinchadas"}], "imageDescription": "Un cementerio antiguo de noche con luna; lápidas de piedra grises; ortigas verdes altas entre las tumbas; Elisa arrodillada recogiendo ortigas con las manos enrojecidas; un búho posado sobre una lápida."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('f2ce41f7-08a3-4d4b-997c-04fda00bccb3', '2026-11-19 12:31:21.073259-03', '2026-11-19 12:31:21.073259-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Flores silvestres", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-2", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-3", "name": "Juncos", "imageUrl": "assets/images/cazador-intrusos/juncos.png", "isIntruder": false}, {"id": "item-4", "name": "Cisne blanco", "imageUrl": "assets/images/cazador-intrusos/cisne.png", "isIntruder": false}, {"id": "item-5", "name": "Lirios de agua", "imageUrl": "assets/images/cazador-intrusos/lirios.png", "isIntruder": false}, {"id": "item-6", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}], "title": "El lago del bosque", "bgImageUrl": "assets/images/cazador-intrusos/cisnes-lago-bg.jpg", "textDescription": "Cerca del lago, los juncos se mecían, los lirios flotaban sobre el agua y un cisne blanco nadaba entre las flores silvestres.", "bgImageDescription": "Lago tranquilo en un bosque al amanecer, con orilla de pasto y agua clara, árboles al fondo; espacio libre para 6 objetos."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('4455d4ea-95b9-43f3-b61e-3e4a3118db72', '2026-11-19 12:31:21.074287-03', '2026-11-19 12:31:21.074287-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Ortigas", "imageUrl": "assets/images/cazador-intrusos/ortigas.png", "isIntruder": false, "imageDescription": "Manojo de ortigas verdes con hojas dentadas, fondo transparente."}, {"id": "item-2", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-3", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-4", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}, {"id": "item-5", "name": "Lápida de piedra", "imageUrl": "assets/images/cazador-intrusos/lapida-piedra.png", "isIntruder": false, "imageDescription": "Lápida de piedra gris antigua con una pequeña cruz y musgo, fondo transparente."}, {"id": "item-6", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}], "title": "El cementerio de las ortigas", "bgImageUrl": "assets/images/cazador-intrusos/cisnes-cementerio-bg.jpg", "textDescription": "De noche, entre las tumbas del cementerio, crecían las ortigas que Elisa debía recoger para tejer las camisas de sus hermanos.", "bgImageDescription": "Cementerio antiguo de noche con luna llena, niebla suave y suelo de tierra; espacio libre para 6 objetos."}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('5b7ca54a-58e4-4c16-b3d3-b0cbb916e6e2', '2026-11-19 12:31:21.07526-03', '2026-11-19 12:31:21.07526-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/cisnes-orilla.jpg", "storyTitle": "Los cisnes salvajes", "targetArea": {"top": 38, "left": 60, "width": 30, "height": 50}, "textSnippet": "Sobre una roca de la orilla, entre la espuma de las olas, una corona dorada brillaba sobre la cabeza del cisne más pequeño.", "imageDescription": "Playa rocosa al atardecer con varios cisnes blancos y el mar al fondo. En la parte derecha, un cisne más pequeño con una corona dorada, cuyo brillo lo hace destacar levemente del resto de la bandada. Escena muy recargada: hay once cisnes blancos y muchos otros pájaros, rocas, algas, espuma, nubes y velas lejanas.", "targetObjectName": "Corona del cisne"}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('49e4cd4c-f59c-4b06-aa91-ee473307f1f2', '2026-11-19 12:31:21.076261-03', '2026-11-19 12:31:21.076261-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/cisnes-cementerio-busca.jpg", "storyTitle": "Los cisnes salvajes", "targetArea": {"top": 15, "left": 65, "width": 25, "height": 40}, "textSnippet": "Detrás de las altas ortigas del cementerio, un viejo búho observaba a Elisa con ojos amarillos.", "imageDescription": "Cementerio de noche con ortigas y algunas lápidas. En la parte superior derecha, un búho marrón de ojos amarillos posado sobre una lápida, con un contorno algo más marcado que las ortigas.", "targetObjectName": "Búho"}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('30776a23-602d-4d8f-9361-922553f923ac', '2026-11-19 12:31:21.07826-03', '2026-11-19 12:31:21.07826-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Los príncipes se vuelven cisnes", "panels": [{"id": 1, "image": "assets/images/comics/cisnes1.png", "imageDescription": "La reina madrastra, de pie en el patio del castillo, extiende los brazos frente a once príncipes."}, {"id": 2, "image": "assets/images/comics/cisnes2.png", "imageDescription": "Los once príncipes se transforman en cisnes con coronas doradas entre una nube de plumas."}, {"id": 3, "image": "assets/images/comics/cisnes3.png", "imageDescription": "Los cisnes salen volando por encima del castillo."}, {"id": 4, "image": "assets/images/comics/cisnes4.png", "imageDescription": "Los cisnes vuelan sobre el bosque rumbo al mar mientras la reina sonríe desde una torre."}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('3093dcad-b737-48e9-9eab-9838ede6b156', '2026-11-19 12:31:22.39901-03', '2026-11-19 12:31:22.39901-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El ministro", "El emperador", "El mago", "El soldado", "El tejedor"], "imageSrc": "assets/images/pixelado/traje_emperador.png", "correctCharacter": "El emperador", "imageDescription": "Un emperador con corona dorada y capa roja con ribetes blancos, de pie con gesto orgulloso en un salón de palacio."}], "total_time": 7}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('c303bb99-2fc6-4337-b0d9-f91ec846ce8c', '2026-11-19 12:31:21.07926-03', '2026-11-19 12:31:21.07926-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La hoguera", "panels": [{"id": 1, "image": "assets/images/comics/cisnes5.png", "imageDescription": "Elisa, con vestido gris, teje en silencio una camisa de ortigas."}, {"id": 2, "image": "assets/images/comics/cisnes6.png", "imageDescription": "Un rey montado a caballo ve a Elisa en el bosque y se enamora de ella."}, {"id": 3, "image": "assets/images/comics/cisnes7.png", "imageDescription": "Elisa, en una carreta rumbo a la hoguera, lleva las camisas verdes bajo la mirada de la multitud."}, {"id": 4, "image": "assets/images/comics/cisnes8.png", "imageDescription": "Once cisnes bajan del cielo; Elisa les lanza las camisas y aparecen once príncipes, el menor con un ala de cisne en lugar de un brazo."}]}', '88a0e2b5-490d-4bf5-9099-42d570362b6f', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('d8659de8-4be4-4084-8382-910dcbcb1aa6', '2026-11-19 12:31:21.082544-03', '2026-11-19 12:31:21.082544-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Perico fue al huerto del señor McGregor.", "isTrue": true}, {"text": "Mamá Coneja le dio permiso para entrar al huerto.", "isTrue": false}, {"text": "Perico pasó por debajo de la cerca.", "isTrue": true}], "passage_text": "Mamá Coneja advirtió a Perico y a sus hermanas que no fueran al huerto del señor McGregor, porque allí su padre había tenido un accidente. Pero Perico, muy desobediente, se coló por debajo de la cerca.", "time_per_statement": 7}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('68018697-9622-43ad-af1c-deed66a46ac0', '2026-11-19 12:31:21.084553-03', '2026-11-19 12:31:21.084553-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Socorro, el señor McGregor me persigue!", "isCorrect": true}, {"text": "¡Mamá, ya terminé mi tarea!", "isCorrect": false}, {"text": "¡Hoy invité a mis amigos a tomar el té!", "isCorrect": false}, {"text": "¡Qué día tan tranquilo para dormir la siesta!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/perico_asustado.png", "imageDescription": "Perico, un conejito marrón con chaqueta azul de botones dorados, corriendo aterrado entre hileras de lechugas en un huerto, con el señor McGregor detrás de él con un rastrillo."}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('50b6cff7-3d46-47da-bb9f-db4f743b5b81', '2026-11-19 12:31:21.086552-03', '2026-11-19 12:31:21.086552-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Mamá Coneja", "Perico", "El señor McGregor", "Colita de Algodón", "Nogalina"], "imageSrc": "assets/images/pixelado/perico_conejo.png", "correctCharacter": "Perico", "imageDescription": "Perico, un conejito marrón de orejas largas, con una chaqueta azul de botones dorados, sentado sobre la hierba de un huerto."}], "total_time": 7}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('c6fcea6e-093f-4606-a580-7913285938b9', '2026-11-19 12:31:21.087552-03', '2026-11-19 12:31:21.087552-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 681, "altText": "Perico con chaqueta azul", "imageSrc": "assets/images/contra/perico_chaqueta_azul.png", "isContradiction": false, "imageDescription": "Perico, conejo marrón, pasando bajo una cerca de madera, con una chaqueta azul de botones dorados."}, {"id": 682, "altText": "Perico con chaqueta de lunares", "imageSrc": "assets/images/contra/perico_chaqueta_lunares.png", "isContradiction": true, "imageDescription": "Perico, conejo marrón, con chaqueta roja de lunares blancos y un sombrero de copa negro."}, {"id": 683, "altText": "Chaqueta azul en el espantapájaros", "imageSrc": "assets/images/contra/perico_espantapajaros.png", "isContradiction": false, "imageDescription": "Un espantapájaros en un huerto vestido con una pequeña chaqueta azul de botones dorados y zapatos diminutos."}, {"id": 684, "altText": "Botones dorados", "imageSrc": "assets/images/contra/perico_botones_dorados.png", "isContradiction": false, "imageDescription": "Primer plano de una tela azul con tres botones dorados brillantes."}], "explanation": "La imagen contradictoria muestra a Perico con una chaqueta roja de lunares y un sombrero de copa.", "premiseText": "Perico llevaba una chaqueta azul con botones dorados cuando entró al huerto."}]}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('0556471e-63c4-4e51-8d76-b0592fdc376c', '2026-11-19 12:31:21.089595-03', '2026-11-19 12:31:21.089595-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "Perico en el huerto", "fragments": [{"id": 1, "text": "Mamá Coneja prohíbe a sus hijos entrar al huerto del señor McGregor."}, {"id": 2, "text": "Perico se cuela bajo la cerca y se come lechugas, judías y rábanos."}, {"id": 3, "text": "El señor McGregor lo descubre y lo persigue con un rastrillo; Perico pierde su chaqueta y sus zapatos."}, {"id": 4, "text": "Perico se esconde en una regadera y estornuda, pero logra escapar."}, {"id": 5, "text": "Cansado y enfermo, vuelve a casa y su mamá le da una taza de té de manzanilla."}]}]}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('734a4073-78b4-4f77-b774-ce55afb330cc', '2026-11-19 12:31:21.091552-03', '2026-11-19 12:31:21.091552-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["chocolate", "manzanilla", "limón", "menta"], "timeLeft": 7.0, "textAfter": "para su dolor de barriga.", "textBefore": "Mamá Coneja le dio a Perico una taza de té de", "correctWord": "manzanilla"}]}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('c99596af-0538-433d-9f37-c48cb7c3371f', '2026-11-19 12:31:21.093581-03', '2026-11-19 12:31:21.093581-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El huerto del señor McGregor", "imageUrl": "assets/images/testigo/perico_huerto.png", "questions": [{"prompt": "¿Qué llevaba puesto el espantapájaros?", "options": ["Una chaqueta azul y zapatos pequeños", "Un delantal", "Un sombrero rojo", "Una capa negra"], "correctOption": "Una chaqueta azul y zapatos pequeños"}, {"prompt": "¿De qué color era la regadera?", "options": ["Roja", "Verde", "Azul", "Amarilla"], "correctOption": "Roja"}, {"prompt": "¿Cuántos gorriones había sobre la cerca?", "options": ["Cuatro", "Tres", "Uno", "Dos"], "correctOption": "Dos"}], "imageDescription": "Huerto soleado con hileras de lechugas verdes y zanahorias; en primer plano una regadera roja sobre el suelo; un espantapájaros con una chaqueta azul y zapatos pequeños; al fondo una cerca blanca de madera con dos gorriones encima."}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('18c97639-45ee-4a9f-be3d-cfcbaa8ed97d', '2026-11-19 12:31:21.111528-03', '2026-11-19 12:31:21.111528-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 2, "title": "La isla del Viejo Brown", "imageUrl": "assets/images/testigo/nogalina_isla.png", "questions": [{"prompt": "¿Dónde vivía el búho?", "options": ["En el hueco de un roble", "En una cueva", "En una cabaña", "En un nido en el suelo"], "correctOption": "En el hueco de un roble"}, {"prompt": "¿Cuántas ardillas había en la orilla?", "options": ["Siete", "Tres", "Cinco", "Una"], "correctOption": "Tres"}, {"prompt": "¿Qué llevaba una ardilla en la cesta?", "options": ["Escarabajos", "Manzanas", "Nueces", "Pescados"], "correctOption": "Escarabajos"}], "imageDescription": "Una pequeña isla con un gran roble de tronco hueco; en una rama frente al hueco, un búho gris; tres ardillas rojas en la orilla junto a una balsa de ramas; una ardilla lleva una cesta con escarabajos; cielo nublado."}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('0259511c-e9af-4382-95cb-98fa2418f6bf', '2026-11-19 12:31:21.094552-03', '2026-11-19 12:31:21.094552-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Rábano", "imageUrl": "assets/images/cazador-intrusos/rabano.png", "isIntruder": false, "imageDescription": "Dos rábanos rojos con hojas verdes, fondo transparente."}, {"id": "item-2", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-3", "name": "Lechuga", "imageUrl": "assets/images/cazador-intrusos/lechuga.png", "isIntruder": false, "imageDescription": "Lechuga verde fresca y grande, fondo transparente."}, {"id": "item-4", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-5", "name": "Chaqueta azul con botones", "imageUrl": "assets/images/cazador-intrusos/chaqueta-azul-botones.png", "isIntruder": false, "imageDescription": "Chaqueta azul pequeña con botones dorados, fondo transparente."}, {"id": "item-6", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}], "title": "El huerto del señor McGregor", "bgImageUrl": "assets/images/cazador-intrusos/perico-huerto-bg.jpg", "textDescription": "En el huerto crecían lechugas y rábanos, y en un rincón colgaba la chaqueta azul que Perico perdió en su huida.", "bgImageDescription": "Huerto soleado con cerca de madera al fondo y tierra labrada; espacio libre para colocar 6 objetos."}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('a577e6a2-a860-4f00-bc01-bab5fd3c7267', '2026-11-19 12:31:21.096577-03', '2026-11-19 12:31:21.096577-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/perico-espantapajaros-busca.jpg", "storyTitle": "Perico el Conejo", "targetArea": {"top": 25, "left": 50, "width": 40, "height": 37.5}, "textSnippet": "Colgada de un espantapájaros, la chaqueta azul de botones dorados de Perico se mecía con la brisa.", "imageDescription": "Huerto soleado con hileras de verduras y un espantapájaros de paja. En la parte central-derecha, sobre el espantapájaros, una chaqueta azul grande con botones dorados que destaca levemente del huerto. Escena muy recargada: el huerto tiene muchas hileras de lechugas, repollos, zanahorias, regaderas, cestas, gorriones, conejos pequeños y varios espantapájaros cercanos.", "targetObjectName": "Chaqueta azul"}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('1a0b052d-87a7-475e-b808-e396f9144fa7', '2026-11-19 12:31:21.097551-03', '2026-11-19 12:31:21.097551-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La travesura de Perico", "panels": [{"id": 1, "image": "assets/images/comics/perico1.png", "imageDescription": "Mamá Coneja advierte a Perico y a sus hermanas en la puerta de su madriguera."}, {"id": 2, "image": "assets/images/comics/perico2.png", "imageDescription": "Perico se cuela bajo la cerca del huerto."}, {"id": 3, "image": "assets/images/comics/perico3.png", "imageDescription": "El señor McGregor persigue a Perico con un rastrillo."}, {"id": 4, "image": "assets/images/comics/perico4.png", "imageDescription": "Perico, agotado, toma té de manzanilla en la cama mientras su mamá lo cuida."}]}', 'bdc83413-1b9b-4dbb-afff-e247d6f5c77f', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('b7189192-4d0d-49b0-9e8e-dd08c82a4a70', '2026-11-19 12:31:21.101992-03', '2026-11-19 12:31:21.101992-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Las ardillas viajaron hasta la isla del búho.", "isTrue": true}, {"text": "Nogalina fue respetuoso con el búho.", "isTrue": false}, {"text": "Nogalina le cantaba adivinanzas al búho.", "isTrue": true}], "passage_text": "Nogalina y sus hermanos ardillas navegaron en balsas hasta la isla del Viejo Brown, el búho. Los demás le llevaban regalos y le pedían permiso con respeto, pero Nogalina lo molestaba cantándole adivinanzas.", "time_per_statement": 7}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('d21388e1-c260-4748-9873-0c3d0299352d', '2026-11-19 12:31:21.103502-03', '2026-11-19 12:31:21.103502-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Gracias por tus regalos, los guardaré!", "isCorrect": false}, {"text": "¡Ya no aguanto más tus travesuras, Nogalina!", "isCorrect": true}, {"text": "¡Esta noche iré a pescar al río!", "isCorrect": false}, {"text": "¡Qué lindo es tu baile, quédate a cenar!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/nogalina_viejo_brown_enojado.png", "imageDescription": "El Viejo Brown, un búho grande y enojado, con las plumas erizadas y los ojos amarillos muy abiertos, sobre la rama de un roble hueco, mirando fijamente a una pequeña ardilla roja."}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('1509a49a-8cc7-4644-ad4b-06cf3605389a', '2026-11-19 12:31:21.104528-03', '2026-11-19 12:31:21.104528-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Nogalina", "Viejo Brown", "Un gallo", "Un halcón", "Un cuervo"], "imageSrc": "assets/images/pixelado/nogalina_viejo_brown.png", "correctCharacter": "Viejo Brown", "imageDescription": "Un búho gris grande, de plumaje en tonos marrones y ojos amarillos, posado en la rama de un roble antiguo."}], "total_time": 7}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('924f6724-08cd-413e-9a03-84f5c82679dd', '2026-11-19 12:31:21.106533-03', '2026-11-19 12:31:21.106533-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 691, "altText": "Cola esponjosa", "imageSrc": "assets/images/contra/nogalina_cola_esponjosa.png", "isContradiction": false, "imageDescription": "Primer plano de una cola de ardilla roja larga y muy esponjosa."}, {"id": 692, "altText": "Ardilla roja", "imageSrc": "assets/images/contra/nogalina_ardilla_roja.png", "isContradiction": false, "imageDescription": "Una ardilla de pelaje rojizo sentada sobre una rama, con una cola larga y esponjosa."}, {"id": 693, "altText": "Ardilla verde de cola corta", "imageSrc": "assets/images/contra/nogalina_ardilla_verde.png", "isContradiction": true, "imageDescription": "Una ardilla de pelaje verde con una cola corta, delgada y sin pelo, sentada sobre una rama."}, {"id": 694, "altText": "Ardillas en balsa", "imageSrc": "assets/images/contra/nogalina_ardillas_balsa.png", "isContradiction": false, "imageDescription": "Tres ardillas rojas navegando en una balsa de ramas sobre un lago, usando sus colas como velas."}], "explanation": "La imagen contradictoria muestra a una ardilla verde con una cola corta y lisa como la de un ratón.", "premiseText": "Nogalina era una ardilla de pelaje rojizo y cola larga y esponjosa."}]}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('63b17893-9f2c-413d-91f8-fb8ebaba4be8', '2026-11-19 12:31:21.108502-03', '2026-11-19 12:31:21.108502-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 2, "title": "El castigo de Nogalina", "fragments": [{"id": 1, "text": "Las ardillas llegan a la isla del Viejo Brown en balsas de ramas."}, {"id": 2, "text": "Cada día le llevan un regalo al búho y le piden permiso para recoger nueces."}, {"id": 3, "text": "Nogalina, en lugar de obedecer, le canta adivinanzas y se burla de él."}, {"id": 4, "text": "El Viejo Brown lo atrapa y lo lleva a su árbol hueco."}, {"id": 5, "text": "Nogalina logra escapar, pero pierde su cola en la huida."}]}]}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('882384a0-9ef6-4193-95d2-4050ecd41247', '2026-11-19 12:31:21.109502-03', '2026-11-19 12:31:21.109502-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 2, "options": ["colas", "chaquetas", "sombreros", "bufandas"], "timeLeft": 7.0, "textAfter": "como velas.", "textBefore": "Las ardillas navegaron hasta la isla del búho usando sus", "correctWord": "colas"}]}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('edee2de8-4c4a-4c9f-96c6-bf572520c05d', '2026-11-19 12:31:21.113502-03', '2026-11-19 12:31:21.113502-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 2, "items": [{"id": "item-1", "name": "Submarino", "imageUrl": "assets/images/cazador-intrusos/submarino.png", "isIntruder": true}, {"id": "item-2", "name": "Raqueta de tenis", "imageUrl": "assets/images/cazador-intrusos/raqueta.png", "isIntruder": true}, {"id": "item-3", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-4", "name": "Pista de esquí", "imageUrl": "assets/images/cazador-intrusos/esqui.png", "isIntruder": true}, {"id": "item-5", "name": "Balsa de ramas", "imageUrl": "assets/images/cazador-intrusos/balsa-ramas.png", "isIntruder": false, "imageDescription": "Pequeña balsa hecha de ramas atadas, vista de costado, fondo transparente."}, {"id": "item-6", "name": "Nueces", "imageUrl": "assets/images/cazador-intrusos/nueces.png", "isIntruder": false, "imageDescription": "Tres nueces marrones, una de ellas abierta, fondo transparente."}], "title": "La isla del búho", "bgImageUrl": "assets/images/cazador-intrusos/nogalina-isla-bg.jpg", "textDescription": "Las ardillas llegaron en una balsa de ramas hasta la isla del búho, donde juntaron nueces bajo los robles.", "bgImageDescription": "Orilla de una isla con robles antiguos, hojas secas en el suelo y un lago al fondo; espacio libre para 6 objetos."}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('6df9374d-b61b-47b5-9d6b-9c8f108fbc4b', '2026-11-19 12:31:21.114502-03', '2026-11-19 12:31:21.114502-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 2, "imageUrl": "assets/images/busca-imagen/nogalina-orilla.jpg", "storyTitle": "La ardilla Nogalina", "targetArea": {"top": 65, "left": 25, "width": 50, "height": 20}, "textSnippet": "Junto a la orilla, entre las ramas, una pequeña balsa esperaba a las ardillas.", "imageDescription": "Orilla de un lago en otoño con cañas y unas pocas ramas caídas. En la parte inferior, una balsa de ramas atadas, de tono algo más claro que la orilla y con contorno más marcado.", "targetObjectName": "Balsa de ramas"}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('1a7f5cb1-9799-4735-8561-5029bd3db951', '2026-11-19 12:31:21.116503-03', '2026-11-19 12:31:21.116503-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 2, "title": "Nogalina y el búho", "panels": [{"id": 1, "image": "assets/images/comics/perico5.png", "imageDescription": "Varias ardillas rojas navegan en balsas de ramas usando sus colas como velas."}, {"id": 2, "image": "assets/images/comics/perico6.png", "imageDescription": "Las ardillas entregan regalos al Viejo Brown frente a su árbol."}, {"id": 3, "image": "assets/images/comics/perico7.png", "imageDescription": "Nogalina baila y canta frente al búho, mientras las otras ardillas lo miran preocupadas."}, {"id": 4, "image": "assets/images/comics/perico8.png", "imageDescription": "Nogalina huye veloz del árbol, sin su cola, que queda en la garra del búho."}]}', 'a3211fdc-ee4d-4bd9-b231-ee9caa45f758', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('4d8d1ccc-ec0d-41ae-9e06-c74bd6ccf3e8', '2026-11-19 12:31:21.12053-03', '2026-11-19 12:31:21.12053-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Pulgarcito era el menor de siete hermanos.", "isTrue": true}, {"text": "Llenó sus bolsillos con piedrecitas blancas.", "isTrue": true}, {"text": "Sus padres eran muy ricos.", "isTrue": false}], "passage_text": "Pulgarcito era el menor de siete hermanos y era muy pequeño. Una noche escuchó que sus padres, por la pobreza, planeaban abandonar a los niños en el bosque. Por eso llenó sus bolsillos con piedrecitas blancas.", "time_per_statement": 7}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('cc84f57f-5925-494e-9fe4-009c7eeb2afd', '2026-11-19 12:31:21.121502-03', '2026-11-19 12:31:21.121502-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El ogro tenía siete hijas.", "isTrue": true}, {"text": "Las hijas del ogro llevaban coronas de oro.", "isTrue": true}, {"text": "El ogro reconoció a los niños en la oscuridad.", "isTrue": false}], "passage_text": "Los niños llegaron a la casa de un ogro. Pulgarcito cambió los gorros de sus hermanos por las coronas de oro de las siete hijas del ogro, y así el ogro se equivocó en la oscuridad.", "time_per_statement": 7}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('e98c5609-393d-4b33-96f3-45bf1181987a', '2026-11-19 12:31:21.122528-03', '2026-11-19 12:31:21.122528-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Me iré a dormir, no escuché nada!", "isCorrect": false}, {"text": "¡Qué rica cena, quiero más sopa!", "isCorrect": false}, {"text": "Voy a llenar mis bolsillos con piedrecitas para encontrar el camino.", "isCorrect": true}, {"text": "¡Mañana pintaremos la casa de rojo!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/pulgarcito_planea.png", "imageDescription": "Pulgarcito, un niño diminuto con gorro rojo, escondido bajo un banco de la cocina, escuchando con cara de preocupación a sus padres que hablan tristes junto a una mesa pobre."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('bf5aeb66-5754-4db1-bc4a-fb2599165856', '2026-11-19 12:31:21.123743-03', '2026-11-19 12:31:21.123743-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Bienvenidos a mi fiesta, pequeños amigos!", "isCorrect": false}, {"text": "¡Huelo carne fresca de niños!", "isCorrect": true}, {"text": "¡Qué buen día para pasear por el campo!", "isCorrect": false}, {"text": "¡Acabo de comer pastel de manzana!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/pulgarcito_ogro.png", "imageDescription": "Un ogro grande y barbudo con ojos rojos, de pie en la puerta de su casa en el bosque, oliendo el aire con la nariz levantada y un cuchillo grande en la mano."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('651d7424-ad22-4611-ae35-b52ff0993251', '2026-11-19 12:31:21.124556-03', '2026-11-19 12:31:21.124556-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El ogro", "Pulgarcito", "El leñador", "El príncipe", "El hijo mayor"], "imageSrc": "assets/images/pixelado/pulgarcito_personaje.png", "correctCharacter": "Pulgarcito", "imageDescription": "Pulgarcito, un niño diminuto del tamaño de un pulgar, con gorro rojo y ropa sencilla, de pie sobre una piedra en el bosque."}], "total_time": 7}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('fe94be15-1909-4a35-8ede-4bc6e0d703c0', '2026-11-19 12:31:21.125585-03', '2026-11-19 12:31:21.125585-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Unas botas de lluvia", "Unas pantuflas", "Unos zuecos de madera", "Zapatos de baile", "Las botas de siete leguas"], "imageSrc": "assets/images/pixelado/pulgarcito_botas.png", "correctCharacter": "Las botas de siete leguas", "imageDescription": "Un par de grandes botas de cuero marrón con hebillas doradas y destellos mágicos a su alrededor."}], "total_time": 7}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('bb348c2a-8954-4211-9903-5ccc61c1b75b', '2026-11-19 12:31:21.149036-03', '2026-11-19 12:31:21.149036-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Por fin terminé de cocinar el almuerzo!", "isCorrect": false}, {"text": "¡Qué lindo jardín tiene el castillo!", "isCorrect": false}, {"text": "¿Qué habrá dentro de esta habitación prohibida?", "isCorrect": true}, {"text": "¡Voy a guardar esta llave y olvidarme de ella!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/barba_azul_esposa_curiosa.png", "imageDescription": "Una joven esposa con vestido azul claro, sosteniendo una pequeña llave dorada frente a una puerta cerrada de madera, con expresión de curiosidad y nervios, en un pasillo de castillo."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('0c241f78-b4dc-4d8d-93a4-45718441883d', '2026-11-19 12:31:21.127564-03', '2026-11-19 12:31:21.127564-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 701, "altText": "Bolsillos con piedrecitas", "imageSrc": "assets/images/contra/pulgarcito_bolsillos_piedras.png", "isContradiction": false, "imageDescription": "Pulgarcito mostrando sus bolsillos llenos de piedrecitas blancas."}, {"id": 702, "altText": "Camino de piedrecitas blancas", "imageSrc": "assets/images/contra/pulgarcito_camino_blanco.png", "isContradiction": false, "imageDescription": "Un sendero de piedrecitas blancas brillando bajo la luna en un bosque oscuro."}, {"id": 703, "altText": "Niños siguiendo el camino", "imageSrc": "assets/images/contra/pulgarcito_regreso_casa.png", "isContradiction": false, "imageDescription": "Siete niños siguiendo un camino de piedrecitas blancas hacia una casa de campo iluminada."}, {"id": 704, "altText": "Pulgarcito soltando plumas", "imageSrc": "assets/images/contra/pulgarcito_plumas.png", "isContradiction": true, "imageDescription": "Pulgarcito caminando por el bosque y dejando caer plumas de colores en el suelo."}], "explanation": "La imagen contradictoria muestra a Pulgarcito soltando plumas de colores en lugar de piedrecitas blancas.", "premiseText": "Pulgarcito dejó caer piedrecitas blancas para marcar el camino de regreso a casa."}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('f7a7cc2d-e4bf-47eb-9eb5-52fa9be1e275', '2026-11-19 12:31:21.128562-03', '2026-11-19 12:31:21.128562-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 711, "altText": "Botas mágicas", "imageSrc": "assets/images/contra/pulgarcito_botas_magicas.png", "isContradiction": false, "imageDescription": "Un par de botas de cuero grandes con destellos y rayos de luz dorados."}, {"id": 712, "altText": "Ogro con zapatillas de ballet", "imageSrc": "assets/images/contra/pulgarcito_ogro_ballet.png", "isContradiction": true, "imageDescription": "Un ogro grande y barbudo con zapatillas de ballet rosadas y un tutú, bailando."}, {"id": 713, "altText": "Ogro dando un paso enorme", "imageSrc": "assets/images/contra/pulgarcito_ogro_paso.png", "isContradiction": false, "imageDescription": "Un ogro dando un paso gigante por encima de montañas y valles."}, {"id": 714, "altText": "Ogro dormido sobre una roca", "imageSrc": "assets/images/contra/pulgarcito_ogro_dormido.png", "isContradiction": false, "imageDescription": "Un ogro durmiendo sentado sobre una roca, con las botas puestas, bajo la luz de la luna."}], "explanation": "La imagen contradictoria muestra al ogro con zapatillas de ballet rosadas.", "premiseText": "El ogro usaba unas botas mágicas que le permitían recorrer siete leguas de un solo paso."}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('28370906-5131-4549-a956-bf190ef1f230', '2026-11-19 12:31:21.129848-03', '2026-11-19 12:31:21.129848-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "Perdidos en el bosque", "fragments": [{"id": 1, "text": "Pulgarcito escucha a sus padres planear que abandonarán a los niños por la falta de comida."}, {"id": 2, "text": "Pulgarcito llena sus bolsillos de piedrecitas blancas."}, {"id": 3, "text": "El leñador lleva a sus hijos al bosque, y Pulgarcito va dejando caer las piedrecitas."}, {"id": 4, "text": "Siguiendo las piedrecitas brillantes, los niños vuelven a casa."}, {"id": 5, "text": "Más tarde, en otra salida al bosque, usa migas de pan, pero los pájaros se las comen."}]}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('a38b8eaf-2b9c-48f3-af7e-3342bbd13c26', '2026-11-19 12:31:21.130887-03', '2026-11-19 12:31:21.130887-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La casa del ogro", "fragments": [{"id": 1, "text": "Los niños, perdidos, ven una luz y llegan a una casa donde vive un ogro."}, {"id": 2, "text": "La esposa del ogro los esconde, pero el ogro huele carne fresca."}, {"id": 3, "text": "Pulgarcito cambia los gorros de sus hermanos por las coronas de las hijas del ogro."}, {"id": 4, "text": "Por la noche, los niños escapan mientras el ogro se equivoca en la oscuridad."}, {"id": 5, "text": "El ogro los persigue con sus botas de siete leguas, pero se duerme y Pulgarcito se las quita."}]}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('fbd2b936-d9ff-4476-926b-f877db51eb8d', '2026-11-19 12:31:21.132857-03', '2026-11-19 12:31:21.132857-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["blancas", "azules", "rojas", "negras"], "timeLeft": 7.0, "textAfter": "para encontrar el camino de regreso.", "textBefore": "Pulgarcito llenó sus bolsillos de piedrecitas", "correctWord": "blancas"}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('97b28781-49b3-4e30-8ff1-6eb3a5f7e581', '2026-11-19 12:31:21.133858-03', '2026-11-19 12:31:21.133858-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["leguas", "pasos", "días", "metros"], "timeLeft": 7.0, "textAfter": "que le permitían caminar muy rápido.", "textBefore": "El ogro usaba unas botas de siete", "correctWord": "leguas"}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('9bbc8c10-c762-4fec-b2d7-177bd605b14d', '2026-11-19 12:31:21.134888-03', '2026-11-19 12:31:21.134888-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La casa del ogro", "imageUrl": "assets/images/testigo/pulgarcito_cocina_ogro.png", "questions": [{"prompt": "¿Qué había sobre la mesa?", "options": ["Un pastel y una vela", "Un libro abierto", "Una olla humeante y un cuchillo", "Una jarra con flores"], "correctOption": "Una olla humeante y un cuchillo"}, {"prompt": "¿De qué color era el pañuelo de la mujer?", "options": ["Rojo", "Verde", "Azul", "Negro"], "correctOption": "Rojo"}, {"prompt": "¿Cuántos niños se escondían tras el baúl?", "options": ["Diez", "Siete", "Tres", "Cinco"], "correctOption": "Siete"}], "imageDescription": "Cocina rústica y oscura: una gran mesa de madera con una olla humeante y un cuchillo grande; una chimenea encendida; una mujer con delantal gris y pañuelo rojo en la cabeza; siete niños escondidos tras un baúl; en la pared, un par de botas grandes colgando."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('3e304c32-9c64-4dae-a103-b18d665c3604', '2026-11-19 12:31:21.135858-03', '2026-11-19 12:31:21.135858-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El camino de piedrecitas", "imageUrl": "assets/images/testigo/pulgarcito_sendero_luna.png", "questions": [{"prompt": "¿De qué color era el gorro de Pulgarcito?", "options": ["Azul", "Rojo", "Verde", "Amarillo"], "correctOption": "Rojo"}, {"prompt": "¿Cuántos niños seguían a Pulgarcito?", "options": ["Cuatro", "Ocho", "Seis", "Siete"], "correctOption": "Seis"}, {"prompt": "¿Qué animal estaba en la rama?", "options": ["Una ardilla", "Un murciélago", "Un búho", "Un cuervo"], "correctOption": "Un búho"}], "imageDescription": "Bosque de noche iluminado por luna llena; un sendero de piedrecitas blancas brillantes; Pulgarcito, diminuto, con gorro rojo, al inicio del sendero; seis niños lo siguen; un búho en una rama baja."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('60841837-deac-4e8e-b79c-a05265ff9aae', '2026-11-19 12:31:21.174122-03', '2026-11-19 12:31:21.174122-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Una anciana adoptó a Karen.", "isTrue": true}, {"text": "Karen eligió zapatos rojos para su confirmación.", "isTrue": true}, {"text": "Karen eligió zapatos negros para la iglesia.", "isTrue": false}], "passage_text": "Karen fue adoptada por una anciana rica. Cuando fue a su confirmación, eligió unos zapatos rojos de charol brillante, aunque no era correcto usarlos en la iglesia.", "time_per_statement": 7}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('8623f33f-9a64-4f20-ab2a-6a89d233d542', '2026-11-19 12:31:21.137858-03', '2026-11-19 12:31:21.137858-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Cesta de pan", "imageUrl": "assets/images/cazador-intrusos/cesta-pan.png", "isIntruder": false}, {"id": "item-2", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-3", "name": "Hacha del leñador", "imageUrl": "assets/images/cazador-intrusos/hacha.png", "isIntruder": false, "imageDescription": "Hacha de leñador con mango de madera y hoja de hierro, fondo transparente."}, {"id": "item-4", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-5", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-6", "name": "Tablones de madera", "imageUrl": "assets/images/cazador-intrusos/tablones.png", "isIntruder": false}], "title": "La cabaña del leñador", "bgImageUrl": "assets/images/cazador-intrusos/pulgarcito-cabana-bg.jpg", "textDescription": "En la humilde cabaña del leñador había un hacha, tablones de madera, una cesta con un poco de pan y una cama sencilla.", "bgImageDescription": "Interior de una cabaña humilde de madera con chimenea apagada y piso de tablas; espacio libre para 6 objetos."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('6ce4907f-c70d-4498-8bd7-013cf357747f', '2026-11-19 12:31:21.138858-03', '2026-11-19 12:31:21.138858-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Corona de oro", "imageUrl": "assets/images/cazador-intrusos/corona-oro.png", "isIntruder": false, "imageDescription": "Pequeña corona dorada con puntas simples, fondo transparente."}, {"id": "item-2", "name": "Radio a pilas", "imageUrl": "assets/images/cazador-intrusos/radio.png", "isIntruder": true}, {"id": "item-3", "name": "Botas de siete leguas", "imageUrl": "assets/images/cazador-intrusos/botas.png", "isIntruder": false}, {"id": "item-4", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}, {"id": "item-5", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-6", "name": "Cofre de tesoros", "imageUrl": "assets/images/cazador-intrusos/cofre.png", "isIntruder": false}], "title": "La casa del ogro", "bgImageUrl": "assets/images/cazador-intrusos/pulgarcito-casa-ogro-bg.jpg", "textDescription": "En la casa del ogro había unas botas de siete leguas, una corona de oro de sus hijas y un cofre repleto de tesoros.", "bgImageDescription": "Interior oscuro de una casa de ogro, con piedras y una chimenea al fondo, piso de piedra; espacio libre para 6 objetos."}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('c37adbe8-39cd-4ac6-af4c-b174cea6c5c7', '2026-11-19 12:31:21.139887-03', '2026-11-19 12:31:21.139887-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/pulgarcito-bosque.jpg", "storyTitle": "Pulgarcito", "targetArea": {"top": 55, "left": 30, "width": 40, "height": 37.5}, "textSnippet": "Entre las raíces de un viejo árbol, brillaba una de las piedrecitas blancas que Pulgarcito había dejado caer.", "imageDescription": "Primer plano del suelo de un bosque de noche, con luna y raíces gruesas de árboles. En la parte inferior, entre las raíces, una piedra blanca grande y lisa que brilla levemente bajo la luna. Escena muy recargada: el suelo está lleno de hojas, hongos, otras piedras de colores y formas parecidas, ramitas, migas de pan y pequeñas flores.", "targetObjectName": "Piedrecita blanca"}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('943b8481-b675-44cb-9415-a3407c95326b', '2026-11-19 12:31:21.140857-03', '2026-11-19 12:31:21.140857-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/pulgarcito-casa-ogro-busca.jpg", "storyTitle": "Pulgarcito", "targetArea": {"top": 30, "left": 68, "width": 25, "height": 40}, "textSnippet": "Colgadas junto a la chimenea de la casa del ogro, las enormes botas de siete leguas esperaban en la penumbra.", "imageDescription": "Interior de la casa del ogro con una chimenea y una olla. En la parte derecha, un par de botas de cuero colgando de la pared, con un leve destello mágico que las distingue de la penumbra.", "targetObjectName": "Botas de siete leguas"}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('517a8e03-82f7-405f-abd0-d9c8c019e66f', '2026-11-19 12:31:21.142858-03', '2026-11-19 12:31:21.142858-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Las piedrecitas blancas", "panels": [{"id": 1, "image": "assets/images/comics/pulgarcito1.png", "imageDescription": "Pulgarcito, escondido bajo el banco, escucha a sus padres hablar tristes en la cocina."}, {"id": 2, "image": "assets/images/comics/pulgarcito2.png", "imageDescription": "Pulgarcito llena sus bolsillos con piedrecitas blancas junto a un arroyo."}, {"id": 3, "image": "assets/images/comics/pulgarcito3.png", "imageDescription": "Los siete hermanos caminan por el bosque con el leñador; Pulgarcito deja caer piedrecitas."}, {"id": 4, "image": "assets/images/comics/pulgarcito4.png", "imageDescription": "Los niños regresan a casa siguiendo el camino de piedrecitas brillantes a la luz de la luna."}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('1f12c254-982e-469c-85c3-433f40ef8e06', '2026-11-19 12:31:21.143858-03', '2026-11-19 12:31:21.143858-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "Las botas del ogro", "panels": [{"id": 1, "image": "assets/images/comics/pulgarcito5.png", "imageDescription": "El ogro de ojos rojos persigue a los niños dando pasos enormes con sus botas de siete leguas."}, {"id": 2, "image": "assets/images/comics/pulgarcito6.png", "imageDescription": "El ogro, cansado, duerme sentado sobre una gran roca."}, {"id": 3, "image": "assets/images/comics/pulgarcito7.png", "imageDescription": "Pulgarcito, diminuto, tira de las botas del ogro dormido."}, {"id": 4, "image": "assets/images/comics/pulgarcito8.png", "imageDescription": "Pulgarcito se pone las botas gigantes, que se ajustan mágicamente, y se aleja corriendo."}]}', '15e30c6e-3c5d-406d-9714-357036fde5e4', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('f2248d01-f062-40bc-ade1-81f96903557a', '2026-11-19 12:31:21.146858-03', '2026-11-19 12:31:21.146858-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Barba Azul era un hombre rico.", "isTrue": true}, {"text": "Su barba era de color rojo.", "isTrue": false}, {"text": "La joven se casó con él después de visitar su castillo.", "isTrue": true}], "passage_text": "Un hombre muy rico tenía una barba azul que asustaba a todos. Pidió casarse con una joven del vecindario y ella aceptó después de visitar su magnífico castillo.", "time_per_statement": 7}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('02ad9328-5dca-4ae3-9976-7abd63cdeb18', '2026-11-19 12:31:21.147858-03', '2026-11-19 12:31:21.147858-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Barba Azul le entregó las llaves del castillo.", "isTrue": true}, {"text": "Le prohibió abrir una pequeña habitación.", "isTrue": true}, {"text": "Le prohibió salir al jardín.", "isTrue": false}], "passage_text": "Antes de partir de viaje, Barba Azul le entregó a su esposa las llaves de todo el castillo. Le permitió abrir cualquier puerta menos la de una pequeña habitación, cuya llave era diminuta.", "time_per_statement": 7}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('f1be2fac-a0d5-4041-b962-69f2fbefb5a8', '2026-11-19 12:31:21.150141-03', '2026-11-19 12:31:21.150141-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¿Por qué la llave está manchada? ¡Abriste la puerta prohibida!", "isCorrect": true}, {"text": "¡Qué alegría volver a verte, querida!", "isCorrect": false}, {"text": "¡Vamos a comer, tengo mucha hambre!", "isCorrect": false}, {"text": "¡Te traje un regalo de mi viaje!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/barba_azul_furioso.png", "imageDescription": "Un hombre alto con larga barba azul y capa oscura, con el rostro enfurecido y una espada en la mano, en el vestíbulo de un castillo."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('4d069bef-b3b1-427e-afa7-1a7731371af0', '2026-11-19 12:31:21.151046-03', '2026-11-19 12:31:21.151046-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Un pirata", "El rey", "Barba Azul", "El mago", "El caballero"], "imageSrc": "assets/images/pixelado/barba_azul_personaje.png", "correctCharacter": "Barba Azul", "imageDescription": "Barba Azul: hombre alto y elegante con una larga barba de color azul oscuro, ropa lujosa de terciopelo y mirada seria."}], "total_time": 7}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('78112b3a-01f9-40df-9b9d-658f98b4cee2', '2026-11-19 12:31:21.152046-03', '2026-11-19 12:31:21.152046-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["La corona real", "La llave manchada", "Un collar de perlas", "Un reloj antiguo", "Una vela roja"], "imageSrc": "assets/images/pixelado/barba_azul_llave.png", "correctCharacter": "La llave manchada", "imageDescription": "Una pequeña llave dorada con manchas rojas, apoyada sobre un cojín de terciopelo azul."}], "total_time": 7}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('aa999e30-2e79-400b-b375-d67703ed9bdc', '2026-11-19 12:31:21.154045-03', '2026-11-19 12:31:21.154045-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 721, "altText": "La esposa recorriendo el castillo", "imageSrc": "assets/images/contra/barba_azul_esposa_castillo.png", "isContradiction": false, "imageDescription": "Una joven con vestido azul y llaves en la mano, caminando por una galería con cuadros."}, {"id": 722, "altText": "Baúl con joyas", "imageSrc": "assets/images/contra/barba_azul_baul_joyas.png", "isContradiction": false, "imageDescription": "Un baúl antiguo abierto, lleno de collares y monedas de oro."}, {"id": 723, "altText": "Barba Azul con ramo de flores", "imageSrc": "assets/images/contra/barba_azul_ramo_flores.png", "isContradiction": true, "imageDescription": "Barba Azul entregando un ramo de flores amarillas a su esposa, sonriendo."}, {"id": 724, "altText": "Manojo de llaves", "imageSrc": "assets/images/contra/barba_azul_manojo_llaves.png", "isContradiction": false, "imageDescription": "Un gran manojo de llaves antiguas de hierro y una pequeña dorada, sobre una mesa."}], "explanation": "La imagen contradictoria muestra a Barba Azul entregando un ramo de flores amarillas en lugar de las llaves.", "premiseText": "Barba Azul le entregó a su esposa un manojo de llaves para abrir los baúles y habitaciones del castillo."}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('ef84588b-dfff-4787-95b2-cebbc5d9fb14', '2026-11-19 12:31:21.155044-03', '2026-11-19 12:31:21.155044-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 731, "altText": "Niños asustados", "imageSrc": "assets/images/contra/barba_azul_ninos_asustados.png", "isContradiction": false, "imageDescription": "Niños del pueblo escondidos tras una pared mirando con miedo a un hombre de barba azul."}, {"id": 732, "altText": "Barba Azul a caballo", "imageSrc": "assets/images/contra/barba_azul_a_caballo.png", "isContradiction": false, "imageDescription": "Un hombre de barba larga azul y capa oscura montando un caballo negro."}, {"id": 733, "altText": "Hombre de barba rubia", "imageSrc": "assets/images/contra/barba_azul_barba_rubia.png", "isContradiction": true, "imageDescription": "Un hombre de barba rubia corta y rizada, vestido con ropa lujosa, sonriendo."}, {"id": 734, "altText": "Retrato de Barba Azul", "imageSrc": "assets/images/contra/barba_azul_retrato.png", "isContradiction": false, "imageDescription": "Retrato pintado de un hombre con la barba azul peinada en dos puntas."}], "explanation": "La imagen contradictoria muestra a un hombre de barba rubia, corta y rizada, que sonríe amablemente.", "premiseText": "Barba Azul tenía una larga barba azul que asustaba a todos."}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('00e97a20-c582-4223-9b72-150eec956a0b', '2026-11-19 12:31:21.157044-03', '2026-11-19 12:31:21.157044-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La llave prohibida", "fragments": [{"id": 1, "text": "Barba Azul se casa con una joven y la lleva a vivir a su gran castillo."}, {"id": 2, "text": "Barba Azul debe partir de viaje y le deja a su esposa todas las llaves."}, {"id": 3, "text": "La esposa invita a sus amigas a recorrer el castillo y todas admiran sus riquezas."}, {"id": 4, "text": "Vencida por la curiosidad, abre la puerta prohibida con la pequeña llave."}, {"id": 5, "text": "Dentro de la habitación descubre el terrible secreto y la llave cae manchada."}]}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('cd1472e2-1b80-4170-a625-a757b027af4c', '2026-11-19 12:31:21.158046-03', '2026-11-19 12:31:21.158046-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El rescate", "fragments": [{"id": 1, "text": "Barba Azul regresa de improviso y le pide las llaves a su esposa."}, {"id": 2, "text": "Al ver la llave manchada, Barba Azul comprende que ella abrió la puerta prohibida."}, {"id": 3, "text": "La esposa pide un cuarto de hora para rezar y sube a la torre con su hermana Ana."}, {"id": 4, "text": "Ana vigila desde la torre y por fin ve a los hermanos acercarse a caballo."}, {"id": 5, "text": "Los hermanos llegan al castillo y ponen fin a Barba Azul."}]}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('def9c793-b50e-48f2-8c9f-68dfedbde168', '2026-11-19 12:31:21.159076-03', '2026-11-19 12:31:21.159076-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["blanca", "azul", "roja", "verde"], "timeLeft": 7.0, "textAfter": "que asustaba a todos.", "textBefore": "Barba Azul tenía una barba de color", "correctWord": "azul"}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('d32f265f-9332-4437-b301-2c6e65174f48', '2026-11-19 12:31:21.160045-03', '2026-11-19 12:31:21.160045-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["María", "Rosa", "Ana", "Laura"], "timeLeft": 7.0, "textAfter": "para esperar a sus hermanos.", "textBefore": "La esposa subió a la torre con su hermana", "correctWord": "Ana"}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('8695c282-2b5d-4e7e-933b-4b1fca1a7446', '2026-11-19 12:31:21.162045-03', '2026-11-19 12:31:21.162045-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El salón del castillo", "imageUrl": "assets/images/testigo/barba_azul_salon.png", "questions": [{"prompt": "¿Cuántas velas tenía el candelabro?", "options": ["Cinco", "Cuatro", "Siete", "Tres"], "correctOption": "Cinco"}, {"prompt": "¿De qué color era el sofá?", "options": ["Azul", "Rojo", "Amarillo", "Verde"], "correctOption": "Verde"}, {"prompt": "¿Qué había sobre la mesa?", "options": ["Un manojo de llaves", "Un libro", "Un florero", "Una bandeja de frutas"], "correctOption": "Un manojo de llaves"}], "imageDescription": "Lujoso salón de un castillo: una gran mesa cubierta con mantel rojo; un candelabro de cinco velas encendidas; un sofá de terciopelo verde; una ventana alta con cortinas azules; sobre la mesa, un manojo de llaves."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('85229812-a502-46bd-a7b1-da5a604eb28d', '2026-11-19 12:31:21.163046-03', '2026-11-19 12:31:21.163046-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La torre del castillo", "imageUrl": "assets/images/testigo/barba_azul_torre_ana.png", "questions": [{"prompt": "¿De qué color era el vestido de Ana?", "options": ["Blanco", "Verde", "Rosa", "Amarillo"], "correctOption": "Amarillo"}, {"prompt": "¿Cuántos jinetes se veían a lo lejos?", "options": ["Cuatro", "Tres", "Uno", "Dos"], "correctOption": "Dos"}, {"prompt": "¿De qué color eran las capas de los jinetes?", "options": ["Azules", "Negras", "Rojas", "Verdes"], "correctOption": "Rojas"}], "imageDescription": "Torre de piedra con una ventana alta; en ella, la esposa con vestido rosa y su hermana Ana con vestido amarillo, mirando un camino de tierra; a lo lejos una nube de polvo y dos jinetes con capas rojas; sol brillante y colinas verdes."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('a0a4c2dc-d7dd-4ef9-a458-9d43e2de8017', '2026-11-19 12:31:21.164075-03', '2026-11-19 12:31:21.164075-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-2", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-3", "name": "Cofre de joyas", "imageUrl": "assets/images/cazador-intrusos/cofre.png", "isIntruder": false}, {"id": "item-4", "name": "Manojo de llaves", "imageUrl": "assets/images/cazador-intrusos/llaves-antiguas.png", "isIntruder": false, "imageDescription": "Manojo de llaves antiguas de hierro con una llave pequeña dorada, fondo transparente."}, {"id": "item-5", "name": "Jarra de plata", "imageUrl": "assets/images/cazador-intrusos/jarra-plata.png", "isIntruder": false}, {"id": "item-6", "name": "Copa de oro", "imageUrl": "assets/images/cazador-intrusos/copa.png", "isIntruder": false}], "title": "El tesoro del castillo", "bgImageUrl": "assets/images/cazador-intrusos/barba-azul-tesoro-bg.jpg", "textDescription": "En la sala del tesoro de Barba Azul brillaban un cofre de joyas, una copa de oro, una jarra de plata y un manojo de llaves antiguas.", "bgImageDescription": "Sala de un castillo con paredes de piedra, alfombra roja y estantes de madera vacíos; espacio libre para 6 objetos."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('24cf0e49-b71f-4fdf-abc6-fecc34ef5160', '2026-11-19 12:31:21.165399-03', '2026-11-19 12:31:21.165399-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}, {"id": "item-2", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-3", "name": "Espada de caballero", "imageUrl": "assets/images/cazador-intrusos/espada-caballero.png", "isIntruder": false, "imageDescription": "Espada recta de caballero con empuñadura dorada, fondo transparente."}, {"id": "item-4", "name": "Monopatín", "imageUrl": "assets/images/cazador-intrusos/monopatin.png", "isIntruder": true}, {"id": "item-5", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-6", "name": "Capa de jinete", "imageUrl": "assets/images/cazador-intrusos/capa.png", "isIntruder": false}], "title": "El camino a la torre", "bgImageUrl": "assets/images/cazador-intrusos/barba-azul-camino-bg.jpg", "textDescription": "Desde la torre se veían llegar los hermanos con sus capas y sus espadas, galopando por el camino polvoriento.", "bgImageDescription": "Camino de tierra entre colinas verdes visto desde una torre, cielo azul con nubes; espacio libre para 6 objetos."}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('2ce0952c-629f-4d22-b0c8-20e76f45cb74', '2026-11-19 12:31:21.166408-03', '2026-11-19 12:31:21.166408-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/barba-azul-salon-busca.jpg", "storyTitle": "Barba Azul", "targetArea": {"top": 50, "left": 25, "width": 50, "height": 30}, "textSnippet": "Sobre una mesita del salón, junto al jarrón de flores, brillaba una pequeña llave dorada olvidada.", "imageDescription": "Primer plano de una mesita de un salón lujoso, con un jarrón de flores. En la parte central-inferior, una llave dorada grande sobre la mesa, cuyo brillo la distingue del mantel. Escena muy recargada: la mesita está llena de candelabros, copas, platos, otras llaves de distintos tamaños, joyas, cartas y adornos de porcelana.", "targetObjectName": "Pequeña llave dorada"}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('11ef4d07-5164-4192-a220-9f920847c599', '2026-11-19 12:31:21.167408-03', '2026-11-19 12:31:21.167408-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/barba-azul-torre-busca.jpg", "storyTitle": "Barba Azul", "targetArea": {"top": 18, "left": 42, "width": 50, "height": 20}, "textSnippet": "En lo alto de la torre, la hermana Ana miraba el horizonte con un largo catalejo de bronce.", "imageDescription": "Torre de piedra con una ventana alta que da al campo. En la parte superior, Ana sostiene un catalejo de bronce, con un destello leve que lo distingue de la piedra.", "targetObjectName": "Catalejo"}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('0f45a61a-3887-4348-8b09-6fb65f452dc4', '2026-11-19 12:31:21.168409-03', '2026-11-19 12:31:21.168409-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La llave prohibida", "panels": [{"id": 1, "image": "assets/images/comics/barba_azul1.png", "imageDescription": "Barba Azul entrega un manojo de llaves a su esposa en el vestíbulo y se despide con una maleta."}, {"id": 2, "image": "assets/images/comics/barba_azul2.png", "imageDescription": "La esposa, sola, recorre las salas del castillo con las llaves."}, {"id": 3, "image": "assets/images/comics/barba_azul3.png", "imageDescription": "Frente a una puerta pequeña, la esposa duda con la llave dorada en la mano."}, {"id": 4, "image": "assets/images/comics/barba_azul4.png", "imageDescription": "La esposa abre la puerta con la llave temblando de miedo."}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('5a38c3c6-80a8-46ac-961b-adf1ae5e6879', '2026-11-19 12:31:21.170114-03', '2026-11-19 12:31:21.170114-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "Los hermanos al rescate", "panels": [{"id": 1, "image": "assets/images/comics/barba_azul5.png", "imageDescription": "Barba Azul regresa y mira furioso la llave que la esposa le entrega."}, {"id": 2, "image": "assets/images/comics/barba_azul6.png", "imageDescription": "La esposa y su hermana Ana suben a la torre."}, {"id": 3, "image": "assets/images/comics/barba_azul7.png", "imageDescription": "Desde la torre, Ana ve a lo lejos dos jinetes que galopan levantando polvo."}, {"id": 4, "image": "assets/images/comics/barba_azul8.png", "imageDescription": "Los dos hermanos llegan al patio del castillo con las espadas en alto."}]}', '3f91bf49-1595-4714-bd5b-4aaad86a295e', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('c87bffc3-380d-49d1-9e73-afc9a05bd081', '2026-11-19 12:31:21.173131-03', '2026-11-19 12:31:21.173131-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Karen era una niña pobre.", "isTrue": true}, {"text": "Karen tenía muchos zapatos de cuero.", "isTrue": false}, {"text": "Karen usó los zapatos rojos en el funeral de su madre.", "isTrue": true}], "passage_text": "Karen era una niña muy pobre que andaba descalza. Un zapatero le hizo con retazos de paño rojo unos zapatitos toscos. Los usó en el funeral de su madre.", "time_per_statement": 7}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('0fb23604-78ec-456a-b531-b16e102f7b0c', '2026-11-19 12:31:21.175122-03', '2026-11-19 12:31:21.175122-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Estoy tan feliz de andar descalza!", "isCorrect": false}, {"text": "¡Qué lindo día para tomar una siesta!", "isCorrect": false}, {"text": "¡No puedo parar de bailar, los zapatos no me obedecen!", "isCorrect": true}, {"text": "¡Voy a hacer un picnic con mis amigos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/zapatos_karen_baila.png", "imageDescription": "Karen, una niña con vestido blanco y zapatos rojos brillantes, bailando sin control en un campo, con una cara de miedo y las manos extendidas."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('3a3c0818-ea93-41ed-aac9-df67dac49fb3', '2026-11-19 12:31:21.176156-03', '2026-11-19 12:31:21.176156-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Entra a comer pastel!", "isCorrect": false}, {"text": "¡Te regalo unos zapatos nuevos de oro!", "isCorrect": false}, {"text": "¡Bailarás con tus zapatos rojos hasta quedar pálida y fría!", "isCorrect": true}, {"text": "¡Bienvenida a la fiesta, Karen!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/zapatos_angel.png", "imageDescription": "Un ángel con túnica blanca, alas y una espada brillante, serio, de pie ante la puerta de una iglesia frente a Karen."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('6afce76f-6147-4742-9148-3224b6e9cdbe', '2026-11-19 12:31:21.178122-03', '2026-11-19 12:31:21.178122-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Unas pantuflas azules", "Unas zapatillas deportivas", "Unas botas de nieve", "Los zapatos rojos", "Unos zuecos de madera"], "imageSrc": "assets/images/pixelado/zapatos_par_rojo.png", "correctCharacter": "Los zapatos rojos", "imageDescription": "Un par de zapatos rojos brillantes de charol, con un pequeño lazo, sobre el suelo de piedra de una iglesia."}], "total_time": 7}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('26e83400-0b2d-47fb-b871-7ce97ee3e98c', '2026-11-19 12:31:21.179121-03', '2026-11-19 12:31:21.179121-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["El zapatero", "El ángel", "El soldado de barba roja", "El pastor", "El verdugo"], "imageSrc": "assets/images/pixelado/zapatos_soldado.png", "correctCharacter": "El soldado de barba roja", "imageDescription": "Un viejo soldado de barba roja larga y rizada, con un abrigo viejo, apoyado en una muleta junto a la puerta de una iglesia."}], "total_time": 7}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('6883419c-42e1-4f5b-bb1b-648395be1f15', '2026-11-19 12:31:21.180122-03', '2026-11-19 12:31:21.180122-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 741, "altText": "Zapatos que saltan", "imageSrc": "assets/images/contra/zapatos_saltan_pasto.png", "isContradiction": false, "imageDescription": "Un par de zapatos rojos brillantes saltando sobre el pasto, con las piernas de Karen en el aire."}, {"id": 742, "altText": "Karen leyendo tranquila", "imageSrc": "assets/images/contra/zapatos_karen_lee.png", "isContradiction": true, "imageDescription": "Karen sentada en un banco leyendo un libro con zapatos rojos puestos, con expresión tranquila."}, {"id": 743, "altText": "Karen bailando en el campo", "imageSrc": "assets/images/contra/zapatos_baila_campo.png", "isContradiction": false, "imageDescription": "Karen bailando con los brazos extendidos en un campo de trigo, con zapatos rojos."}, {"id": 744, "altText": "Karen bailando entre árboles", "imageSrc": "assets/images/contra/zapatos_baila_bosque.png", "isContradiction": false, "imageDescription": "Karen con zapatos rojos bailando entre los árboles de un bosque en otoño."}], "explanation": "La imagen contradictoria muestra a Karen sentada, tranquila, leyendo un libro con los zapatos puestos.", "premiseText": "Karen se puso los zapatos rojos y no podía dejar de bailar por campos y bosques."}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('8bcea608-82a3-4280-bdfc-cf3d85abee7a', '2026-11-19 12:31:21.181122-03', '2026-11-19 12:31:21.181122-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 751, "altText": "Ángel con espada", "imageSrc": "assets/images/contra/zapatos_angel_espada.png", "isContradiction": false, "imageDescription": "Un ángel con túnica blanca y una espada brillante frente a la puerta de una iglesia."}, {"id": 752, "altText": "Payaso con globos", "imageSrc": "assets/images/contra/zapatos_payaso.png", "isContradiction": true, "imageDescription": "Un payaso con globos de colores parado frente a Karen y la puerta de una iglesia."}, {"id": 753, "altText": "Karen mirando al ángel", "imageSrc": "assets/images/contra/zapatos_karen_asustada.png", "isContradiction": false, "imageDescription": "Karen con zapatos rojos mirando hacia arriba con miedo, delante de un ángel."}, {"id": 754, "altText": "Ángel con alas desplegadas", "imageSrc": "assets/images/contra/zapatos_angel_alas.png", "isContradiction": false, "imageDescription": "Un ángel con las alas abiertas sobre el tejado de una iglesia, rodeado de luz."}], "explanation": "La imagen contradictoria muestra a un payaso con globos de colores frente a Karen.", "premiseText": "Un ángel con una espada se le apareció a Karen delante de la iglesia."}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('d62c860c-703c-43ae-8199-bc85c1dacd5a', '2026-11-19 12:31:21.183123-03', '2026-11-19 12:31:21.183123-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El primer baile", "fragments": [{"id": 1, "text": "Karen, una niña pobre, recibe unos zapatitos rojos cosidos por un zapatero."}, {"id": 2, "text": "Una anciana rica la adopta y le compra unos hermosos zapatos rojos nuevos."}, {"id": 3, "text": "Karen los usa en la iglesia, pensando solo en ellos y no en rezar."}, {"id": 4, "text": "Un viejo soldado de barba roja toca las suelas y los zapatos empiezan a bailar solos."}, {"id": 5, "text": "Karen no puede detenerse y baila por campos y bosques."}]}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('879d01ab-f7ae-4cf1-9a2a-9586e3f339ff', '2026-11-19 12:31:21.184124-03', '2026-11-19 12:31:21.184124-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El castigo y el perdón", "fragments": [{"id": 1, "text": "Un ángel con espada le dice que bailará hasta quedar pálida y fría."}, {"id": 2, "text": "Karen llega a la casa del verdugo y le pide que le corte los pies con los zapatos."}, {"id": 3, "text": "Los zapatos siguen bailando solos por el bosque, mientras Karen recibe pies de madera."}, {"id": 4, "text": "Karen trabaja sirviendo en la casa del pastor y se arrepiente sinceramente."}, {"id": 5, "text": "Con el corazón humilde, Karen reza, la luz inunda su alma y encuentra la paz."}]}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('29ceaa2d-28c3-44b9-84f6-8caf3c5d3583', '2026-11-19 12:31:21.185147-03', '2026-11-19 12:31:21.185147-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["azules", "blancos", "negros", "rojos"], "timeLeft": 7.0, "textAfter": "porque le parecían los más hermosos.", "textBefore": "Karen eligió unos zapatos", "correctWord": "rojos"}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('5929e635-dfbf-4370-9ce3-92df18da77af', '2026-11-19 12:31:21.186149-03', '2026-11-19 12:31:21.186149-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["baile", "trabajo", "lluvia", "nieve"], "timeLeft": 7.0, "textAfter": "!»", "textBefore": "El viejo soldado dijo: «¡Qué hermosos zapatos de", "correctWord": "baile"}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('3ca59fa5-232d-4714-819f-040945ca791c', '2026-11-19 12:31:21.188121-03', '2026-11-19 12:31:21.188121-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La iglesia", "imageUrl": "assets/images/testigo/zapatos_iglesia_interior.png", "questions": [{"prompt": "¿De qué color eran los zapatos de Karen?", "options": ["Blancos", "Rojos", "Azules", "Negros"], "correctOption": "Rojos"}, {"prompt": "¿Qué llevaba la anciana en la mano?", "options": ["Un paraguas", "Un libro", "Un bastón", "Una cesta"], "correctOption": "Un bastón"}, {"prompt": "¿De qué color eran los vitrales?", "options": ["Verdes", "Rosados", "Amarillos", "Azules"], "correctOption": "Azules"}], "imageDescription": "Interior de una iglesia antigua: bancos de madera con personas vestidas de negro; Karen de pie con vestido blanco y zapatos rojos brillantes que destacan; una anciana con bastón y vestido negro; un gran ventanal con vitrales azules."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('15712bc4-00b4-47bf-8a07-b16339d5227c', '2026-11-19 12:31:21.189121-03', '2026-11-19 12:31:21.189121-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El camino del bosque", "imageUrl": "assets/images/testigo/zapatos_bosque_otono.png", "questions": [{"prompt": "¿Qué estación parecía ser?", "options": ["Verano", "Invierno", "Primavera", "Otoño"], "correctOption": "Otoño"}, {"prompt": "¿Qué animal negro estaba en la rama?", "options": ["Una paloma", "Un gato", "Un cuervo", "Un búho"], "correctOption": "Un cuervo"}, {"prompt": "¿Qué animal rojizo miraba entre los arbustos?", "options": ["Un ciervo", "Un zorro", "Un lobo", "Un conejo"], "correctOption": "Un zorro"}], "imageDescription": "Camino de otoño en un bosque con hojas naranjas; un par de zapatos rojos bailando en el aire con piernas de niña; un cuervo negro sobre una rama; un zorro rojizo mirando entre los arbustos; sol bajo entre los árboles."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('c89af47f-d1e1-4024-9ed7-c3b90a529b3c', '2026-11-19 12:31:21.191122-03', '2026-11-19 12:31:21.191122-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-2", "name": "Zapatos rojos", "imageUrl": "assets/images/cazador-intrusos/zapatos-rojos.png", "isIntruder": false, "imageDescription": "Par de zapatos rojos brillantes con un lazo pequeño, fondo transparente."}, {"id": "item-3", "name": "Retazos de paño rojo", "imageUrl": "assets/images/cazador-intrusos/tela-roja.png", "isIntruder": false, "imageDescription": "Tres trozos de tela roja doblados y apilados, fondo transparente."}, {"id": "item-4", "name": "Botas de cuero", "imageUrl": "assets/images/cazador-intrusos/botas.png", "isIntruder": false}, {"id": "item-5", "name": "Extintor de incendios", "imageUrl": "assets/images/cazador-intrusos/extintor-incendios.png", "isIntruder": true}, {"id": "item-6", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}], "title": "El taller del zapatero", "bgImageUrl": "assets/images/cazador-intrusos/zapatos-taller-bg.jpg", "textDescription": "En el taller del zapatero había unos zapatos rojos terminados, retazos de paño rojo y un par de botas de cuero.", "bgImageDescription": "Taller de zapatero rústico con estante de madera, mesa de trabajo y ventana con luz cálida; espacio libre para 6 objetos."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('24b7b97c-b60d-470b-b801-225ab26c0a1f', '2026-11-19 12:31:21.192086-03', '2026-11-19 12:31:21.192086-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Flores del altar", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-2", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-3", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-4", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}, {"id": "item-5", "name": "Vela encendida", "imageUrl": "assets/images/cazador-intrusos/vela.png", "isIntruder": false, "imageDescription": "Vela blanca encendida con una pequeña llama, fondo transparente."}, {"id": "item-6", "name": "Campana de iglesia", "imageUrl": "assets/images/cazador-intrusos/campana.png", "isIntruder": false, "imageDescription": "Campana de bronce antigua, fondo transparente."}], "title": "La iglesia del pueblo", "bgImageUrl": "assets/images/cazador-intrusos/zapatos-iglesia-bg.jpg", "textDescription": "En la iglesia del pueblo había flores en el altar, velas encendidas y una campana en lo alto de la torre.", "bgImageDescription": "Entrada de una iglesia de piedra con puerta de madera grande y escalones, sin objetos pequeños; espacio libre para 6 objetos."}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('c74dedb4-6b1b-4596-8298-85561107f6f9', '2026-11-19 12:31:21.19354-03', '2026-11-19 12:31:21.19354-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/zapatos-iglesia-busca.jpg", "storyTitle": "Los zapatos rojos", "targetArea": {"top": 62, "left": 25, "width": 50, "height": 30}, "textSnippet": "Sobre el escalón de la entrada de la iglesia, un par de zapatos rojos brillaba bajo el sol.", "imageDescription": "Entrada de una iglesia de piedra con tres escalones. En la parte inferior, un par de zapatos rojos grandes sobre el escalón, que destacan levemente por su color rojo apagado frente a la piedra sepia. Escena muy recargada: la entrada tiene muchos zapatos de distintos tipos, flores, velas, bancos, personas de espaldas y farolillos.", "targetObjectName": "Zapatos rojos"}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('014695ec-fb1d-4089-85f3-2179943baece', '2026-11-19 12:31:21.194553-03', '2026-11-19 12:31:21.194553-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/zapatos-camino-busca.jpg", "storyTitle": "Los zapatos rojos", "targetArea": {"top": 12, "left": 58, "width": 32, "height": 31.25}, "textSnippet": "En la rama más alta de un árbol del camino, un cuervo observaba a Karen en silencio.", "imageDescription": "Camino de otoño con unos pocos árboles de hojas anaranjadas. En la parte superior derecha, un cuervo negro posado en una rama, con un contorno algo más marcado que el follaje.", "targetObjectName": "Cuervo"}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('ec8ba2ab-ee20-43ad-b689-ce58c0d01976', '2026-11-19 12:31:21.195568-03', '2026-11-19 12:31:21.195568-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Los zapatos de baile", "panels": [{"id": 1, "image": "assets/images/comics/zapatos1.png", "imageDescription": "Un zapatero cose unos zapatitos rojos de tela para una niña pobre."}, {"id": 2, "image": "assets/images/comics/zapatos2.png", "imageDescription": "Karen entra a la iglesia con los zapatos rojos nuevos, mirando solo sus pies."}, {"id": 3, "image": "assets/images/comics/zapatos3.png", "imageDescription": "Un soldado de barba roja golpea las suelas diciendo que son zapatos de baile."}, {"id": 4, "image": "assets/images/comics/zapatos4.png", "imageDescription": "Los zapatos empiezan a bailar con Karen por las calles del pueblo."}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('56397b60-9e07-44c9-8cad-a6b7f10392cc', '2026-11-19 12:31:22.399979-03', '2026-11-19 12:31:22.399979-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Una cama", "Un órgano", "Una ventana", "Un arpa", "El telar vacío"], "imageSrc": "assets/images/pixelado/traje_telar_vacio.png", "correctCharacter": "El telar vacío", "imageDescription": "Un telar de madera con hilos dorados tensos pero sin tela, con dos tejedores fingiendo trabajar a los lados."}], "total_time": 7}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('dc1ec715-ba80-4b07-9fb4-5bffd06d6bc6', '2026-11-19 12:31:21.196542-03', '2026-11-19 12:31:21.196542-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La paz de Karen", "panels": [{"id": 1, "image": "assets/images/comics/zapatos5.png", "imageDescription": "Un ángel con espada detiene a Karen ante la puerta de una iglesia."}, {"id": 2, "image": "assets/images/comics/zapatos6.png", "imageDescription": "Karen, con pies de madera y muletas, trabaja como sirvienta en la casa del pastor."}, {"id": 3, "image": "assets/images/comics/zapatos7.png", "imageDescription": "Karen reza con humildad en una habitación sencilla y una luz brillante entra por la ventana."}, {"id": 4, "image": "assets/images/comics/zapatos8.png", "imageDescription": "Karen sonríe en paz mientras la luz la rodea."}]}', 'a9460cb0-7222-49a1-bda4-cd2038274079', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('c66b709e-6571-4231-b5ac-d2aa3266ea40', '2026-11-19 12:31:21.200538-03', '2026-11-19 12:31:21.200538-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Blancanieves tenía el cabello negro como el ébano.", "isTrue": true}, {"text": "El espejo mágico de la reina mentía.", "isTrue": false}, {"text": "La reina era la madrastra de Blancanieves.", "isTrue": true}], "passage_text": "Blancanieves era una niña de piel blanca como la nieve y cabello negro como el ébano. Su madrastra, la reina, tenía un espejo mágico que siempre decía la verdad.", "time_per_statement": 7}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('24122c97-25e6-4f30-bfb2-24d2ba1115a5', '2026-11-19 12:31:21.200538-03', '2026-11-19 12:31:21.200538-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La reina ordenó a un cazador llevarse a Blancanieves.", "isTrue": true}, {"text": "El cazador cumplió la orden sin dudar.", "isTrue": false}, {"text": "Blancanieves logró escapar.", "isTrue": true}], "passage_text": "Cuando el espejo dijo que Blancanieves era más bella, la reina ordenó a un cazador llevarla al bosque. El cazador sintió lástima y la dejó escapar.", "time_per_statement": 7}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c64476ad-3271-48ce-be22-9dc71f697e12', '2026-11-19 12:31:21.202539-03', '2026-11-19 12:31:21.202539-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Qué lindo día para salir a pasear!", "isCorrect": false}, {"text": "¡Espejito, espejito, dime quién es la más bella del reino!", "isCorrect": true}, {"text": "¡Hoy haré un pastel de chocolate!", "isCorrect": false}, {"text": "¡Espejito, necesito que me prestes tu marco!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/blancanieves_reina_espejo.png", "imageDescription": "Una reina con corona negra y dorada y vestido morado, frente a un espejo mágico de marco dorado en el que brilla un rostro; la reina tiene el ceño fruncido."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('6ecf13db-ccf4-49ab-9498-177ce8a36f7b', '2026-11-19 12:31:21.203538-03', '2026-11-19 12:31:21.203538-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¿Quién ha estado durmiendo en nuestras camitas?", "isCorrect": true}, {"text": "¡Mañana pintaremos la casa de azul!", "isCorrect": false}, {"text": "¡Qué rico huele el pastel de zanahoria!", "isCorrect": false}, {"text": "¡Ya es hora de dormir todos juntos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/blancanieves_enanitos.png", "imageDescription": "Siete enanitos con gorros de colores, de pie junto a una mesa pequeña con siete platitos, mirando asombrados a una niña dormida en una de sus camitas."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('7fb93264-879c-449f-ad58-26b781b157f8', '2026-11-19 12:31:21.204541-03', '2026-11-19 12:31:21.205569-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El espejo mágico", "Un cuadro del rey", "Un reloj de pared", "La puerta del castillo", "Una ventana del palacio"], "imageSrc": "assets/images/pixelado/blancanieves_espejo.png", "correctCharacter": "El espejo mágico", "imageDescription": "Un espejo mágico de marco dorado y adornos de flores, con un rostro de niebla verdosa brillando en su superficie, sobre una pared de piedra."}], "total_time": 7}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('cfbe8d53-61c9-4d77-9200-533cd1ac455a', '2026-11-19 12:31:21.206539-03', '2026-11-19 12:31:21.206539-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Los cuatro músicos", "Los cinco duendes", "Los tres cerditos", "Los siete enanitos", "Los dos hermanos"], "imageSrc": "assets/images/pixelado/blancanieves_siete_enanitos.png", "correctCharacter": "Los siete enanitos", "imageDescription": "Siete enanitos con gorros de colores diferentes, cada uno con un pico o un farol, caminando en fila por un bosque."}], "total_time": 7}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('103998c9-da87-4f7c-87f8-def09fa2efa3', '2026-11-19 12:31:21.207543-03', '2026-11-19 12:31:21.207543-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 761, "altText": "Blancanieves en la ventana", "imageSrc": "assets/images/contra/blancanieves_ventana_cabana.png", "isContradiction": false, "imageDescription": "Blancanieves asomada a la ventana de una cabaña, con curiosidad."}, {"id": 762, "altText": "Anciana ofreciendo una banana", "imageSrc": "assets/images/contra/blancanieves_anciana_banana.png", "isContradiction": true, "imageDescription": "Una anciana con capa oscura ofreciendo una banana verde a Blancanieves en la ventana."}, {"id": 763, "altText": "Manzana roja brillante", "imageSrc": "assets/images/contra/blancanieves_manzana_roja.png", "isContradiction": false, "imageDescription": "Una manzana roja brillante con una pequeña mordida, sobre el suelo del bosque."}, {"id": 764, "altText": "Anciana con cesta de manzanas", "imageSrc": "assets/images/contra/blancanieves_anciana_cesta.png", "isContradiction": false, "imageDescription": "Una anciana encorvada con capa oscura sostiene una cesta llena de manzanas rojas."}], "explanation": "La imagen contradictoria muestra a la anciana ofreciendo una banana verde en lugar de una manzana roja.", "premiseText": "La reina, disfrazada de anciana, le ofreció a Blancanieves una manzana roja envenenada."}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('ad56afe2-1e85-4605-ac24-e6ee08182673', '2026-11-19 12:31:21.208539-03', '2026-11-19 12:31:21.208539-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 771, "altText": "Enanitos con faroles", "imageSrc": "assets/images/contra/blancanieves_enanitos_faroles.png", "isContradiction": false, "imageDescription": "Enanitos con faroles encendidos caminando por un túnel de roca."}, {"id": 772, "altText": "Enanitos jugando fútbol", "imageSrc": "assets/images/contra/blancanieves_enanitos_futbol.png", "isContradiction": true, "imageDescription": "Siete enanitos con gorros de colores jugando fútbol con un balón en un campo de pasto."}, {"id": 773, "altText": "Enanitos entrando a la mina", "imageSrc": "assets/images/contra/blancanieves_enanitos_mina.png", "isContradiction": false, "imageDescription": "Siete enanitos con picos al hombro entrando a una mina por una boca oscura entre rocas."}, {"id": 774, "altText": "Carretilla con gemas", "imageSrc": "assets/images/contra/blancanieves_carretilla_gemas.png", "isContradiction": false, "imageDescription": "Una carretilla de madera llena de piedras preciosas de colores brillantes."}], "explanation": "La imagen contradictoria muestra a los siete enanitos jugando fútbol en un campo de pasto.", "premiseText": "Los siete enanitos trabajaban cada día en una mina buscando oro y piedras preciosas."}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('82515ce7-fdff-429c-ae8c-f15ab9f3eb0a', '2026-11-19 12:31:21.209539-03', '2026-11-19 12:31:21.209539-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La huida al bosque", "fragments": [{"id": 1, "text": "La reina le pregunta al espejo mágico quién es la más bella y este responde que Blancanieves."}, {"id": 2, "text": "La reina ordena a un cazador llevarla al bosque."}, {"id": 3, "text": "El cazador se compadece y deja que Blancanieves huya."}, {"id": 4, "text": "Blancanieves encuentra una casita y se queda dormida en las camitas de los enanitos."}, {"id": 5, "text": "Los siete enanitos regresan de la mina y la acogen."}]}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('cb6d0df2-6d29-4cba-8733-c6bf79a36324', '2026-11-19 12:31:21.211284-03', '2026-11-19 12:31:21.211284-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La manzana envenenada", "fragments": [{"id": 1, "text": "La reina descubre que Blancanieves sigue viva y vive con los enanitos."}, {"id": 2, "text": "Disfrazada de anciana, la reina visita la casita con una cesta de manzanas."}, {"id": 3, "text": "Blancanieves muerde la manzana envenenada y cae como muerta."}, {"id": 4, "text": "Los enanitos la colocan en un ataúd de cristal."}, {"id": 5, "text": "Un príncipe la ve y, al moverse el ataúd, el pedazo de manzana sale de su garganta y ella despierta."}]}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('563a7695-d5c3-4bd1-8e24-c862f363c017', '2026-11-19 12:31:21.212322-03', '2026-11-19 12:31:21.212322-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["joven", "rápida", "bella", "fuerte"], "timeLeft": 7.0, "textAfter": "del reino? —preguntó la reina.", "textBefore": "—Espejito, espejito, ¿quién es la más", "correctWord": "bella"}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('da42cd22-c0bb-47a7-a1f0-8d7e78cee78b', '2026-11-19 12:31:21.213293-03', '2026-11-19 12:31:21.213293-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["caballeros", "cazadores", "enanitos", "gigantes"], "timeLeft": 7.0, "textAfter": "en una casita del bosque.", "textBefore": "Blancanieves vivía con los siete", "correctWord": "enanitos"}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('d18ff3b6-3d2e-4723-9889-82ab74943ad8', '2026-11-19 12:31:21.215293-03', '2026-11-19 12:31:21.215293-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La casita de los enanitos", "imageUrl": "assets/images/testigo/blancanieves_casita_interior.png", "questions": [{"prompt": "¿Cuántos platitos había sobre la mesa?", "options": ["Seis", "Ocho", "Siete", "Cinco"], "correctOption": "Siete"}, {"prompt": "¿De qué color eran las cortinas?", "options": ["Verdes", "Blancas", "Azules", "Rojas"], "correctOption": "Verdes"}, {"prompt": "¿Dónde estaba Blancanieves?", "options": ["Dormida en una de las camitas", "Cocinando", "Sentada a la mesa", "Mirando por la ventana"], "correctOption": "Dormida en una de las camitas"}], "imageDescription": "Interior de una casita: una mesa pequeña con siete platitos y siete vasitos; siete camitas pequeñas contra la pared, cada una con una colcha de color distinto; una ventana con cortinas verdes; Blancanieves dormida en una de las camas; una chimenea con una olla."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('3fc8e058-2f29-4396-b2dc-f9bbd57e1516', '2026-11-19 12:31:21.216294-03', '2026-11-19 12:31:21.216294-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La reina y la manzana", "imageUrl": "assets/images/testigo/blancanieves_anciana_ventana.png", "questions": [{"prompt": "¿Qué llevaba la anciana en la cesta?", "options": ["Manzanas rojas", "Flores", "Panes", "Peras amarillas"], "correctOption": "Manzanas rojas"}, {"prompt": "¿Qué animal estaba a los pies de la anciana?", "options": ["Un gato negro", "Una rata", "Un conejo", "Un perro"], "correctOption": "Un gato negro"}, {"prompt": "¿Dónde estaba Blancanieves?", "options": ["Subida a un árbol", "Dentro de la cesta", "Sentada en el suelo", "Asomada a una ventana"], "correctOption": "Asomada a una ventana"}], "imageDescription": "Fachada de una cabaña de enanitos con una ventana abierta; Blancanieves asomada con cara curiosa; una anciana encorvada con capa negra sostiene una cesta de mimbre llena de manzanas rojas y ofrece una; un gato negro a sus pies."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('6ff93464-8599-4268-9073-c3f638a3e578', '2026-11-19 12:31:21.218294-03', '2026-11-19 12:31:21.218294-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Cesta de pan", "imageUrl": "assets/images/cazador-intrusos/cesta-pan.png", "isIntruder": false}, {"id": "item-2", "name": "Platitos de madera", "imageUrl": "assets/images/cazador-intrusos/platitos.png", "isIntruder": false, "imageDescription": "Tres platitos pequeños de madera, apilados, fondo transparente."}, {"id": "item-3", "name": "Camita de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-4", "name": "Colcha roja", "imageUrl": "assets/images/cazador-intrusos/manta-roja.png", "isIntruder": false}, {"id": "item-5", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-6", "name": "Lámpara LED", "imageUrl": "assets/images/cazador-intrusos/lampara-led.png", "isIntruder": true}], "title": "La cocina de los enanitos", "bgImageUrl": "assets/images/cazador-intrusos/blancanieves-cocina-bg.jpg", "textDescription": "En la casita de los enanitos había camitas de madera, una cesta de pan, platitos de madera y una colcha roja sobre la cama.", "bgImageDescription": "Interior de una casita de bosque, con chimenea, ventana pequeña y piso de madera; espacio libre para 6 objetos."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('30f8d775-204c-43a2-ac4a-1d6c84c4d3b1', '2026-11-19 12:31:21.219318-03', '2026-11-19 12:31:21.219318-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-2", "name": "Manzana roja", "imageUrl": "assets/images/cazador-intrusos/manzana-roja.png", "isIntruder": false, "imageDescription": "Manzana roja brillante con una hoja verde, fondo transparente."}, {"id": "item-3", "name": "Flores del bosque", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-4", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-5", "name": "Mariposa", "imageUrl": "assets/images/cazador-intrusos/mariposa.png", "isIntruder": false}, {"id": "item-6", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}], "title": "El bosque encantado", "bgImageUrl": "assets/images/cazador-intrusos/blancanieves-bosque-bg.jpg", "textDescription": "En el bosque, Blancanieves recogía flores y miraba las mariposas, sin saber que una manzana roja la esperaba.", "bgImageDescription": "Claro del bosque soleado con árboles altos y pasto verde; espacio libre para 6 objetos."}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('29debb7e-fc4f-4441-8857-05b474c0481a', '2026-11-19 12:31:22.367399-03', '2026-11-19 12:31:22.367399-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Gracias por invitarme a esta linda fiesta!", "isCorrect": false}, {"text": "¡Vengo a bailar con todos ustedes!", "isCorrect": false}, {"text": "¡Les traigo un pastel de cumpleaños!", "isCorrect": false}, {"text": "¡Nadie me invitó, pero vengo a dejar mi regalo!", "isCorrect": true}], "emotionImage": "assets/images/emoticono/bella_hada_enojada.png", "imageDescription": "Un hada de túnica negra y varita, con gesto de furia, de pie en la puerta de un gran salón de banquete de un castillo, frente al rey y la reina."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('4550fdee-7f78-487a-8f98-ed4cf0a876a4', '2026-11-19 12:31:21.22059-03', '2026-11-19 12:31:21.22059-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/blancanieves-casita-busca.jpg", "storyTitle": "Blancanieves", "targetArea": {"top": 30, "left": 8, "width": 30, "height": 50}, "textSnippet": "Detrás de la puerta de madera de la casita, colgaba un pequeño pico de minero.", "imageDescription": "Entrada de una casita de enanitos con la puerta de madera abierta. En la parte izquierda, un pico de minero grande colgado de un clavo, de tono algo más claro que la puerta. Escena muy recargada: junto a la puerta hay muchas herramientas, faroles, gorros, botas, cestas, picos y palas de distintos tamaños.", "targetObjectName": "Pico de minero"}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('f2740199-7add-457c-b4bd-655e82de7b1b', '2026-11-19 12:31:21.221615-03', '2026-11-19 12:31:21.221615-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/blancanieves-castillo-busca.jpg", "storyTitle": "Blancanieves", "targetArea": {"top": 20, "left": 70, "width": 20, "height": 50}, "textSnippet": "En el salón del castillo, el espejo mágico de marco dorado brillaba tras una cortina de terciopelo.", "imageDescription": "Salón del castillo de la reina con cortinas de terciopelo. En la parte derecha, un espejo de marco dorado alto con un brillo verdoso, que destaca levemente de la pared.", "targetObjectName": "Espejo mágico"}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('3dd71e8a-5601-4b48-b4c0-4787e765dc9d', '2026-11-19 12:31:21.222623-03', '2026-11-19 12:31:21.222623-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La huida de Blancanieves", "panels": [{"id": 1, "image": "assets/images/comics/blancanieves1.png", "imageDescription": "La reina frunce el ceño frente al espejo mágico."}, {"id": 2, "image": "assets/images/comics/blancanieves2.png", "imageDescription": "Un cazador lleva a Blancanieves por el bosque oscuro."}, {"id": 3, "image": "assets/images/comics/blancanieves3.png", "imageDescription": "El cazador baja su arma y le indica a Blancanieves que huya."}, {"id": 4, "image": "assets/images/comics/blancanieves4.png", "imageDescription": "Blancanieves corre entre árboles hasta llegar a una casita pequeña con siete camitas."}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('644505ba-b3bb-4c07-9a87-d8528a6ffda5', '2026-11-19 12:31:21.223597-03', '2026-11-19 12:31:21.223597-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La manzana", "panels": [{"id": 1, "image": "assets/images/comics/blancanieves5.png", "imageDescription": "La reina se disfraza de anciana en una torre llena de frascos de pociones."}, {"id": 2, "image": "assets/images/comics/blancanieves6.png", "imageDescription": "La anciana ofrece una manzana a Blancanieves en la ventana de la casita."}, {"id": 3, "image": "assets/images/comics/blancanieves7.png", "imageDescription": "Blancanieves cae dormida con la manzana a su lado y los enanitos llegan corriendo."}, {"id": 4, "image": "assets/images/comics/blancanieves8.png", "imageDescription": "Los enanitos lloran junto al ataúd de cristal en el bosque y un príncipe se acerca."}]}', 'bd812ac7-613d-4787-96cf-6b80223a352a', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('5186dcba-0ae0-428a-9b27-e229669db32a', '2026-11-19 12:31:21.226598-03', '2026-11-19 12:31:21.226598-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Cenicienta dormía junto al fogón.", "isTrue": true}, {"text": "Sus hermanastras la trataban con cariño.", "isTrue": false}, {"text": "Cenicienta tenía dos hermanastras.", "isTrue": true}], "passage_text": "Cenicienta vivía con su madrastra y sus dos hermanastras, que la obligaban a hacer todo el trabajo de la casa. Todas las noches dormía junto al fogón, cubierta de cenizas.", "time_per_statement": 7}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('efc12160-be4f-4a3a-8844-a42ffc7ae018', '2026-11-19 12:31:21.227598-03', '2026-11-19 12:31:21.227598-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Cenicienta plantó una ramita de avellano.", "isTrue": true}, {"text": "Un pajarito blanco le concedía sus deseos.", "isTrue": true}, {"text": "El árbol creció en el jardín del príncipe.", "isTrue": false}], "passage_text": "Cenicienta plantó una ramita de avellano sobre la tumba de su madre y la regó con sus lágrimas. Creció un árbol y un pajarito blanco le concedía lo que ella deseaba.", "time_per_statement": 7}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c3518307-1e99-4d05-8b29-d5803c4c8b4d', '2026-11-19 12:31:21.229624-03', '2026-11-19 12:31:21.229624-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Mañana iré de paseo en carruaje!", "isCorrect": false}, {"text": "Nunca terminaré de separar las lentejas de las cenizas...", "isCorrect": true}, {"text": "¡Qué rica es la cena de esta noche!", "isCorrect": false}, {"text": "¡Estoy muy feliz de limpiar toda la casa!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/cenicienta_fogon.png", "imageDescription": "Cenicienta, joven con vestido gris sucio y delantal, sentada junto al fogón con cenizas, mirando con tristeza un plato de lentejas mezcladas con cenizas."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('4a3184d1-61d5-48d6-bf19-57e5c2277b5b', '2026-11-19 12:31:21.229624-03', '2026-11-19 12:31:21.229624-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Quiero ir a pescar al río!", "isCorrect": false}, {"text": "¡No me interesa ningún zapato!", "isCorrect": false}, {"text": "¡Mi zapato favorito es el de cuero!", "isCorrect": false}, {"text": "¡Esta zapatilla dorada solo le calzará a mi verdadera novia!", "isCorrect": true}], "emotionImage": "assets/images/emoticono/cenicienta_principe_zapatilla.png", "imageDescription": "El príncipe, con ropa elegante, sosteniendo una zapatilla dorada en las manos frente a una joven sentada en un banquito; detrás, las hermanastras observan con ansiedad."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('a5a11e0b-d6a3-4f2f-987f-51b5c88bb1fd', '2026-11-19 12:31:21.231597-03', '2026-11-19 12:31:21.231597-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["La reina", "Cenicienta", "La madrastra", "Una hermanastra", "Blancanieves"], "imageSrc": "assets/images/pixelado/cenicienta_personaje.png", "correctCharacter": "Cenicienta", "imageDescription": "Cenicienta, joven de cabello rubio recogido y vestido gris con delantal, con ceniza en las mejillas, sosteniendo una escoba."}], "total_time": 7}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('1e069dd5-65b0-42e8-b8bf-1cc35f993091', '2026-11-19 12:31:21.232615-03', '2026-11-19 12:31:21.232615-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["La zapatilla dorada", "Un zapato rojo", "Un zueco de madera", "Una sandalia de playa", "Una bota de cuero"], "imageSrc": "assets/images/pixelado/cenicienta_zapatilla.png", "correctCharacter": "La zapatilla dorada", "imageDescription": "Una zapatilla dorada brillante de tacón bajo, apoyada sobre un cojín rojo."}], "total_time": 7}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('4e4fdcde-189d-4ffb-afcc-abcec82a1de2', '2026-11-19 12:31:22.368369-03', '2026-11-19 12:31:22.368369-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Qué rico huele el pastel del desayuno!", "isCorrect": false}, {"text": "¿Qué es esa cosa que da vueltas tan rápido?", "isCorrect": true}, {"text": "¡Tengo mucho frío, cerremos las ventanas!", "isCorrect": false}, {"text": "¡Hoy iré a cabalgar por el bosque!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/bella_princesa_huso.png", "imageDescription": "La princesa de quince años, con vestido rosa, en lo alto de una torre, mirando con curiosidad a una anciana que hila con un huso."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('f152cb25-9d33-4faa-b004-e03d0581d5d8', '2026-11-19 12:31:21.233623-03', '2026-11-19 12:31:21.233623-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 781, "altText": "Cenicienta bajando la escalera", "imageSrc": "assets/images/contra/cenicienta_baja_escalera.png", "isContradiction": false, "imageDescription": "Cenicienta con vestido de oro y plata bajando una gran escalera de mármol de un palacio."}, {"id": 782, "altText": "Zapatilla dorada en el escalón", "imageSrc": "assets/images/contra/cenicienta_zapatilla_escalon.png", "isContradiction": false, "imageDescription": "Una zapatilla dorada sobre un escalón de mármol blanco, de noche."}, {"id": 783, "altText": "Cenicienta disfrazada de pirata", "imageSrc": "assets/images/contra/cenicienta_pirata.png", "isContradiction": true, "imageDescription": "Cenicienta con sombrero de pirata, parche en el ojo y un loro en el hombro, en un salón de baile."}, {"id": 784, "altText": "Baile con el príncipe", "imageSrc": "assets/images/contra/cenicienta_baila_principe.png", "isContradiction": false, "imageDescription": "Cenicienta con vestido de oro y plata bailando con el príncipe en un gran salón iluminado."}], "explanation": "La imagen contradictoria muestra a Cenicienta en el baile con un disfraz de pirata con parche.", "premiseText": "Cenicienta fue al baile con un vestido de oro y plata y zapatillas doradas."}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('3a240c88-8967-45c9-817e-44769f09bb34', '2026-11-19 12:31:21.234597-03', '2026-11-19 12:31:21.234597-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 791, "altText": "Árbol en un volcán", "imageSrc": "assets/images/contra/cenicienta_arbol_volcan.png", "isContradiction": true, "imageDescription": "Un avellano creciendo en la cima de un volcán en erupción, con lava naranja alrededor."}, {"id": 792, "altText": "Cenicienta pidiendo un deseo", "imageSrc": "assets/images/contra/cenicienta_deseo_arbol.png", "isContradiction": false, "imageDescription": "Cenicienta de pie bajo el avellano con las manos juntas, mirando hacia el pajarito blanco."}, {"id": 793, "altText": "Árbol con pajarito blanco", "imageSrc": "assets/images/contra/cenicienta_arbol_pajaro.png", "isContradiction": false, "imageDescription": "Un avellano grande y frondoso con un pajarito blanco posado en una rama sobre una tumba."}, {"id": 794, "altText": "Ramita regada con lágrimas", "imageSrc": "assets/images/contra/cenicienta_tumba_ramita.png", "isContradiction": false, "imageDescription": "Una pequeña tumba con una ramita recién plantada, y Cenicienta llorando a su lado."}], "explanation": "La imagen contradictoria muestra el árbol creciendo en la cima de un volcán en erupción.", "premiseText": "El árbol de avellano de Cenicienta creció sobre la tumba de su madre."}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('d90e7438-77f9-499c-80af-0ce6a2a31b30', '2026-11-19 12:31:21.236624-03', '2026-11-19 12:31:21.236624-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El baile del príncipe", "fragments": [{"id": 1, "text": "El rey anuncia una fiesta de tres días para que su hijo elija novia."}, {"id": 2, "text": "La madrastra pone a prueba a Cenicienta con lentejas entre las cenizas, y las palomas y tórtolas la ayudan."}, {"id": 3, "text": "Cenicienta pide un deseo al avellano y recibe un vestido de oro y plata."}, {"id": 4, "text": "En el baile, el príncipe no quiere bailar con nadie más que con ella."}, {"id": 5, "text": "Al caer la noche, Cenicienta escapa corriendo y se esconde en el palomar."}]}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('d9917d85-42cb-4cab-8e6a-6f6da332bbf0', '2026-11-19 12:31:21.237179-03', '2026-11-19 12:31:21.237179-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La zapatilla dorada", "fragments": [{"id": 1, "text": "En la tercera noche, Cenicienta huye tan rápido que pierde una zapatilla dorada en la escalera."}, {"id": 2, "text": "El príncipe recoge la zapatilla y declara que se casará con quien le calce."}, {"id": 3, "text": "Las hermanastras intentan probarse la zapatilla, pero no les cabe."}, {"id": 4, "text": "Cenicienta se prueba la zapatilla y le queda perfectamente."}, {"id": 5, "text": "El príncipe la reconoce y se casan."}]}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('a4426b91-4152-440e-90dd-da8c9fbeabaf', '2026-11-19 12:31:21.237784-03', '2026-11-19 12:31:21.237784-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["roble", "manzano", "pino", "avellano"], "timeLeft": 7.0, "textAfter": "y la regó con sus lágrimas.", "textBefore": "Sobre la tumba de su madre, Cenicienta plantó una rama de", "correctWord": "avellano"}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('61c4fd65-08e1-4eed-8670-3473fd30d3c6', '2026-11-19 12:31:21.238822-03', '2026-11-19 12:31:21.238822-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["dorada", "roja", "azul", "negra"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "El príncipe se casaría con la joven a quien le calzara la zapatilla", "correctWord": "dorada"}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('04935687-c78d-4cba-a403-55d1678acc6e', '2026-11-19 12:31:21.240792-03', '2026-11-19 12:31:21.240792-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El fogón de Cenicienta", "imageUrl": "assets/images/testigo/cenicienta_cocina_fogon.png", "questions": [{"prompt": "¿Qué había en el cuenco de madera?", "options": ["Nueces", "Harina", "Arroz", "Lentejas"], "correctOption": "Lentejas"}, {"prompt": "¿Cuántas aves había sobre la repisa?", "options": ["Cuatro", "Tres", "Seis", "Dos"], "correctOption": "Tres"}, {"prompt": "¿De qué color era el vestido de Cenicienta?", "options": ["Gris", "Rosado", "Rojo", "Azul"], "correctOption": "Gris"}], "imageDescription": "Cocina pobre: un fogón con brasas y ceniza; Cenicienta con vestido gris y delantal sentada en el suelo; un cuenco de madera con lentejas; una paloma blanca y dos tórtolas posadas sobre la repisa; un caldero negro colgando sobre el fuego."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('86884942-2027-4eb9-9a79-d025c8904d53', '2026-11-19 12:31:21.240792-03', '2026-11-19 12:31:21.240792-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La escalera del palacio", "imageUrl": "assets/images/testigo/cenicienta_escalera_noche.png", "questions": [{"prompt": "¿De qué color era la alfombra de la escalera?", "options": ["Azul", "Roja", "Verde", "Dorada"], "correctOption": "Roja"}, {"prompt": "¿Qué objeto había en los escalones?", "options": ["Una zapatilla dorada", "Un guante", "Un abanico", "Una corona"], "correctOption": "Una zapatilla dorada"}, {"prompt": "¿Qué sostenía el príncipe?", "options": ["Un farol", "Una espada", "Un libro", "Un ramo de flores"], "correctOption": "Un farol"}], "imageDescription": "Gran escalera de mármol blanco con alfombra roja; en los escalones una zapatilla dorada; al pie de la escalera, el príncipe con capa azul sosteniendo un farol; un guardia con casco plateado; luna llena en el cielo."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('749a1ad6-2917-48f2-98ee-7e1dee8fa27d', '2026-11-19 12:31:22.37037-03', '2026-11-19 12:31:22.37037-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El huso", "Una aguja de coser", "Una varita mágica", "Una cuchara", "Un peine de plata"], "imageSrc": "assets/images/pixelado/bella_huso.png", "correctCharacter": "El huso", "imageDescription": "Un huso de madera con un poco de hilo blanco enrollado, apoyado sobre una rueca antigua, en una habitación de piedra."}], "total_time": 7}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('2afaccab-a62d-44d4-9a64-7f222deac09b', '2026-11-19 12:31:21.242791-03', '2026-11-19 12:31:21.242791-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-2", "name": "Pajarito blanco", "imageUrl": "assets/images/cazador-intrusos/pajarito-blanco.png", "isIntruder": false, "imageDescription": "Pajarito blanco de pico pequeño y ojos negros, posado, fondo transparente."}, {"id": "item-3", "name": "Radio a pilas", "imageUrl": "assets/images/cazador-intrusos/radio.png", "isIntruder": true}, {"id": "item-4", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}, {"id": "item-5", "name": "Flores", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-6", "name": "Árbol de avellano", "imageUrl": "assets/images/cazador-intrusos/avellano.png", "isIntruder": false, "imageDescription": "Árbol de avellano joven con hojas verdes y avellanas, fondo transparente."}], "title": "El árbol de avellano", "bgImageUrl": "assets/images/cazador-intrusos/cenicienta-avellano-bg.jpg", "textDescription": "Junto a la tumba de su madre creció el avellano, rodeado de flores y visitado por un pajarito blanco que cumplía los deseos de Cenicienta.", "bgImageDescription": "Jardín tranquilo con una pequeña tumba de piedra y pasto verde, cielo claro; espacio libre para 6 objetos."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('1ae2e8a8-36dc-4218-8a98-a430983ac3f7', '2026-11-19 12:31:21.242791-03', '2026-11-19 12:31:21.242791-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-2", "name": "Zapatilla dorada", "imageUrl": "assets/images/cazador-intrusos/zapatilla-dorada.png", "isIntruder": false, "imageDescription": "Zapatilla dorada brillante de tacón bajo, fondo transparente."}, {"id": "item-3", "name": "Calculadora solar", "imageUrl": "assets/images/cazador-intrusos/calculadora.png", "isIntruder": true}, {"id": "item-4", "name": "Jarra de plata", "imageUrl": "assets/images/cazador-intrusos/jarra-plata.png", "isIntruder": false}, {"id": "item-5", "name": "Copa de cristal", "imageUrl": "assets/images/cazador-intrusos/copa.png", "isIntruder": false}, {"id": "item-6", "name": "Vestido de oro y plata", "imageUrl": "assets/images/cazador-intrusos/vestido-oro-plata.png", "isIntruder": false, "imageDescription": "Vestido de gala dorado con detalles plateados, fondo transparente."}], "title": "El baile en el palacio", "bgImageUrl": "assets/images/cazador-intrusos/cenicienta-salon-bg.jpg", "textDescription": "En el gran salón del palacio había una zapatilla dorada, un vestido de oro y plata, copas de cristal y jarras de plata.", "bgImageDescription": "Gran salón de baile de un palacio con suelo de mármol y columnas, iluminado por candelabros; espacio libre para 6 objetos."}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('771de8e9-083f-497b-b29c-48ac35f197ca', '2026-11-19 12:31:21.244792-03', '2026-11-19 12:31:21.244792-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/cenicienta-avellano-busca.jpg", "storyTitle": "La Cenicienta", "targetArea": {"top": 15, "left": 50, "width": 40, "height": 37.5}, "textSnippet": "Entre las ramas del avellano, un pajarito blanco observaba a Cenicienta en silencio.", "imageDescription": "Gran avellano con muchas hojas en un jardín. En la parte superior derecha, un pajarito blanco grande posado entre las ramas, más claro que el follaje y con contorno más marcado. Escena muy recargada: el avellano está lleno de hojas, avellanas, otros pajaritos de colores, nidos, lazos y flores.", "targetObjectName": "Pajarito blanco"}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('9e4512a1-3e1c-4c7d-84fe-7fab3a083655', '2026-11-19 12:31:21.245792-03', '2026-11-19 12:31:21.245792-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/cenicienta-fogon-busca.jpg", "storyTitle": "La Cenicienta", "targetArea": {"top": 65, "left": 15, "width": 50, "height": 20}, "textSnippet": "En un rincón del fogón, escondido entre las cenizas, un cuenco de madera guardaba las lentejas que Cenicienta debía limpiar.", "imageDescription": "Cocina pobre con fogón y cenizas. En la parte inferior izquierda, un cuenco de madera con lentejas, medio cubierto de cenizas, de tono algo más oscuro y definido que el suelo.", "targetObjectName": "Cuenco de lentejas"}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('ff0963fb-2322-42bd-8522-2771f01157c8', '2026-11-19 12:31:21.247792-03', '2026-11-19 12:31:21.247792-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Un deseo bajo el avellano", "panels": [{"id": 1, "image": "assets/images/comics/cenicienta1.png", "imageDescription": "Cenicienta llora junto a la tumba de su madre y planta una ramita de avellano."}, {"id": 2, "image": "assets/images/comics/cenicienta2.png", "imageDescription": "Con el tiempo, el avellano crece y un pajarito blanco se posa en sus ramas."}, {"id": 3, "image": "assets/images/comics/cenicienta3.png", "imageDescription": "Cenicienta pide un deseo y el pajarito le deja un vestido de oro y plata."}, {"id": 4, "image": "assets/images/comics/cenicienta4.png", "imageDescription": "Cenicienta, con el vestido, camina hacia el palacio iluminado por la luna."}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('23eee7e2-0f12-463a-9871-084da7f045fe', '2026-11-19 12:31:21.248792-03', '2026-11-19 12:31:21.248792-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La zapatilla", "panels": [{"id": 1, "image": "assets/images/comics/cenicienta5.png", "imageDescription": "Cenicienta corre por la escalera del palacio dejando atrás una zapatilla dorada."}, {"id": 2, "image": "assets/images/comics/cenicienta6.png", "imageDescription": "El príncipe recoge la zapatilla de la escalera."}, {"id": 3, "image": "assets/images/comics/cenicienta7.png", "imageDescription": "Las hermanastras intentan calzarse la zapatilla sin éxito."}, {"id": 4, "image": "assets/images/comics/cenicienta8.png", "imageDescription": "La zapatilla calza perfectamente en el pie de Cenicienta y el príncipe sonríe."}]}', '63dd2f85-29a0-4c90-a657-37c7e28fec24', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('7e38a2b4-0bc5-493f-b681-3273fbae2fcc', '2026-11-19 12:31:22.36137-03', '2026-11-19 12:31:22.36137-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El rey invitó a doce hadas.", "isTrue": true}, {"text": "El rey invitó a las trece hadas.", "isTrue": false}, {"text": "Los platos de la fiesta eran de oro.", "isTrue": true}], "passage_text": "Cuando nació la princesa, el rey organizó una gran fiesta. Invitó a doce de las trece hadas del reino, porque solo tenía doce platos de oro.", "time_per_statement": 7}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('3e85fb09-a288-4770-806f-0d8dd5ad7a71', '2026-11-19 12:31:22.365467-03', '2026-11-19 12:31:22.365467-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La princesa se pincharía con un huso.", "isTrue": true}, {"text": "La maldición la lanzó un hada que sí fue invitada.", "isTrue": false}, {"text": "La princesa dormiría cien años.", "isTrue": true}], "passage_text": "El hada no invitada lanzó una maldición: a los quince años la princesa se pincharía con un huso. Otra hada suavizó el hechizo: la princesa dormiría cien años.", "time_per_statement": 7}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('6ea214ff-d905-464e-a2e3-43abce8216cc', '2026-11-19 12:31:22.373367-03', '2026-11-19 12:31:22.373367-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 801, "altText": "Torre alta de piedra", "imageSrc": "assets/images/contra/bella_torre_alta.png", "isContradiction": false, "imageDescription": "Una torre alta de piedra con una pequeña puerta y una escalera de caracol visible por la ventana."}, {"id": 802, "altText": "Princesa y un cactus", "imageSrc": "assets/images/contra/bella_princesa_cactus.png", "isContradiction": true, "imageDescription": "La princesa pinchándose el dedo con un cactus grande en medio de un desierto soleado."}, {"id": 803, "altText": "Anciana hilando", "imageSrc": "assets/images/contra/bella_anciana_huso.png", "isContradiction": false, "imageDescription": "Una anciana con pañuelo azul hilando con un huso junto a una rueca, en un cuarto de la torre."}, {"id": 804, "altText": "Princesa sorprendida", "imageSrc": "assets/images/contra/bella_princesa_dedo.png", "isContradiction": false, "imageDescription": "La princesa mirando su dedo con cara de sorpresa dentro del cuarto de la torre."}], "explanation": "La imagen contradictoria muestra a la princesa pinchándose el dedo con un cactus en medio del desierto.", "premiseText": "La princesa se pinchó el dedo con el huso de una anciana, en lo alto de una torre."}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('9456795c-20d7-4fc5-ba62-db1e62e94085', '2026-11-19 12:31:22.374369-03', '2026-11-19 12:31:22.374369-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 811, "altText": "Castillo medio cubierto", "imageSrc": "assets/images/contra/bella_castillo_cubierto.png", "isContradiction": false, "imageDescription": "Un castillo con las torres asomando sobre una maraña espesa de ramas con espinas."}, {"id": 812, "altText": "Rosas con espinas", "imageSrc": "assets/images/contra/bella_rosas_blancas.png", "isContradiction": false, "imageDescription": "Primer plano de rosas blancas con tallos de largas espinas."}, {"id": 813, "altText": "Seto de espinas y rosas", "imageSrc": "assets/images/contra/bella_seto_rosas.png", "isContradiction": false, "imageDescription": "Un gigantesco seto de ramas con espinas y rosas blancas que rodea un castillo."}, {"id": 814, "altText": "Castillo en isla tropical", "imageSrc": "assets/images/contra/bella_castillo_isla.png", "isContradiction": true, "imageDescription": "Un castillo rodeado de arena dorada y palmeras en una isla tropical con mar turquesa."}], "explanation": "La imagen contradictoria muestra el castillo rodeado de arena y palmeras en una isla tropical, sin espinas.", "premiseText": "Cuando el castillo se durmió, creció a su alrededor un enorme seto de espinas y rosas."}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('90fd8464-6a15-42d9-80e0-9559b8758d3e', '2026-11-19 12:31:22.376333-03', '2026-11-19 12:31:22.376333-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La maldición", "fragments": [{"id": 1, "text": "Nace la princesa y el rey organiza una gran fiesta con doce hadas."}, {"id": 2, "text": "Un hada no invitada llega enojada y lanza una maldición."}, {"id": 3, "text": "Otra hada suaviza el hechizo: la princesa dormirá cien años en lugar de morir."}, {"id": 4, "text": "El rey ordena quemar todos los husos del reino."}, {"id": 5, "text": "A los quince años, la princesa encuentra en una torre a una anciana que hila."}]}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('03833b21-88e7-4ad7-842f-0cc492243d16', '2026-11-19 12:31:22.377344-03', '2026-11-19 12:31:22.377344-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El sueño de cien años", "fragments": [{"id": 1, "text": "La princesa se pincha el dedo con el huso y cae dormida."}, {"id": 2, "text": "Todo el castillo se queda dormido junto a ella."}, {"id": 3, "text": "Alrededor del castillo crece un enorme seto de espinas."}, {"id": 4, "text": "Después de cien años, un príncipe llega y las espinas se convierten en flores."}, {"id": 5, "text": "El príncipe besa a la princesa y todos despiertan."}]}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('54f291a8-f6fe-45b5-8b1a-f24d9ca1604d', '2026-11-19 12:31:22.379347-03', '2026-11-19 12:31:22.379347-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["huso", "clavo", "espejo", "cuchillo"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "A los quince años, la princesa se pinchó el dedo con un", "correctWord": "huso"}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('42f2ecff-ba36-4ee9-8814-160468cbf57a', '2026-11-19 12:31:22.380343-03', '2026-11-19 12:31:22.380343-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["meses", "días", "noches", "años"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "La princesa y todo el castillo durmieron durante cien", "correctWord": "años"}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('864f44bd-460c-4f9a-86b9-99833aa52492', '2026-11-19 12:31:22.382376-03', '2026-11-19 12:31:22.382376-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La torre del huso", "imageUrl": "assets/images/testigo/bella_cuarto_torre.png", "questions": [{"prompt": "¿De qué color era el pañuelo de la anciana?", "options": ["Azul", "Negro", "Verde", "Rojo"], "correctOption": "Azul"}, {"prompt": "¿Qué ave estaba en la ventana?", "options": ["Un cuervo", "Una paloma blanca", "Un búho", "Un loro"], "correctOption": "Una paloma blanca"}, {"prompt": "¿Qué había en la cerradura de la puerta?", "options": ["Una llave oxidada", "Una campanilla", "Una cinta roja", "Un candado dorado"], "correctOption": "Una llave oxidada"}], "imageDescription": "Cuarto circular al final de una escalera de caracol en una torre; una anciana con pañuelo azul sentada junto a una rueca con un huso; en la pequeña ventana, una paloma blanca; en la puerta, una llave oxidada en la cerradura; telarañas en las esquinas."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('eb4a5652-c9dc-4ea8-a4ed-3311cab0ba55', '2026-11-19 12:31:22.383343-03', '2026-11-19 12:31:22.383343-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El castillo dormido", "imageUrl": "assets/images/testigo/bella_salon_dormido.png", "questions": [{"prompt": "¿Dónde dormía el rey?", "options": ["En una silla del jardín", "En su trono", "En la cama", "En el suelo"], "correctOption": "En su trono"}, {"prompt": "¿Qué sostenía la cocinera?", "options": ["Un plato", "Un cuchillo", "Una cuchara de madera", "Una escoba"], "correctOption": "Una cuchara de madera"}, {"prompt": "¿Qué animal dormía bajo la mesa?", "options": ["Un loro", "Un gato", "Un conejo", "Un perro"], "correctOption": "Un perro"}], "imageDescription": "Gran salón con todos dormidos: un rey en su trono con la corona torcida; una cocinera con una cuchara de madera, dormida junto a una olla; un perro dormido bajo la mesa; cortinas amarillas en las ventanas."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('b370d862-301e-4412-83d0-e73e43d4755a', '2026-11-19 12:31:22.397981-03', '2026-11-19 12:31:22.397981-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Qué traje tan hermoso lleva el emperador!", "isCorrect": false}, {"text": "¡Viva el emperador, qué corona tan grande!", "isCorrect": false}, {"text": "¡Mamá, quiero un helado!", "isCorrect": false}, {"text": "¡Pero si el emperador no lleva nada puesto!", "isCorrect": true}], "emotionImage": "assets/images/emoticono/traje_nino_grita.png", "imageDescription": "Un niño pequeño entre la multitud, señalando con el dedo a un emperador que desfila en ropa interior blanca bajo un palio, mientras la gente mira."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('218d0290-8334-433c-ba8d-78c537090f65', '2026-11-19 12:31:22.384344-03', '2026-11-19 12:31:22.384344-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Lámpara LED", "imageUrl": "assets/images/cazador-intrusos/lampara-led.png", "isIntruder": true}, {"id": "item-2", "name": "Huso de hilar", "imageUrl": "assets/images/cazador-intrusos/huso.png", "isIntruder": false, "imageDescription": "Huso de madera con hilo blanco enrollado, fondo transparente."}, {"id": "item-3", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-4", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-5", "name": "Llave oxidada", "imageUrl": "assets/images/cazador-intrusos/llave-oxidada.png", "isIntruder": false, "imageDescription": "Llave antigua de hierro oxidada, fondo transparente."}, {"id": "item-6", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}], "title": "La torre de la princesa", "bgImageUrl": "assets/images/cazador-intrusos/bella-torre-bg.jpg", "textDescription": "En lo alto de la torre había un huso de hilar, una cama de madera y una vieja llave oxidada.", "bgImageDescription": "Interior de una torre de piedra con una pequeña ventana, suelo de madera y telarañas suaves; espacio libre para 6 objetos."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('c8c179e8-e30e-4577-82cf-ed162919cbbe', '2026-11-19 12:31:22.385371-03', '2026-11-19 12:31:22.385371-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-2", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}, {"id": "item-3", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}, {"id": "item-4", "name": "Corona del rey", "imageUrl": "assets/images/cazador-intrusos/corona-rey.png", "isIntruder": false}, {"id": "item-5", "name": "Rosal con espinas", "imageUrl": "assets/images/cazador-intrusos/rosal-espinas.png", "isIntruder": false, "imageDescription": "Rosal con ramas de espinas largas y rosas blancas, fondo transparente."}, {"id": "item-6", "name": "Rosas", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}], "title": "El jardín de espinas", "bgImageUrl": "assets/images/cazador-intrusos/bella-jardin-bg.jpg", "textDescription": "Alrededor del castillo dormido crecía un rosal con espinas, lleno de rosas, y en la entrada brillaba la corona del rey.", "bgImageDescription": "Jardín frente a un castillo dormido, con pasto y neblina suave al atardecer; espacio libre para 6 objetos."}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('153d9ab6-1e5d-4dc7-bd44-005beb7abea1', '2026-11-19 12:31:22.387341-03', '2026-11-19 12:31:22.387341-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/bella-torre-busca.jpg", "storyTitle": "La Bella Durmiente", "targetArea": {"top": 30, "left": 15, "width": 25, "height": 60}, "textSnippet": "En lo alto de la torre, junto a la rueca de la anciana, un huso de madera esperaba a la princesa.", "imageDescription": "Cuarto de una torre con una anciana sentada junto a una rueca. En la parte izquierda, un huso de madera alto con hilo blanco, de color algo más claro que la rueca y con contorno marcado. Escena muy recargada: el cuarto está lleno de ruecas, telarañas, canastas con hilos, ovillos, baúles y cortinas viejas.", "targetObjectName": "Huso"}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('60679a30-915b-4605-b2a8-5792ce3e4e0e', '2026-11-19 12:31:22.388438-03', '2026-11-19 12:31:22.388438-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/bella-seto-busca.jpg", "storyTitle": "La Bella Durmiente", "targetArea": {"top": 28, "left": 55, "width": 32, "height": 31.25}, "textSnippet": "Entre las espinas del seto, asomaba una rosa blanca que parecía guardar el secreto del castillo.", "imageDescription": "Seto de espinas frente a un castillo dormido. En la parte central-derecha, una rosa blanca entre las ramas, que destaca levemente por su blancura frente a las espinas.", "targetObjectName": "Rosa blanca"}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('f66db276-e333-475e-abe4-e60035d050d6', '2026-11-19 12:31:22.389343-03', '2026-11-19 12:31:22.389343-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "El hechizo", "panels": [{"id": 1, "image": "assets/images/comics/bella1.png", "imageDescription": "El rey y la reina celebran el nacimiento de la princesa en un gran salón con doce hadas."}, {"id": 2, "image": "assets/images/comics/bella2.png", "imageDescription": "Un hada vestida de negro entra al salón con gesto furioso."}, {"id": 3, "image": "assets/images/comics/bella3.png", "imageDescription": "El hada lanza la maldición con su varita, mientras todos miran asustados."}, {"id": 4, "image": "assets/images/comics/bella4.png", "imageDescription": "Otra hada se acerca a la cuna y suaviza el hechizo."}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('c042594e-80f7-443e-9436-1620099a4acb', '2026-11-19 12:31:22.390341-03', '2026-11-19 12:31:22.390341-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El sueño", "panels": [{"id": 1, "image": "assets/images/comics/bella5.png", "imageDescription": "La princesa sube la escalera de la torre y encuentra a la anciana hilando."}, {"id": 2, "image": "assets/images/comics/bella6.png", "imageDescription": "La princesa toca el huso y cae dormida sobre una cama."}, {"id": 3, "image": "assets/images/comics/bella7.png", "imageDescription": "El castillo duerme y un seto de espinas lo cubre."}, {"id": 4, "image": "assets/images/comics/bella8.png", "imageDescription": "Cien años después, un príncipe llega ante las rosas floridas del castillo."}]}', '3b36a387-ef6c-4c89-8d51-747e8e3397f6', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('d342bf53-d18e-4c7c-94b6-c88fa4dc0ed2', '2026-11-19 12:31:22.393972-03', '2026-11-19 12:31:22.393972-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El emperador gastaba mucho dinero en ropa.", "isTrue": true}, {"text": "Los dos hombres dijeron ser médicos.", "isTrue": false}, {"text": "Los estafadores dijeron ser tejedores.", "isTrue": true}], "passage_text": "Había un emperador al que le gustaba tanto la ropa nueva que gastaba todo su dinero en vestirse. Un día llegaron dos estafadores que dijeron ser tejedores.", "time_per_statement": 7}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c9053368-cf4a-468c-8c40-241a00cb0545', '2026-11-19 12:31:22.39498-03', '2026-11-19 12:31:22.39498-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La tela era invisible para los tontos.", "isTrue": true}, {"text": "Pidieron seda e hilos de oro.", "isTrue": true}, {"text": "Usaron todo el oro para hacer el traje.", "isTrue": false}], "passage_text": "Los estafadores aseguraron que su tela era invisible para los tontos. Pidieron seda e hilos de oro, pero se los guardaron en sus bolsos.", "time_per_statement": 7}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('7da9f293-9b7b-4ba7-9e59-2346c8b3812d', '2026-11-19 12:31:22.39701-03', '2026-11-19 12:31:22.39701-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Estos telares están llenos de lana azul!", "isCorrect": false}, {"text": "¡Qué lindo es mi jardín!", "isCorrect": false}, {"text": "¡Qué hambre tengo, vamos a comer!", "isCorrect": false}, {"text": "¡No veo nada! ¿Seré yo un tonto?", "isCorrect": true}], "emotionImage": "assets/images/emoticono/traje_emperador_telares.png", "imageDescription": "Un emperador con corona, mirando asombrado dos telares vacíos con la boca abierta, junto a dos tejedores que fingen tejer."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('f7c67af3-7db9-4a2a-bbac-46b1e1db643c', '2026-11-19 12:31:22.401981-03', '2026-11-19 12:31:22.401981-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 821, "altText": "Rollos de seda", "imageSrc": "assets/images/contra/traje_rollos_seda.png", "isContradiction": false, "imageDescription": "Tres rollos de tela de seda brillante de colores sobre una mesa."}, {"id": 822, "altText": "Estafadores guardando el oro", "imageSrc": "assets/images/contra/traje_estafadores_bolsa.png", "isContradiction": false, "imageDescription": "Dos hombres guardando a escondidas hilo de oro en una bolsa, mirando de reojo."}, {"id": 823, "altText": "Carrete de hilo de oro", "imageSrc": "assets/images/contra/traje_carrete_oro.png", "isContradiction": false, "imageDescription": "Un carrete de hilo dorado brillante sobre una mesa de madera."}, {"id": 824, "altText": "Estafadores con pintura", "imageSrc": "assets/images/contra/traje_estafadores_pintura.png", "isContradiction": true, "imageDescription": "Dos hombres recibiendo cubos de pintura y brochas de un sirviente."}], "explanation": "La imagen contradictoria muestra a los estafadores recibiendo cubos de pintura y brochas.", "premiseText": "Los estafadores pidieron seda e hilos de oro para tejer la tela invisible."}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('b3eabadc-ded8-457f-9ccb-f708b66f216e', '2026-11-19 12:31:22.402981-03', '2026-11-19 12:31:22.402981-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 831, "altText": "Palio azul y dorado", "imageSrc": "assets/images/contra/traje_palio.png", "isContradiction": false, "imageDescription": "Un palio azul con bordes dorados sostenido por cuatro hombres en una calle."}, {"id": 832, "altText": "Ayudantes agachados", "imageSrc": "assets/images/contra/traje_ayudantes.png", "isContradiction": false, "imageDescription": "Dos ayudantes agachados con las manos levantadas, fingiendo sostener una cola de tela."}, {"id": 833, "altText": "Multitud asombrada", "imageSrc": "assets/images/contra/traje_multitud.png", "isContradiction": false, "imageDescription": "Una multitud en una calle con banderas rojas, mirando con asombro hacia el desfile."}, {"id": 834, "altText": "Emperador en monopatín", "imageSrc": "assets/images/contra/traje_emperador_monopatin.png", "isContradiction": true, "imageDescription": "Un emperador con corona y capa, solo, montado en un monopatín en una calle vacía."}], "explanation": "La imagen contradictoria muestra al emperador desfilando solo, montado en un monopatín.", "premiseText": "El emperador desfiló por la ciudad bajo un palio, acompañado de sus ayudantes."}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('75840ede-1837-4cad-b2de-e7e86b1d5e5f', '2026-11-19 12:31:22.404011-03', '2026-11-19 12:31:22.404011-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "Los falsos tejedores", "fragments": [{"id": 1, "text": "El emperador, a quien le encantan los trajes, contrata a dos supuestos tejedores."}, {"id": 2, "text": "Los estafadores montan telares vacíos y piden seda e hilos de oro."}, {"id": 3, "text": "El viejo ministro visita el taller, no ve nada y finge admirar la tela."}, {"id": 4, "text": "Otro funcionario hace lo mismo para no pasar por tonto."}, {"id": 5, "text": "Por fin, el propio emperador visita el taller y también finge ver la tela."}]}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('e15ae309-a1f4-4705-a752-234ce7a77f5b', '2026-11-19 12:31:22.404982-03', '2026-11-19 12:31:22.404982-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El desfile", "fragments": [{"id": 1, "text": "Los estafadores simulan cortar la tela y coser con agujas sin hilo."}, {"id": 2, "text": "Los ayudantes del emperador lo visten con el traje invisible."}, {"id": 3, "text": "El emperador sale a desfilar por la ciudad bajo un palio."}, {"id": 4, "text": "Un niño grita que el emperador no lleva nada puesto."}, {"id": 5, "text": "El pueblo repite lo que dijo el niño, pero el emperador sigue desfilando con orgullo."}]}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('a013568d-0b70-49c0-98d7-c7e504447789', '2026-11-19 12:31:22.406983-03', '2026-11-19 12:31:22.406983-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["ancianos", "tontos", "sirvientes", "niños"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "Los estafadores dijeron que la tela era invisible para los", "correctWord": "tontos"}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('f9cc38a2-baab-4b56-b225-5ad6321f7730', '2026-11-19 12:31:22.407979-03', '2026-11-19 12:31:22.407979-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["puesto", "escrito", "pintado", "dicho"], "timeLeft": 7.0, "textAfter": "! —gritó el niño.", "textBefore": "—¡Pero si el emperador no lleva nada", "correctWord": "puesto"}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('971d80f9-d764-4db3-bef4-55084c73b03f', '2026-11-19 12:31:22.40901-03', '2026-11-19 12:31:22.40901-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El taller de los tejedores", "imageUrl": "assets/images/testigo/traje_taller_interior.png", "questions": [{"prompt": "¿Cuántos telares había?", "options": ["Cuatro", "Dos", "Tres", "Uno"], "correctOption": "Dos"}, {"prompt": "¿De qué color eran los gorros de los tejedores?", "options": ["Verdes", "Negros", "Rojos", "Azules"], "correctOption": "Rojos"}, {"prompt": "¿Cuántas velas estaban encendidas?", "options": ["Una", "Dos", "Cinco", "Tres"], "correctOption": "Tres"}], "imageDescription": "Taller con dos telares de madera vacíos; dos hombres con gorros rojos fingiendo tejer; sobre una mesa, unas tijeras grandes y un carrete de hilo dorado; tres velas encendidas; una ventana con luna."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('393b4950-44f9-44e1-b62b-56e18fdce70c', '2026-11-19 12:31:22.410506-03', '2026-11-19 12:31:22.410506-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El desfile del emperador", "imageUrl": "assets/images/testigo/traje_calle_desfile.png", "questions": [{"prompt": "¿De qué color era el palio?", "options": ["Azul", "Amarillo", "Rojo", "Verde"], "correctOption": "Azul"}, {"prompt": "¿Cuántos hombres sostenían el palio?", "options": ["Cuatro", "Seis", "Tres", "Dos"], "correctOption": "Cuatro"}, {"prompt": "¿De qué color eran las banderas de los balcones?", "options": ["Azules", "Verdes", "Rojas", "Blancas"], "correctOption": "Rojas"}], "imageDescription": "Calle de una ciudad con gente a ambos lados; el emperador con corona dorada caminando en ropa interior blanca; dos ayudantes detrás con las manos levantadas; un palio azul con bordes dorados sostenido por cuatro hombres; un niño señalando; banderas rojas en los balcones."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('7c6ce3df-4c8a-4b26-bc99-e906ac8b92c6', '2026-11-19 12:31:22.424962-03', '2026-11-19 12:31:22.424962-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Bienvenido a mi fiesta, soldadito!", "isCorrect": false}, {"text": "¡Ya es hora de ir a nadar!", "isCorrect": false}, {"text": "¡No mires tanto a la bailarina!", "isCorrect": true}, {"text": "¡Te regalaré mi caja de música!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/soldadito_duende.png", "imageDescription": "Un duende negro que sale de una cajita de rapé con cara enfadada, mirando a un soldadito de plomo sobre una mesa de juguetes, de noche."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('53b6991a-60e8-429c-a8d8-71745e4401fa', '2026-11-19 12:31:22.411934-03', '2026-11-19 12:31:22.411934-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-2", "name": "Tijeras grandes", "imageUrl": "assets/images/cazador-intrusos/tijeras.png", "isIntruder": false, "imageDescription": "Tijeras grandes de sastre con mango negro, fondo transparente."}, {"id": "item-3", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-4", "name": "Carrete de hilo dorado", "imageUrl": "assets/images/cazador-intrusos/hilo-dorado.png", "isIntruder": false, "imageDescription": "Carrete de hilo dorado brillante, fondo transparente."}, {"id": "item-5", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-6", "name": "Telar de madera", "imageUrl": "assets/images/cazador-intrusos/telar.png", "isIntruder": false, "imageDescription": "Telar de madera antiguo con hilos tensos, fondo transparente."}], "title": "El taller de los tejedores", "bgImageUrl": "assets/images/cazador-intrusos/traje-taller-bg.jpg", "textDescription": "En el taller de los falsos tejedores había un telar de madera, unas tijeras grandes y un carrete de hilo dorado.", "bgImageDescription": "Taller antiguo con paredes de piedra, una mesa de madera y una ventana con luz cálida; espacio libre para 6 objetos."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('360aea15-b471-4bda-aa89-fb9e4ad5b8db', '2026-11-19 12:31:22.412932-03', '2026-11-19 12:31:22.412932-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Calculadora solar", "imageUrl": "assets/images/cazador-intrusos/calculadora.png", "isIntruder": true}, {"id": "item-2", "name": "Capa real", "imageUrl": "assets/images/cazador-intrusos/capa.png", "isIntruder": false}, {"id": "item-3", "name": "Corona del emperador", "imageUrl": "assets/images/cazador-intrusos/corona-rey.png", "isIntruder": false}, {"id": "item-4", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-5", "name": "Cofre de oro", "imageUrl": "assets/images/cazador-intrusos/cofre.png", "isIntruder": false}, {"id": "item-6", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}], "title": "El palacio del emperador", "bgImageUrl": "assets/images/cazador-intrusos/traje-palacio-bg.jpg", "textDescription": "En el palacio del emperador había una corona, una capa real y un cofre de oro.", "bgImageDescription": "Salón de un palacio con columnas, alfombra roja y cortinas doradas; espacio libre para 6 objetos."}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('b29c227c-2c1d-443f-b200-216837f329c4', '2026-11-19 12:31:22.414932-03', '2026-11-19 12:31:22.414932-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/traje-taller-busca.jpg", "storyTitle": "El traje nuevo del emperador", "targetArea": {"top": 55, "left": 45, "width": 50, "height": 30}, "textSnippet": "Sobre la mesa del taller, entre carretes de hilo, brillaban unas tijeras de plata del estafador.", "imageDescription": "Taller con una mesa de madera llena de carretes de hilo. En la parte inferior derecha, unas tijeras grandes de plata, con un destello leve que las distingue de la madera. Escena muy recargada: la mesa tiene muchos carretes de hilo, telas, agujas, cintas, otras tijeras y rollos de seda.", "targetObjectName": "Tijeras"}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('7036e577-a74c-4cac-ac11-0b8a5a7a21cd', '2026-11-19 12:31:22.415932-03', '2026-11-19 12:31:22.415932-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/traje-desfile-busca.jpg", "storyTitle": "El traje nuevo del emperador", "targetArea": {"top": 40, "left": 12, "width": 20, "height": 50}, "textSnippet": "Entre la multitud del desfile, un niño pequeño señalaba con el dedo al emperador.", "imageDescription": "Calle con algunas personas mirando un desfile. En la parte izquierda, un niño pequeño señalando con el dedo, algo más iluminado y con contorno más marcado que el resto.", "targetObjectName": "Niño que señala"}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('1ff6b394-38ba-4435-acdb-e805b925145a', '2026-11-19 12:31:22.41696-03', '2026-11-19 12:31:22.41696-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Los falsos tejedores", "panels": [{"id": 1, "image": "assets/images/comics/traje1.png", "imageDescription": "Dos hombres llegan a la ciudad con bolsos y se presentan ante el emperador."}, {"id": 2, "image": "assets/images/comics/traje2.png", "imageDescription": "Los tejedores montan un telar vacío y reciben seda e hilos de oro."}, {"id": 3, "image": "assets/images/comics/traje3.png", "imageDescription": "Un viejo ministro mira el telar vacío con cara de sorpresa."}, {"id": 4, "image": "assets/images/comics/traje4.png", "imageDescription": "El emperador visita el taller y finge ver la tela, con los tejedores a su lado."}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('f1c30241-adf9-45c0-b9b2-cfb6af5896d8', '2026-11-19 12:31:22.417932-03', '2026-11-19 12:31:22.417932-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El desfile", "panels": [{"id": 1, "image": "assets/images/comics/traje5.png", "imageDescription": "Los ayudantes del emperador lo visten con un traje invisible frente a un espejo."}, {"id": 2, "image": "assets/images/comics/traje6.png", "imageDescription": "El emperador camina bajo un palio por la ciudad, con ropa interior blanca."}, {"id": 3, "image": "assets/images/comics/traje7.png", "imageDescription": "Un niño señala al emperador entre la multitud."}, {"id": 4, "image": "assets/images/comics/traje8.png", "imageDescription": "El pueblo ríe y el emperador sigue desfilando muy erguido."}]}', '6ca6bc3b-48ef-4d0c-94b0-7a8a5dd6bc97', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('7ab1241d-f5c2-47e2-b487-8ae0c6c1f87c', '2026-11-19 12:31:22.421931-03', '2026-11-19 12:31:22.421931-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Los soldaditos eran de plomo.", "isTrue": true}, {"text": "Eran veinte soldaditos.", "isTrue": false}, {"text": "Uno de ellos tenía una sola pierna.", "isTrue": true}], "passage_text": "Un niño recibió por su cumpleaños veinticinco soldaditos de plomo, hechos de una vieja cuchara. Uno de ellos solo tenía una pierna, porque no alcanzó el plomo para terminarlo.", "time_per_statement": 7}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('b1d9dbcf-be85-404e-adef-5454ab384641', '2026-11-19 12:31:22.421931-03', '2026-11-19 12:31:22.421931-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La bailarina era de papel.", "isTrue": true}, {"text": "El castillo era de madera.", "isTrue": false}, {"text": "La bailarina levantaba una pierna.", "isTrue": true}], "passage_text": "Sobre la mesa había un hermoso castillo de papel. En la puerta estaba una bailarina de papel, que levantaba una pierna tan alto que el soldadito creyó que ella también tenía una sola pierna.", "time_per_statement": 7}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('0dcd1309-2502-44a8-83fc-e61faaeb48f8', '2026-11-19 12:31:22.423932-03', '2026-11-19 12:31:22.423932-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Quiero salir a jugar a la calle!", "isCorrect": false}, {"text": "¡Me gustaría ser un pirata del mar!", "isCorrect": false}, {"text": "¡Qué hermosa bailarina! Ella también tiene una sola pierna.", "isCorrect": true}, {"text": "¡Tengo mucho sueño, me iré a dormir!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/soldadito_bailarina.png", "imageDescription": "Un soldadito de plomo de pie sobre una sola pierna, con uniforme rojo y azul, mirando enamorado a una bailarina de papel con vestido blanco y cinta azul frente a un castillo de papel."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('b0aa4890-82fe-4883-a4db-3db65e760bef', '2026-11-19 12:31:22.425932-03', '2026-11-19 12:31:22.425932-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Un muñeco de nieve", "El soldadito de plomo", "Un robot", "Un guardia real", "Un cascanueces"], "imageSrc": "assets/images/pixelado/soldadito_personaje.png", "correctCharacter": "El soldadito de plomo", "imageDescription": "Un soldadito de plomo de una sola pierna, con uniforme rojo y azul y un fusil al hombro, sobre una mesa de madera."}], "total_time": 7}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('57660901-4234-46b8-a68d-b746a62a77bb', '2026-11-19 12:31:22.427519-03', '2026-11-19 12:31:22.427519-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un hada", "Una princesa", "Una muñeca de trapo", "La bailarina de papel", "Una marioneta"], "imageSrc": "assets/images/pixelado/soldadito_bailarina_papel.png", "correctCharacter": "La bailarina de papel", "imageDescription": "Una bailarina de papel con vestido blanco, una cinta azul y una lentejuela dorada, de pie sobre una pierna con la otra levantada."}], "total_time": 7}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('880c398c-a74d-4764-ad05-8ec72c00c78a', '2026-11-19 12:31:22.428937-03', '2026-11-19 12:31:22.428937-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 841, "altText": "Barco pirata de metal", "imageSrc": "assets/images/contra/soldadito_barco_pirata.png", "isContradiction": true, "imageDescription": "El soldadito de plomo a bordo de un barco pirata de metal en un canal."}, {"id": 842, "altText": "Barquito flotando", "imageSrc": "assets/images/contra/soldadito_barquito_flota.png", "isContradiction": false, "imageDescription": "Un barquito de papel blanco con el soldadito de pie, flotando en una acequia de piedra."}, {"id": 843, "altText": "Niños dejando el barquito", "imageSrc": "assets/images/contra/soldadito_ninos_barquito.png", "isContradiction": false, "imageDescription": "Dos niños con impermeables amarillos dejando un barquito de papel sobre el agua de un canal."}, {"id": 844, "altText": "Soldadito con gesto firme", "imageSrc": "assets/images/contra/soldadito_gesto_firme.png", "isContradiction": false, "imageDescription": "El soldadito de pie en el barquito, mirando al frente con gesto firme."}], "explanation": "La imagen contradictoria muestra al soldadito en un barco pirata de metal.", "premiseText": "El soldadito de plomo viajó por el canal en un barquito hecho de papel."}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('a268a5ea-66b6-4264-a180-13e46a45976c', '2026-11-19 12:31:22.429935-03', '2026-11-19 12:31:22.429935-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 851, "altText": "Bailarina de rojo", "imageSrc": "assets/images/contra/soldadito_bailarina_roja.png", "isContradiction": true, "imageDescription": "Una bailarina de papel con vestido rojo y sombrero de copa negro."}, {"id": 852, "altText": "Lentejuela dorada", "imageSrc": "assets/images/contra/soldadito_lentejuela.png", "isContradiction": false, "imageDescription": "Primer plano de una pequeña lentejuela dorada brillante sobre papel blanco."}, {"id": 853, "altText": "Cinta azul", "imageSrc": "assets/images/contra/soldadito_cinta_azul.png", "isContradiction": false, "imageDescription": "Primer plano de una cinta azul brillante sobre un vestido blanco de papel."}, {"id": 854, "altText": "Bailarina sobre una pierna", "imageSrc": "assets/images/contra/soldadito_bailarina_pierna.png", "isContradiction": false, "imageDescription": "Una bailarina de papel con vestido blanco equilibrada sobre una pierna."}], "explanation": "La imagen contradictoria muestra a una bailarina con vestido rojo y sombrero de copa.", "premiseText": "La bailarina de papel llevaba un vestido blanco con una cinta azul y una lentejuela brillante."}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('5f894797-8e07-49c1-853a-a201e61c54cc', '2026-11-19 12:31:22.430937-03', '2026-11-19 12:31:22.430937-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El soldadito y la bailarina", "fragments": [{"id": 1, "text": "En su cumpleaños, un niño recibe veinticinco soldaditos de plomo."}, {"id": 2, "text": "El soldadito de una sola pierna se enamora de una bailarina de papel."}, {"id": 3, "text": "El duende de la cajita le dice que no la mire."}, {"id": 4, "text": "A la mañana siguiente, el soldadito cae por la ventana a la calle."}, {"id": 5, "text": "Dos niños lo ponen en un barquito de papel y lo dejan en el agua de la acequia."}]}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('c32e896e-f38b-41ba-abe1-9c9c2aa64680', '2026-11-19 12:31:22.431935-03', '2026-11-19 12:31:22.431935-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El viaje del soldadito", "fragments": [{"id": 1, "text": "El barquito entra a una alcantarilla donde una rata le pide su pasaporte."}, {"id": 2, "text": "La corriente lo lleva hasta una cascada y el barquito se hunde."}, {"id": 3, "text": "Un gran pez se lo traga."}, {"id": 4, "text": "Pescan al pez y lo abren en una cocina; el soldadito aparece en la misma casa."}, {"id": 5, "text": "El niño lo arroja a la estufa y el soldadito se derrite en forma de corazón."}]}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('4cfeead4-14e0-4d4c-959e-b0f29caa3677', '2026-11-19 12:31:22.433938-03', '2026-11-19 12:31:22.433938-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["manga", "pierna", "espada", "oreja"], "timeLeft": 7.0, "textAfter": "porque no alcanzó el plomo.", "textBefore": "El soldadito tenía una sola", "correctWord": "pierna"}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('e485e41a-fcf5-4f1a-a2ea-2d5a8d12e1cd', '2026-11-19 12:31:22.434936-03', '2026-11-19 12:31:22.434936-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["anillo", "corazón", "botón", "soldado"], "timeLeft": 7.0, "textAfter": "de plomo.", "textBefore": "Al final, el soldadito se derritió y quedó convertido en un pequeño", "correctWord": "corazón"}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('288f07ed-a327-43b7-b953-55ae699e4a7d', '2026-11-19 12:31:22.435969-03', '2026-11-19 12:31:22.435969-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La mesa de juguetes", "imageUrl": "assets/images/testigo/soldadito_mesa_juguetes.png", "questions": [{"prompt": "¿Cuántas torres tenía el castillo?", "options": ["Dos", "Tres", "Cuatro", "Una"], "correctOption": "Dos"}, {"prompt": "¿De qué color era la cinta de la bailarina?", "options": ["Azul", "Verde", "Roja", "Amarilla"], "correctOption": "Azul"}, {"prompt": "¿Qué parecía un lago junto al castillo?", "options": ["Un plato con agua", "Una bañera", "Una alfombra azul", "Un espejo con cisnes de cera"], "correctOption": "Un espejo con cisnes de cera"}], "imageDescription": "Una mesa de juguetes: un castillo de papel blanco con dos torres; frente a la puerta una bailarina de papel con una pierna levantada, cinta azul y lentejuela; al lado, un espejo que parece un lago, con cisnes de cera."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('b8cdc7dc-d1d1-428b-8917-b3dde79a4444', '2026-11-19 12:31:22.448594-03', '2026-11-19 12:31:22.448594-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "La mujer deseaba comer rapónchigos.", "isTrue": true}, {"text": "El esposo compró un kilo de rapónchigos a la bruja.", "isTrue": false}, {"text": "El matrimonio vivía junto al jardín de una bruja.", "isTrue": true}], "passage_text": "Un matrimonio vivía junto al jardín de una bruja. La mujer deseó tanto comer rapónchigos del jardín que su esposo los robó.", "time_per_statement": 7}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('04599837-c7f5-4e40-8e97-8f6afb5b5008', '2026-11-19 12:31:22.436935-03', '2026-11-19 12:31:22.436935-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El canal de la ciudad", "imageUrl": "assets/images/testigo/soldadito_canal_lluvia.png", "questions": [{"prompt": "¿De qué color eran los impermeables de los niños?", "options": ["Azules", "Verdes", "Amarillos", "Rojos"], "correctOption": "Amarillos"}, {"prompt": "¿Qué animal asomaba por el agujero?", "options": ["Un sapo", "Un gato", "Un pájaro", "Una rata"], "correctOption": "Una rata"}, {"prompt": "¿De qué color era el barquito?", "options": ["Azul", "Negro", "Blanco", "Rojo"], "correctOption": "Blanco"}], "imageDescription": "Una acequia de piedra después de la lluvia; un barquito de papel blanco con el soldadito de pie; dos niños en la orilla con impermeables amarillos; una rata asomándose de un agujero; un farol de hierro."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('551c4034-ce12-4a26-b200-31206a52cb11', '2026-11-19 12:31:22.438937-03', '2026-11-19 12:31:22.438937-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-2", "name": "Soldadito de plomo", "imageUrl": "assets/images/cazador-intrusos/soldadito-plomo.png", "isIntruder": false, "imageDescription": "Soldadito de plomo de una sola pierna, uniforme rojo y azul, fondo transparente."}, {"id": "item-3", "name": "Castillo de papel", "imageUrl": "assets/images/cazador-intrusos/castillo-papel.png", "isIntruder": false, "imageDescription": "Castillo de papel blanco con dos torres y una puerta, fondo transparente."}, {"id": "item-4", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-5", "name": "Bailarina de papel", "imageUrl": "assets/images/cazador-intrusos/bailarina-papel.png", "isIntruder": false, "imageDescription": "Bailarina de papel sobre una pierna con cinta azul, fondo transparente."}, {"id": "item-6", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}], "title": "La mesa del cuarto de juguetes", "bgImageUrl": "assets/images/cazador-intrusos/soldadito-cuarto-bg.jpg", "textDescription": "Sobre la mesa estaban el soldadito de plomo, el castillo de papel y la bailarina de una sola pierna.", "bgImageDescription": "Cuarto de juguetes de un niño con una mesa de madera, alfombra y una ventana; espacio libre para 6 objetos."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('1536124e-6995-454b-b0ae-059c98ced3f2', '2026-11-19 12:31:22.439938-03', '2026-11-19 12:31:22.439938-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Rata", "imageUrl": "assets/images/cazador-intrusos/rata.png", "isIntruder": false, "imageDescription": "Rata gris de cola larga, de perfil, fondo transparente."}, {"id": "item-2", "name": "Submarino", "imageUrl": "assets/images/cazador-intrusos/submarino.png", "isIntruder": true}, {"id": "item-3", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-4", "name": "Patineta eléctrica", "imageUrl": "assets/images/cazador-intrusos/patineta.png", "isIntruder": true}, {"id": "item-5", "name": "Gran pez", "imageUrl": "assets/images/cazador-intrusos/pez-grande.png", "isIntruder": false, "imageDescription": "Pez grande y gris con la boca abierta, fondo transparente."}, {"id": "item-6", "name": "Barquito de papel", "imageUrl": "assets/images/cazador-intrusos/barquito-papel.png", "isIntruder": false, "imageDescription": "Barquito de papel blanco visto de costado, fondo transparente."}], "title": "El viaje por el canal", "bgImageUrl": "assets/images/cazador-intrusos/soldadito-canal-bg.jpg", "textDescription": "En el canal navegaba un barquito de papel, una rata observaba desde un agujero y un gran pez esperaba bajo el agua.", "bgImageDescription": "Canal de piedra de una ciudad antigua después de la lluvia, con agua marrón y farolas; espacio libre para 6 objetos."}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('3f5aaede-42dc-49ef-a909-43710a1fccb0', '2026-11-19 12:31:22.441935-03', '2026-11-19 12:31:22.441935-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/soldadito-mesa-busca.jpg", "storyTitle": "El soldadito de plomo", "targetArea": {"top": 28, "left": 35, "width": 30, "height": 50}, "textSnippet": "Junto al castillo de papel, sobre la mesa de juguetes, una bailarina equilibrada en una pierna esperaba al soldadito.", "imageDescription": "Mesa de juguetes con un castillo de papel. En la parte central, una bailarina de papel grande sobre una pierna, más clara que el castillo y con una cinta de color apagado. Escena muy recargada: la mesa está llena de soldaditos de plomo, muñecas, cajas, bloques, un castillo de papel y otros juguetes.", "targetObjectName": "Bailarina de papel"}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('01050919-df8e-4161-9127-3a9a84e3ad9e', '2026-11-19 12:31:22.442937-03', '2026-11-19 12:31:22.442937-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/soldadito-acequia-busca.jpg", "storyTitle": "El soldadito de plomo", "targetArea": {"top": 62, "left": 40, "width": 50, "height": 20}, "textSnippet": "Al borde de la acequia, entre las piedras mojadas, flotaba un pequeño barquito de papel.", "imageDescription": "Acequia de piedra con agua oscura. En la parte inferior derecha, un barquito de papel blanco flotando, más claro que el agua y con contorno marcado.", "targetObjectName": "Barquito de papel"}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('b4317693-31ec-4688-893b-d6ac958b98e6', '2026-11-19 12:31:22.443966-03', '2026-11-19 12:31:22.443966-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "El soldadito cae", "panels": [{"id": 1, "image": "assets/images/comics/soldadito1.png", "imageDescription": "Un niño abre una caja con veinticinco soldaditos de plomo en su cumpleaños."}, {"id": 2, "image": "assets/images/comics/soldadito2.png", "imageDescription": "El soldadito de una sola pierna mira a la bailarina de papel frente al castillo."}, {"id": 3, "image": "assets/images/comics/soldadito3.png", "imageDescription": "De noche, el duende negro sale de su cajita y mira al soldadito con enojo."}, {"id": 4, "image": "assets/images/comics/soldadito4.png", "imageDescription": "El soldadito cae por la ventana abierta hacia la calle."}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('e624e893-143b-49be-bf7b-4c2c88a53147', '2026-11-19 12:31:22.445332-03', '2026-11-19 12:31:22.445332-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El viaje", "panels": [{"id": 1, "image": "assets/images/comics/soldadito5.png", "imageDescription": "Dos niños ponen al soldadito en un barquito de papel sobre un canal de lluvia."}, {"id": 2, "image": "assets/images/comics/soldadito6.png", "imageDescription": "El barquito pasa por una alcantarilla oscura donde una rata lo mira."}, {"id": 3, "image": "assets/images/comics/soldadito7.png", "imageDescription": "Un gran pez traga al soldadito en el agua."}, {"id": 4, "image": "assets/images/comics/soldadito8.png", "imageDescription": "En la estufa, el soldadito se derrite en forma de pequeño corazón, y a su lado queda la lentejuela de la bailarina."}]}', '65f40872-dfb2-4e3d-ae62-e7c653fe371a', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('1b83dd1a-9f0e-4d35-a109-975c3ba2f4dc', '2026-11-19 12:31:22.461604-03', '2026-11-19 12:31:22.461604-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["techo", "puertas", "ladrillos", "cimientos"], "timeLeft": 7.0, "textAfter": "sino una pequeña ventana.", "textBefore": "La torre en la que vivía Rapunzel no tenía", "correctWord": "puertas"}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('7062954d-2672-4a1f-b318-ce1476fb70c5', '2026-11-19 12:31:22.449602-03', '2026-11-19 12:31:22.449602-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La torre tenía una sola ventana.", "isTrue": true}, {"text": "La torre tenía una gran puerta de hierro.", "isTrue": false}, {"text": "La bruja subía trepando por el cabello de Rapunzel.", "isTrue": true}], "passage_text": "Cuando Rapunzel cumplió doce años, la bruja la encerró en una torre sin puertas y con una sola ventana. Para subir, gritaba: «Rapunzel, Rapunzel, suéltame tu cabello».", "time_per_statement": 7}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('d3590efb-ba7f-42a9-b802-3731edb8a8dd', '2026-11-19 12:31:22.450604-03', '2026-11-19 12:31:22.450604-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Quiero bañarme en el río!", "isCorrect": false}, {"text": "¡Qué bonito es cantar en lo alto de mi torre!", "isCorrect": true}, {"text": "¡Tengo tanta hambre que comeré lechugas!", "isCorrect": false}, {"text": "¡Voy a salir por la puerta a pasear!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/rapunzel_canta.png", "imageDescription": "Rapunzel con una larga trenza dorada que cae por la ventana de una torre alta, cantando con los ojos cerrados, rodeada de pájaros."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('e196a754-4d84-4d51-8204-57c90f9a86a3', '2026-11-19 12:31:22.451602-03', '2026-11-19 12:31:22.451602-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Rapunzel, Rapunzel, suéltame tu cabello!", "isCorrect": true}, {"text": "¡Rapunzel, ven a jugar al jardín!", "isCorrect": false}, {"text": "¡Qué bonita es la luna esta noche!", "isCorrect": false}, {"text": "¡Hola, vengo a traerte una puerta!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/rapunzel_bruja_llama.png", "imageDescription": "Una bruja con capa negra al pie de una torre sin puertas, con las manos junto a la boca, llamando hacia una ventana en lo alto."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('33f360be-f879-4c56-abf2-bfc24f44da9d', '2026-11-19 12:31:22.453603-03', '2026-11-19 12:31:22.453603-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El hada", "La bruja", "La princesa", "Rapunzel", "La reina"], "imageSrc": "assets/images/pixelado/rapunzel_personaje.png", "correctCharacter": "Rapunzel", "imageDescription": "Rapunzel, joven de cabello dorado larguísimo con una trenza que cae hasta el suelo, vestida con un vestido sencillo, asomada a una ventana."}], "total_time": 7}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('e6609b2b-825b-41d3-b0c4-e3476b9bb9a0', '2026-11-19 12:31:22.454602-03', '2026-11-19 12:31:22.454602-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un faro", "Un castillo", "Un molino", "Un campanario", "La torre sin puertas"], "imageSrc": "assets/images/pixelado/rapunzel_torre.png", "correctCharacter": "La torre sin puertas", "imageDescription": "Una torre alta de piedra gris sin puertas, con una sola ventana pequeña en lo alto, en medio de un bosque."}], "total_time": 7}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('97529837-8998-48d0-b8aa-db05f77ae59a', '2026-11-19 12:31:22.455632-03', '2026-11-19 12:31:22.455632-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 861, "altText": "Trenza dorada por la ventana", "imageSrc": "assets/images/contra/rapunzel_trenza_ventana.png", "isContradiction": false, "imageDescription": "Una larguísima trenza dorada cayendo por la ventana de una torre hasta el suelo."}, {"id": 862, "altText": "Rapunzel arreglando su cabello", "imageSrc": "assets/images/contra/rapunzel_peinando.png", "isContradiction": false, "imageDescription": "Rapunzel sentada peinando su cabello dorado larguísimo que cubre el suelo del cuarto."}, {"id": 863, "altText": "Rapunzel de pelo corto", "imageSrc": "assets/images/contra/rapunzel_pelo_corto.png", "isContradiction": true, "imageDescription": "Rapunzel con el cabello corto y negro, asomada a la ventana de una torre."}, {"id": 864, "altText": "Trenza atada al gancho", "imageSrc": "assets/images/contra/rapunzel_trenza_gancho.png", "isContradiction": false, "imageDescription": "Primer plano de una trenza dorada larga atada a un gancho de la ventana."}], "explanation": "La imagen contradictoria muestra a Rapunzel con el cabello corto y negro, asomada a la ventana.", "premiseText": "Rapunzel tenía el cabello larguísimo y dorado, y lo dejaba caer por la ventana de la torre."}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('9a6d55cc-c7f3-4016-9c3a-fd975fa83f61', '2026-11-19 12:31:22.456604-03', '2026-11-19 12:31:22.456604-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 871, "altText": "Torre con puerta roja", "imageSrc": "assets/images/contra/rapunzel_torre_puerta_roja.png", "isContradiction": true, "imageDescription": "Una torre de piedra con una gran puerta roja y una escalera en la entrada."}, {"id": 872, "altText": "Torre sin puertas", "imageSrc": "assets/images/contra/rapunzel_torre_sin_puerta.png", "isContradiction": false, "imageDescription": "Una torre alta de piedra, sin ninguna puerta, rodeada de árboles."}, {"id": 873, "altText": "Ventana en lo alto", "imageSrc": "assets/images/contra/rapunzel_ventana_alta.png", "isContradiction": false, "imageDescription": "Una pequeña ventana en lo más alto de una torre de piedra gris."}, {"id": 874, "altText": "Hiedra en la torre", "imageSrc": "assets/images/contra/rapunzel_hiedra_torre.png", "isContradiction": false, "imageDescription": "Una torre cubierta de hiedra en su parte baja, sin puerta visible."}], "explanation": "La imagen contradictoria muestra una torre con una gran puerta roja y escaleras en la entrada.", "premiseText": "La torre de Rapunzel no tenía puertas, solo una pequeña ventana en lo alto."}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('048a6b36-1033-4b64-9eb2-16f72b6cc9b0', '2026-11-19 12:31:22.458637-03', '2026-11-19 12:31:22.458637-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La torre", "fragments": [{"id": 1, "text": "Un matrimonio espera un hijo, y la mujer desea comer rapónchigos del jardín de una bruja."}, {"id": 2, "text": "El marido roba los rapónchigos y la bruja lo descubre."}, {"id": 3, "text": "A cambio de perdonarlo, la bruja se queda con la niña, a quien llama Rapunzel."}, {"id": 4, "text": "Cuando cumple doce años, la bruja encierra a Rapunzel en una torre sin puertas."}, {"id": 5, "text": "La bruja sube cada día a la torre trepando por el largo cabello de Rapunzel."}]}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('c45daddd-e911-43cc-a50f-b2dacaaf585a', '2026-11-19 12:31:22.459604-03', '2026-11-19 12:31:22.459604-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El príncipe", "fragments": [{"id": 1, "text": "Un príncipe escucha cantar a Rapunzel mientras pasea por el bosque."}, {"id": 2, "text": "Escondido, ve a la bruja subir por el cabello y repite sus palabras."}, {"id": 3, "text": "Rapunzel y el príncipe se enamoran y planean escapar."}, {"id": 4, "text": "La bruja se entera, corta el cabello de Rapunzel y la envía lejos."}, {"id": 5, "text": "El príncipe cae entre espinas y queda ciego, pero las lágrimas de Rapunzel lo curan al reencontrarse."}]}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('734a6ea1-4180-408d-87fb-6cb37381b12c', '2026-11-19 12:31:22.460632-03', '2026-11-19 12:31:22.460632-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["escalera", "pañuelo", "cabello", "cuerda"], "timeLeft": 7.0, "textAfter": "—gritaba la bruja.", "textBefore": "—Rapunzel, Rapunzel, suéltame tu", "correctWord": "cabello"}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('33123745-0490-4426-b11b-d6376e8497f6', '2026-11-19 12:31:22.463603-03', '2026-11-19 12:31:22.463603-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La torre de Rapunzel", "imageUrl": "assets/images/testigo/rapunzel_torre_bosque.png", "questions": [{"prompt": "¿De qué color eran las cortinas de la ventana?", "options": ["Blancas", "Verdes", "Rosadas", "Azules"], "correctOption": "Rosadas"}, {"prompt": "¿Cuántos pájaros azules había sobre el tejado?", "options": ["Cinco", "Tres", "Dos", "Uno"], "correctOption": "Tres"}, {"prompt": "¿Qué llevaba la bruja en la cabeza?", "options": ["Nada", "Un sombrero puntiagudo", "Una corona", "Un pañuelo"], "correctOption": "Un sombrero puntiagudo"}], "imageDescription": "Una torre alta de piedra gris en un bosque, sin puertas; en lo alto una ventana pequeña con cortinas rosadas; una trenza dorada que cuelga hasta el suelo; una bruja con capa negra y sombrero puntiagudo; tres pájaros azules sobre el tejado."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('a8f2c2a3-d61a-4ac2-a64d-b2e73852f903', '2026-11-19 12:31:22.464604-03', '2026-11-19 12:31:22.464604-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El jardín de la bruja", "imageUrl": "assets/images/testigo/rapunzel_jardin_bruja.png", "questions": [{"prompt": "¿Qué sostenía el hombre?", "options": ["Un saco", "Una cesta", "Un farol", "Una pala"], "correctOption": "Una cesta"}, {"prompt": "¿De qué era el muro?", "options": ["Arbustos", "Piedra", "Madera", "Ladrillo rojo"], "correctOption": "Piedra"}, {"prompt": "¿Qué había cultivado en hileras?", "options": ["Calabazas", "Rapónchigos de hojas verdes", "Tomates rojos", "Zanahorias"], "correctOption": "Rapónchigos de hojas verdes"}], "imageDescription": "Un jardín rodeado por un alto muro de piedra; hileras de rapónchigos de hojas verdes; un hombre asomado sobre el muro con una cesta en la mano."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('70e93d00-0180-475b-9504-39b4df032446', '2026-11-19 12:31:22.465633-03', '2026-11-19 12:31:22.465633-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-2", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-3", "name": "Rapónchigos", "imageUrl": "assets/images/cazador-intrusos/raponchigos.png", "isIntruder": false, "imageDescription": "Manojo de rapónchigos con hojas verdes y raíz blanca, fondo transparente."}, {"id": "item-4", "name": "Flores del jardín", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-5", "name": "Sombrero de bruja", "imageUrl": "assets/images/cazador-intrusos/sombrero-bruja.png", "isIntruder": false, "imageDescription": "Sombrero negro puntiagudo de bruja con una cinta morada, fondo transparente."}, {"id": "item-6", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}], "title": "El jardín de la bruja", "bgImageUrl": "assets/images/cazador-intrusos/rapunzel-jardin-bg.jpg", "textDescription": "En el jardín de la bruja crecían rapónchigos y flores, y colgaba su sombrero puntiagudo de un clavo.", "bgImageDescription": "Jardín cercado por un muro de piedra, con tierra labrada y cielo claro; espacio libre para 6 objetos."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('1df4a1b0-6386-4191-8277-50311856c8cc', '2026-11-19 12:31:22.466602-03', '2026-11-19 12:31:22.466602-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Tijeras", "imageUrl": "assets/images/cazador-intrusos/tijeras.png", "isIntruder": false}, {"id": "item-2", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-3", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-4", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-5", "name": "Trenza dorada", "imageUrl": "assets/images/cazador-intrusos/trenza-dorada.png", "isIntruder": false, "imageDescription": "Larga trenza dorada enrollada, con un lazo rosado, fondo transparente."}, {"id": "item-6", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}], "title": "La torre de Rapunzel", "bgImageUrl": "assets/images/cazador-intrusos/rapunzel-cuarto-bg.jpg", "textDescription": "En la torre de Rapunzel había una larga trenza dorada, unas tijeras y una cama de madera.", "bgImageDescription": "Cuarto circular de una torre de piedra con una ventana pequeña y suelo de madera; espacio libre para 6 objetos."}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('003dcf27-ac92-4090-8429-f78fb4214106', '2026-11-19 12:31:22.468603-03', '2026-11-19 12:31:22.468603-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/rapunzel-torre-busca.jpg", "storyTitle": "Rapunzel", "targetArea": {"top": 10, "left": 45, "width": 25, "height": 60}, "textSnippet": "En lo alto de la torre, una pequeña ventana dejaba colgar una larga trenza dorada.", "imageDescription": "Torre alta de piedra en un bosque. En el centro, una trenza dorada larguísima que cuelga desde la ventana hasta el pie de la torre, con un tono apagado más claro que la piedra. Escena muy recargada: alrededor de la torre hay muchas enredaderas, pájaros, árboles, flores, ramas y una trenza falsa de hiedra.", "targetObjectName": "Trenza dorada"}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('12c76d16-c5fa-4ac4-9aae-329ae817a414', '2026-11-19 12:31:22.469605-03', '2026-11-19 12:31:22.469605-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/rapunzel-jardin-busca.jpg", "storyTitle": "Rapunzel", "targetArea": {"top": 62, "left": 12, "width": 50, "height": 20}, "textSnippet": "Cerca del muro de piedra, entre las hileras del huerto, brillaban las hojas verdes de los rapónchigos.", "imageDescription": "Jardín con un muro de piedra y varias verduras. En la parte inferior izquierda, un grupo de rapónchigos de hojas verdes apagadas que destaca levemente entre las demás plantas.", "targetObjectName": "Rapónchigos"}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('db1a137e-7e09-4c85-bab3-d54ad01c6816', '2026-11-19 12:31:22.471148-03', '2026-11-19 12:31:22.471148-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La promesa", "panels": [{"id": 1, "image": "assets/images/comics/rapunzel1.png", "imageDescription": "Una mujer embarazada mira por la ventana el jardín de la bruja lleno de rapónchigos."}, {"id": 2, "image": "assets/images/comics/rapunzel2.png", "imageDescription": "Su esposo salta el muro del jardín y recoge rapónchigos en una cesta."}, {"id": 3, "image": "assets/images/comics/rapunzel3.png", "imageDescription": "La bruja aparece enfurecida con capa negra frente al hombre."}, {"id": 4, "image": "assets/images/comics/rapunzel4.png", "imageDescription": "La bruja se lleva a una bebé en brazos mientras los padres lloran."}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('e4513fbf-a31e-40df-9389-e70ddfc55b2e', '2026-11-19 12:31:22.496383-03', '2026-11-19 12:31:22.496383-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/gigante-muro-busca.jpg", "storyTitle": "El gigante egoísta", "targetArea": {"top": 58, "left": 10, "width": 32, "height": 31.25}, "textSnippet": "Al pie del muro de piedra, un pequeño agujero dejaba pasar a los niños al jardín.", "imageDescription": "Muro de piedra alto cubierto de nieve. En la parte inferior izquierda, un agujero oscuro en la base del muro, con un borde algo más marcado que las piedras.", "targetObjectName": "Agujero del muro"}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('81ee5da3-ed54-40ca-b8e6-55210c07e24c', '2026-11-19 12:31:22.47214-03', '2026-11-19 12:31:22.47214-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La trenza", "panels": [{"id": 1, "image": "assets/images/comics/rapunzel5.png", "imageDescription": "Rapunzel, adolescente, canta en la ventana de la torre con su largo cabello."}, {"id": 2, "image": "assets/images/comics/rapunzel6.png", "imageDescription": "La bruja sube a la torre trepando por la trenza dorada."}, {"id": 3, "image": "assets/images/comics/rapunzel7.png", "imageDescription": "Un príncipe escondido entre los árboles observa la escena."}, {"id": 4, "image": "assets/images/comics/rapunzel8.png", "imageDescription": "El príncipe sube por la trenza y Rapunzel lo recibe sorprendida."}]}', '7f2d4902-945d-40f8-abcc-2a8f107108b4', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('c02d8e27-f771-4276-945d-9d23e9f4bc1c', '2026-11-19 12:31:22.475149-03', '2026-11-19 12:31:22.475149-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Los niños jugaban en el jardín del gigante.", "isTrue": true}, {"text": "El gigante regresó después de siete años.", "isTrue": true}, {"text": "El gigante invitó a los niños a quedarse.", "isTrue": false}], "passage_text": "Los niños jugaban todas las tardes en el hermoso jardín del gigante, lleno de suave césped y de duraznos en flor. Cuando el gigante regresó, después de siete años, los echó de allí.", "time_per_statement": 7}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('0ad777bc-c826-4932-a639-be39d64b7660', '2026-11-19 12:31:22.47615-03', '2026-11-19 12:31:22.47615-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El gigante construyó un alto muro.", "isTrue": true}, {"text": "La primavera llegó pronto al jardín.", "isTrue": false}, {"text": "En el jardín vivían la Nieve y la Escarcha.", "isTrue": true}], "passage_text": "El gigante construyó un alto muro y puso un cartel de prohibida la entrada. Entonces la primavera no llegó a su jardín, y solo vivieron allí la Nieve, la Escarcha y el Viento del Norte.", "time_per_statement": 7}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('9379ed67-7d30-4914-bbac-1036869ac3b6', '2026-11-19 12:31:22.478181-03', '2026-11-19 12:31:22.478181-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¿Qué hacen en mi jardín? ¡Fuera de aquí!", "isCorrect": true}, {"text": "¡Bienvenidos, niños, pueden jugar todo el día!", "isCorrect": false}, {"text": "¡Qué lindos duraznos tengo!", "isCorrect": false}, {"text": "¡Vamos a jugar a la pelota juntos!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/gigante_enojado.png", "imageDescription": "Un gigante enorme con barba y ropa de abrigo, con el ceño fruncido y el dedo señalando a un grupo de niños asustados en un jardín con flores."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('851d6001-6e44-45cc-8112-8d84a6b85b8a', '2026-11-19 12:31:22.47915-03', '2026-11-19 12:31:22.47915-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Cerremos el jardín con otro muro más alto!", "isCorrect": false}, {"text": "¡Qué egoísta fui! Sin niños no hay primavera.", "isCorrect": true}, {"text": "¡Este árbol es mío y nadie lo tocará!", "isCorrect": false}, {"text": "¡Prefiero que el invierno dure para siempre!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/gigante_conmovido.png", "imageDescription": "El gigante, de rodillas en un jardín nevado, ayudando con ternura a un niño pequeño a subir a un árbol que empieza a florecer."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('d6420aa6-905e-4276-85ae-41a66597846f', '2026-11-19 12:31:22.48018-03', '2026-11-19 12:31:22.48018-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["El gigante", "El mago", "El ogro de Cornualles", "El leñador", "El rey"], "imageSrc": "assets/images/pixelado/gigante_personaje.png", "correctCharacter": "El gigante", "imageDescription": "Un gigante enorme y barbudo, con ropa de abrigo, de pie en un jardín, mirando hacia abajo con ceño fruncido."}], "total_time": 7}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('c5c1c3aa-45c9-4881-b26d-544d5b4afb9e', '2026-11-19 12:31:22.481149-03', '2026-11-19 12:31:22.481149-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un sauce llorón", "El árbol florecido", "Un rosal", "Un manzano rojo", "Un pino nevado"], "imageSrc": "assets/images/pixelado/gigante_durazno_flor.png", "correctCharacter": "El árbol florecido", "imageDescription": "Un duraznero cubierto de flores rosadas, con un pajarito posado en una rama, sobre césped verde."}], "total_time": 7}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('43442a50-01b7-4fa9-b820-e22146cdcfe1', '2026-11-19 12:31:22.482151-03', '2026-11-19 12:31:22.482151-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 881, "altText": "Muro alto de piedra", "imageSrc": "assets/images/contra/gigante_muro_alto.png", "isContradiction": false, "imageDescription": "Un muro alto de piedra gris que rodea un jardín nevado."}, {"id": 882, "altText": "Gigante con globos", "imageSrc": "assets/images/contra/gigante_bienvenida_globos.png", "isContradiction": true, "imageDescription": "El gigante abriendo un portón con un cartel de bienvenida y globos de colores, sonriendo."}, {"id": 883, "altText": "Gigante mirando por la ventana", "imageSrc": "assets/images/contra/gigante_mira_ventana.png", "isContradiction": false, "imageDescription": "El gigante mirando serio por la ventana de su casa hacia el jardín cercado."}, {"id": 884, "altText": "Cartel de prohibido", "imageSrc": "assets/images/contra/gigante_cartel_prohibido.png", "isContradiction": false, "imageDescription": "Un cartel de madera con el dibujo de una mano alzada, clavado en el suelo junto al muro."}], "explanation": "La imagen contradictoria muestra al gigante abriendo un portón con un cartel de bienvenida y globos.", "premiseText": "El gigante construyó un alto muro alrededor de su jardín y puso un cartel para prohibir la entrada."}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('83310183-ecd9-4dbb-9818-c75cf2a13fd6', '2026-11-19 12:31:22.48415-03', '2026-11-19 12:31:22.48415-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 891, "altText": "Jardín nevado", "imageSrc": "assets/images/contra/gigante_jardin_nevado.png", "isContradiction": true, "imageDescription": "Un jardín cubierto de nieve, sin flores, con niños abrazándose de frío."}, {"id": 892, "altText": "Duraznos en flor", "imageSrc": "assets/images/contra/gigante_duraznos_flor.png", "isContradiction": false, "imageDescription": "Varios árboles de durazno cubiertos de flores rosadas."}, {"id": 893, "altText": "Niños entrando por el muro", "imageSrc": "assets/images/contra/gigante_ninos_agujero.png", "isContradiction": false, "imageDescription": "Un grupo de niños entrando al jardín por un agujero del muro de piedra."}, {"id": 894, "altText": "Pájaros cantando", "imageSrc": "assets/images/contra/gigante_pajaros_rama.png", "isContradiction": false, "imageDescription": "Tres pájaros pequeños cantando en una rama florecida."}], "explanation": "La imagen contradictoria muestra el jardín cubierto de nieve, sin flores, con niños tiritando.", "premiseText": "Cuando los niños volvieron, el jardín se llenó de flores y de pájaros cantores."}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('a1df1fd3-5478-45d4-99ac-999aa5e61457', '2026-11-19 12:31:22.536915-03', '2026-11-19 12:31:22.536915-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Una cesta de paja", "La rueca con oro", "Un telar", "Un baúl", "Un arpa"], "imageSrc": "assets/images/pixelado/rumpel_rueca_oro.png", "correctCharacter": "La rueca con oro", "imageDescription": "Una rueca de madera con un montón de hilos de oro brillante enrollados en ella, en una habitación de piedra."}], "total_time": 7}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('70713580-513a-4563-b20e-e5aaea59533d', '2026-11-19 12:31:22.485184-03', '2026-11-19 12:31:22.485184-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "El muro del gigante", "fragments": [{"id": 1, "text": "Los niños juegan cada tarde en el hermoso jardín del gigante."}, {"id": 2, "text": "El gigante regresa tras siete años y los echa de su jardín."}, {"id": 3, "text": "Construye un alto muro y coloca un cartel de prohibida la entrada."}, {"id": 4, "text": "La primavera se olvida del jardín y solo llegan la nieve y la escarcha."}, {"id": 5, "text": "Los niños, tristes, rondan el muro porque no tienen dónde jugar."}]}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('48c60fe2-0dd3-428c-a5f3-26f19bd8f05a', '2026-11-19 12:31:22.48615-03', '2026-11-19 12:31:22.48615-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "La primavera vuelve", "fragments": [{"id": 1, "text": "Una mañana, el gigante oye cantar a un pajarillo y mira por la ventana."}, {"id": 2, "text": "Los niños han entrado por un agujero del muro y los árboles florecen."}, {"id": 3, "text": "En un rincón sigue el invierno: un niño pequeño no puede subir al árbol."}, {"id": 4, "text": "El gigante lo ayuda a subir y derriba el muro."}, {"id": 5, "text": "Los niños juegan con el gigante todos los días."}]}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
