INSERT INTO public.games_bookminigame VALUES ('82fc0ac4-2e64-4e2e-8aa5-8395eeedb477', '2026-11-19 12:31:22.490389-03', '2026-11-19 12:31:22.490389-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El jardín de los niños", "imageUrl": "assets/images/testigo/gigante_jardin_primavera.png", "questions": [{"prompt": "¿De qué color eran las flores de los duraznos?", "options": ["Rojas", "Blancas", "Rosadas", "Amarillas"], "correctOption": "Rosadas"}, {"prompt": "¿Cuántos pájaros azules había en la rama?", "options": ["Tres", "Uno", "Dos", "Cinco"], "correctOption": "Dos"}, {"prompt": "¿Qué había bajo los árboles?", "options": ["Una fuente", "Un banco de madera", "Una casa", "Un columpio"], "correctOption": "Un banco de madera"}], "imageDescription": "Jardín soleado con césped suave; árboles de durazno con flores rosadas; seis niños jugando; dos pájaros azules en una rama; un banco de madera bajo los árboles."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('fb5146f9-1ab5-45b2-bcda-0c5c87d76961', '2026-11-19 12:31:22.491387-03', '2026-11-19 12:31:22.491387-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El muro del gigante", "imageUrl": "assets/images/testigo/gigante_muro_nieve.png", "questions": [{"prompt": "¿Qué dibujo tenía el cartel?", "options": ["Un corazón", "Una flor", "Una mano alzada", "Una estrella"], "correctOption": "Una mano alzada"}, {"prompt": "¿De qué color era la bufanda del niño?", "options": ["Roja", "Amarilla", "Verde", "Azul"], "correctOption": "Roja"}, {"prompt": "¿Cuántos árboles sin hojas había?", "options": ["Seis", "Uno", "Tres", "Cuatro"], "correctOption": "Tres"}], "imageDescription": "Un muro alto de piedra gris alrededor de un jardín cubierto de nieve; un cartel de madera con una mano alzada dibujada; tres árboles sin hojas; un niño pequeño con bufanda roja asomado por un agujero del muro."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('355c990f-0c82-4b02-892c-b530a052bacb', '2026-11-19 12:31:22.49237-03', '2026-11-19 12:31:22.49237-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Pajarillo cantor", "imageUrl": "assets/images/cazador-intrusos/pajarillo.png", "isIntruder": false, "imageDescription": "Pajarillo pequeño y azul con el pico abierto, cantando, fondo transparente."}, {"id": "item-2", "name": "Flores", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-3", "name": "Árbol de durazno en flor", "imageUrl": "assets/images/cazador-intrusos/durazno-flor.png", "isIntruder": false, "imageDescription": "Pequeño duraznero con flores rosadas, fondo transparente."}, {"id": "item-4", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-5", "name": "Mariposa", "imageUrl": "assets/images/cazador-intrusos/mariposa.png", "isIntruder": false}, {"id": "item-6", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}], "title": "El jardín primaveral", "bgImageUrl": "assets/images/cazador-intrusos/gigante-primavera-bg.jpg", "textDescription": "En el jardín del gigante florecían duraznos y flores, revoloteaban las mariposas y cantaba un pajarillo.", "bgImageDescription": "Jardín soleado con césped verde suave y cielo azul; espacio libre para 6 objetos."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('18480b69-ae6a-4ade-94b6-536aedcc665f', '2026-11-19 12:31:22.493369-03', '2026-11-19 12:31:22.493369-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Copo de nieve", "imageUrl": "assets/images/cazador-intrusos/copo-nieve.png", "isIntruder": false, "imageDescription": "Gran copo de nieve de cristal con seis puntas, fondo transparente."}, {"id": "item-2", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-3", "name": "Ladrillos del muro", "imageUrl": "assets/images/cazador-intrusos/ladrillos.png", "isIntruder": false}, {"id": "item-4", "name": "Cartel de prohibido", "imageUrl": "assets/images/cazador-intrusos/cartel-prohibido.png", "isIntruder": false, "imageDescription": "Cartel de madera con una mano alzada dibujada, fondo transparente."}, {"id": "item-5", "name": "Extintor de incendios", "imageUrl": "assets/images/cazador-intrusos/extintor-incendios.png", "isIntruder": true}, {"id": "item-6", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}], "title": "El jardín del invierno", "bgImageUrl": "assets/images/cazador-intrusos/gigante-invierno-bg.jpg", "textDescription": "Tras el muro de ladrillos, el jardín quedó cubierto de copos de nieve y con un cartel de prohibido.", "bgImageDescription": "Jardín cubierto de nieve con árboles sin hojas y cielo gris; espacio libre para 6 objetos."}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('44bb5a1f-48b7-454d-85af-a6e520727373', '2026-11-19 12:31:22.495372-03', '2026-11-19 12:31:22.495372-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/gigante-durazno-busca.jpg", "storyTitle": "El gigante egoísta", "targetArea": {"top": 20, "left": 48, "width": 40, "height": 37.5}, "textSnippet": "En la rama más baja del durazno, un pajarillo cantaba entre las flores rosadas.", "imageDescription": "Jardín en primavera con un gran duraznero florecido. En la parte central-derecha, un pajarillo azul grande posado en una rama, con un color apagado que lo distingue de las flores. Escena muy recargada: el jardín está lleno de flores de durazno, otros pájaros, niños jugando, mariposas, hojas y ramas.", "targetObjectName": "Pajarillo"}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('969446df-2f69-471e-b02b-2f9f5bb11076', '2026-11-19 12:31:22.497371-03', '2026-11-19 12:31:22.497371-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "El muro", "panels": [{"id": 1, "image": "assets/images/comics/gigante1.png", "imageDescription": "Los niños juegan felices entre árboles de durazno en flor."}, {"id": 2, "image": "assets/images/comics/gigante2.png", "imageDescription": "El gigante regresa y mira con enojo a los niños."}, {"id": 3, "image": "assets/images/comics/gigante3.png", "imageDescription": "El gigante construye un muro alto con piedras."}, {"id": 4, "image": "assets/images/comics/gigante4.png", "imageDescription": "El gigante clava un cartel con una mano alzada en el portón, mientras la nieve cubre el jardín."}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('4a320ba5-18cc-482c-be2e-14140eecbef2', '2026-11-19 12:31:22.49837-03', '2026-11-19 12:31:22.49837-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La primavera", "panels": [{"id": 1, "image": "assets/images/comics/gigante5.png", "imageDescription": "Los niños entran por un agujero del muro y los árboles florecen."}, {"id": 2, "image": "assets/images/comics/gigante6.png", "imageDescription": "En un rincón nevado, un niño pequeño llora junto a un árbol sin flores."}, {"id": 3, "image": "assets/images/comics/gigante7.png", "imageDescription": "El gigante, conmovido, ayuda al niño a subir al árbol."}, {"id": 4, "image": "assets/images/comics/gigante8.png", "imageDescription": "El gigante derriba el muro y juega con los niños."}]}', 'fdc9bdb8-86a1-4715-bfe3-29958da559f6', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('1696bdf3-9786-44da-8379-4573e83e6264', '2026-11-19 12:31:22.5024-03', '2026-11-19 12:31:22.5024-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El estudiante necesitaba una rosa roja.", "isTrue": true}, {"text": "La joven le pidió una rosa amarilla.", "isTrue": false}, {"text": "En su jardín no había rosas rojas.", "isTrue": true}], "passage_text": "Un joven estudiante lloraba porque la hija del profesor le había dicho que bailaría con él solo si le llevaba una rosa roja. Pero en su jardín no había ninguna rosa roja.", "time_per_statement": 7}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('dacb1e73-e429-4940-b1bd-4bf395a445c7', '2026-11-19 12:31:22.50337-03', '2026-11-19 12:31:22.50337-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El ruiseñor debía cantar toda la noche.", "isTrue": true}, {"text": "Apoyaría su pecho en una espina.", "isTrue": true}, {"text": "Bastaba con regar el rosal con agua.", "isTrue": false}], "passage_text": "El ruiseñor entendió que el estudiante estaba enamorado de verdad. Para crear una rosa roja, debía cantar toda la noche con el pecho apoyado en una espina.", "time_per_statement": 7}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('9c058c3a-f895-4ca9-88ab-cb6bf44a9cb2', '2026-11-19 12:31:22.504371-03', '2026-11-19 12:31:22.504371-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Qué felices estamos esta noche!", "isCorrect": false}, {"text": "¡Tengo muchas rosas rojas para bailar!", "isCorrect": false}, {"text": "¡No hay ninguna rosa roja en todo mi jardín!", "isCorrect": true}, {"text": "¡Mañana iré a pescar al río!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/ruisenor_estudiante_llora.png", "imageDescription": "Un joven estudiante sentado bajo un roble, con un libro cerrado y lágrimas en las mejillas, de noche, junto a un rosal sin flores."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('91197f7f-1e04-4b30-9c41-55366cd1d52a', '2026-11-19 12:31:22.505754-03', '2026-11-19 12:31:22.505754-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Esta noche me iré a dormir temprano!", "isCorrect": false}, {"text": "¡Qué rico sabor tiene esta espina!", "isCorrect": false}, {"text": "¡Prefiero volar al mar y descansar!", "isCorrect": false}, {"text": "¡Cantaré toda la noche por el amor verdadero!", "isCorrect": true}], "emotionImage": "assets/images/emoticono/ruisenor_canta_espina.png", "imageDescription": "Un ruiseñor pequeño y marrón posado en un rosal con el pecho apoyado en una espina, cantando bajo la luna, con una rosa que empieza a enrojecer."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('1c4baa79-8488-4015-80ed-ebbcc13a8167', '2026-11-19 12:31:22.506762-03', '2026-11-19 12:31:22.506762-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Un gorrión", "El ruiseñor", "Un colibrí", "Un canario", "Un mirlo"], "imageSrc": "assets/images/pixelado/ruisenor_ave.png", "correctCharacter": "El ruiseñor", "imageDescription": "Un ruiseñor pequeño de plumaje marrón y pecho claro, posado en la rama de un rosal, con el pico abierto."}], "total_time": 7}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('711d2f25-3eab-447c-99ac-a00e0633d358', '2026-11-19 12:31:22.508762-03', '2026-11-19 12:31:22.508762-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["La rosa roja", "Un rubí", "Una amapola", "Un clavel blanco", "Un tulipán"], "imageSrc": "assets/images/pixelado/ruisenor_rosa_roja.png", "correctCharacter": "La rosa roja", "imageDescription": "Una rosa roja intensa, recién abierta, con gotas de rocío y un tallo con espinas, sobre fondo oscuro."}], "total_time": 7}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('dc49a36d-6384-4a9a-b177-5c6308421bfe', '2026-11-19 12:31:22.510763-03', '2026-11-19 12:31:22.510763-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 901, "altText": "Espina bajo la luna", "imageSrc": "assets/images/contra/ruisenor_espina_luna.png", "isContradiction": false, "imageDescription": "Primer plano de una espina larga de rosal con la luna llena al fondo."}, {"id": 902, "altText": "Ruiseñor sobre el rosal", "imageSrc": "assets/images/contra/ruisenor_ave_rosal.png", "isContradiction": false, "imageDescription": "Un ruiseñor posado en un rosal de espinas bajo la luz de la luna."}, {"id": 903, "altText": "Ruiseñor cantando", "imageSrc": "assets/images/contra/ruisenor_canta_luna.png", "isContradiction": false, "imageDescription": "Un ruiseñor con el pico abierto cantando bajo la luna llena."}, {"id": 904, "altText": "Ruiseñor durmiendo en su nido", "imageSrc": "assets/images/contra/ruisenor_nido_dormido.png", "isContradiction": true, "imageDescription": "Un ruiseñor durmiendo tranquilo en un nido en lo alto de un árbol, lejos del rosal."}], "explanation": "La imagen contradictoria muestra al ruiseñor durmiendo tranquilo en un nido, lejos del rosal.", "premiseText": "El ruiseñor apoyó su pecho contra una espina del rosal y cantó toda la noche."}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('227c93a5-7319-4cae-be58-c200ee0e2b23', '2026-11-19 12:31:22.560984-03', '2026-11-19 12:31:22.560984-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Hoy no cocinamos nada!", "isCorrect": false}, {"text": "¡Alguien ha estado probando mi avena!", "isCorrect": true}, {"text": "¡Alguien ha cantado en mi jardín!", "isCorrect": false}, {"text": "¡Qué linda sorpresa, hay una invitada!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/ricitos_oso_enojado.png", "imageDescription": "Papá Oso, grande y de pelaje marrón, de pie en su casa, mirando con asombro y enojo su tazón de avena movido sobre la mesa, con Mamá Osa y el Osito detrás."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('ee003d0d-439c-4f69-8c7b-059dba85c2ed', '2026-11-19 12:31:22.562984-03', '2026-11-19 12:31:22.562984-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Gretel", "Caperucita Roja", "Blancanieves", "Ricitos de Oro", "Hansel"], "imageSrc": "assets/images/pixelado/ricitos_personaje.png", "correctCharacter": "Ricitos de Oro", "imageDescription": "Ricitos de Oro, una niña de cabello rizado y dorado con vestido azul y delantal blanco, de pie en el bosque."}], "total_time": 7}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('d61f0844-b8a7-4540-8aab-e9d021b6cb83', '2026-11-19 12:31:22.510763-03', '2026-11-19 12:31:22.510763-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 911, "altText": "Sobrino del chambelán", "imageSrc": "assets/images/contra/ruisenor_sobrino.png", "isContradiction": false, "imageDescription": "Un joven elegante con casaca dorada entregando un cofre de joyas a la joven."}, {"id": 912, "altText": "Estudiante con la rosa", "imageSrc": "assets/images/contra/ruisenor_estudiante_rosa.png", "isContradiction": false, "imageDescription": "El estudiante sosteniendo una rosa roja en la mano, con gesto esperanzado."}, {"id": 913, "altText": "Joven con joyas", "imageSrc": "assets/images/contra/ruisenor_joven_joyas.png", "isContradiction": false, "imageDescription": "Una joven con vestido azul mirando con interés un cofre abierto lleno de joyas."}, {"id": 914, "altText": "Joven abrazando la rosa", "imageSrc": "assets/images/contra/ruisenor_joven_abraza_rosa.png", "isContradiction": true, "imageDescription": "La joven abrazando contra el pecho una rosa roja, sonriendo con alegría."}], "explanation": "La imagen contradictoria muestra a la joven abrazando la rosa roja con alegría.", "premiseText": "La joven rechazó la rosa roja porque el sobrino del chambelán le había regalado joyas."}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('19f9192b-4d6a-4aa8-a79f-46cb00203bb3', '2026-11-19 12:31:22.512762-03', '2026-11-19 12:31:22.512762-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La búsqueda de la rosa", "fragments": [{"id": 1, "text": "El estudiante se lamenta porque no tiene una rosa roja para la joven que ama."}, {"id": 2, "text": "El ruiseñor escucha y decide ayudarlo, pues cree en el amor verdadero."}, {"id": 3, "text": "Visita primero un rosal blanco y luego uno amarillo, pero ninguno da rosas rojas."}, {"id": 4, "text": "El rosal junto a la ventana le dice que solo puede lograrlo cantando toda la noche sobre una espina."}, {"id": 5, "text": "El ruiseñor canta apoyado en la espina hasta que la rosa se vuelve roja."}]}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('bdeead87-dd1e-4c9f-865a-9c6be15de53f', '2026-11-19 12:31:22.513854-03', '2026-11-19 12:31:22.513854-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El final", "fragments": [{"id": 1, "text": "Al amanecer, el ruiseñor muere y la rosa roja florece."}, {"id": 2, "text": "El estudiante encuentra la rosa y corre a llevársela a la joven."}, {"id": 3, "text": "La joven rechaza la rosa porque prefiere las joyas del sobrino del chambelán."}, {"id": 4, "text": "El estudiante arroja la rosa a la calle y un carro pasa sobre ella."}, {"id": 5, "text": "El estudiante vuelve a sus libros diciendo que el amor es una tontería."}]}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('172cb530-24f2-40cc-a9b8-276d2d350509', '2026-11-19 12:31:22.515762-03', '2026-11-19 12:31:22.515762-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["rama", "hoja", "piedra", "espina"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "El ruiseñor debía cantar toda la noche con el pecho apoyado en una", "correctWord": "espina"}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('04f11618-0c26-4e3f-b717-88cdeabc8d47', '2026-11-19 12:31:22.516765-03', '2026-11-19 12:31:22.516765-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["amarilla", "roja", "rosada", "blanca"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "La joven prefirió unas joyas a la rosa", "correctWord": "roja"}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('9779a99a-6769-4741-9e7f-24d9eb9af1aa', '2026-11-19 12:31:22.518786-03', '2026-11-19 12:31:22.518786-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "El rosal", "imageUrl": "assets/images/testigo/ruisenor_jardin_noche.png", "questions": [{"prompt": "¿Cuántos rosales había?", "options": ["Uno", "Cinco", "Tres", "Dos"], "correctOption": "Tres"}, {"prompt": "¿De qué color eran las rosas del rosal de la izquierda?", "options": ["Azules", "Rosadas", "Blancas", "Rojas"], "correctOption": "Blancas"}, {"prompt": "¿Qué había en el jardín además de los rosales?", "options": ["Un columpio", "Un estanque con patos", "Un invernadero", "Una fuente de piedra"], "correctOption": "Una fuente de piedra"}], "imageDescription": "Jardín de noche con tres rosales: el de la izquierda con rosas blancas, el del centro con rosas amarillas y el de la derecha, junto a una ventana, sin flores; luna llena; un ruiseñor pequeño sobre una rama; una fuente de piedra."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('be008f51-568d-49f9-b521-7983d021e7de', '2026-11-19 12:31:22.518786-03', '2026-11-19 12:31:22.518786-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La ventana del estudiante", "imageUrl": "assets/images/testigo/ruisenor_escritorio.png", "questions": [{"prompt": "¿De qué color era el jersey del estudiante?", "options": ["Azul", "Gris", "Verde", "Rojo"], "correctOption": "Verde"}, {"prompt": "¿Qué había sobre el escritorio además de libros?", "options": ["Una vela", "Una lámpara eléctrica", "Un reloj", "Una taza de té"], "correctOption": "Una vela"}, {"prompt": "¿Qué animal dormía en la silla?", "options": ["Un gato", "Un loro", "Un perro", "Un conejo"], "correctOption": "Un gato"}], "imageDescription": "Un estudiante joven con jersey verde sentado en un escritorio con libros apilados; una vela encendida; por la ventana se ve el rosal con una rosa roja brillante; una pluma sobre un cuaderno; un gato dormido en una silla."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('bcec32f0-0f64-4fdf-bd91-7d27518565c8', '2026-11-19 12:31:22.520761-03', '2026-11-19 12:31:22.520761-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Flores", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-2", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-3", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-4", "name": "Ruiseñor", "imageUrl": "assets/images/cazador-intrusos/ruisenor.png", "isIntruder": false, "imageDescription": "Ruiseñor pequeño marrón posado, de perfil, fondo transparente."}, {"id": "item-5", "name": "Rosal con espinas", "imageUrl": "assets/images/cazador-intrusos/rosal-espinas.png", "isIntruder": false}, {"id": "item-6", "name": "Rosa roja", "imageUrl": "assets/images/cazador-intrusos/rosa-roja.png", "isIntruder": false, "imageDescription": "Rosa roja intensa con tallo y dos hojas, fondo transparente."}], "title": "El jardín del rosal", "bgImageUrl": "assets/images/cazador-intrusos/ruisenor-jardin-bg.jpg", "textDescription": "Bajo la luna, el jardín tenía flores, un rosal con espinas, una rosa roja y un ruiseñor que cantaba.", "bgImageDescription": "Jardín de noche con luna llena, pasto oscuro y un camino de piedra; espacio libre para 6 objetos."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('bcd9eecd-5364-4665-9bf1-568b98c768c4', '2026-11-19 12:31:22.562984-03', '2026-11-19 12:31:22.562984-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un oso polar", "Un panda", "Papá Oso", "El Osito", "Mamá Osa"], "imageSrc": "assets/images/pixelado/ricitos_osito.png", "correctCharacter": "El Osito", "imageDescription": "El Osito, un osito pequeño de pelaje marrón claro con un delantal azul, sentado en una silla pequeña."}], "total_time": 7}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('c3506b03-6be1-4a0d-8636-923c3537a3d3', '2026-11-19 12:31:22.521816-03', '2026-11-19 12:31:22.521816-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-2", "name": "Pluma y tintero", "imageUrl": "assets/images/cazador-intrusos/pluma-tintero.png", "isIntruder": false, "imageDescription": "Pluma de ave dentro de un tintero de cristal, fondo transparente."}, {"id": "item-3", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}, {"id": "item-4", "name": "Libro antiguo", "imageUrl": "assets/images/cazador-intrusos/libro-antiguo.png", "isIntruder": false, "imageDescription": "Libro antiguo de tapa de cuero marrón, fondo transparente."}, {"id": "item-5", "name": "Vela encendida", "imageUrl": "assets/images/cazador-intrusos/vela.png", "isIntruder": false}, {"id": "item-6", "name": "Calculadora solar", "imageUrl": "assets/images/cazador-intrusos/calculadora.png", "isIntruder": true}], "title": "El estudio del estudiante", "bgImageUrl": "assets/images/cazador-intrusos/ruisenor-estudio-bg.jpg", "textDescription": "En el escritorio del estudiante había una vela, un libro antiguo y una pluma con tintero.", "bgImageDescription": "Habitación de estudiante con una ventana grande de noche y una mesa de madera; espacio libre para 6 objetos."}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('8b440208-a11a-434b-a9f7-73dd0fcf7cba', '2026-11-19 12:31:22.523801-03', '2026-11-19 12:31:22.523801-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/ruisenor-rosal-busca.jpg", "storyTitle": "El ruiseñor y la rosa", "targetArea": {"top": 8, "left": 52, "width": 40, "height": 37.5}, "textSnippet": "Sobre la rama más alta del rosal, el pequeño ruiseñor cantaba bajo la luz de la luna.", "imageDescription": "Jardín de noche con un rosal alto y luna llena. En la parte superior derecha, un ruiseñor marrón grande posado en la rama más alta, con un contorno de luz suave. Escena muy recargada: el rosal está lleno de rosas blancas y amarillas, hojas, espinas, otros pájaros, estrellas y luciérnagas.", "targetObjectName": "Ruiseñor"}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('f40c0598-4971-4892-bed0-a29fb4dcb26b', '2026-11-19 12:31:22.524762-03', '2026-11-19 12:31:22.524762-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/ruisenor-calle-busca.jpg", "storyTitle": "El ruiseñor y la rosa", "targetArea": {"top": 65, "left": 30, "width": 50, "height": 20}, "textSnippet": "En el empedrado de la calle, aplastada por la rueda de un carro, yacía una rosa roja.", "imageDescription": "Calle empedrada con un carro a lo lejos. En la parte inferior, una rosa roja aplastada sobre las piedras, con un rojo apagado que destaca levemente del empedrado.", "targetObjectName": "Rosa roja aplastada"}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('0de8cef5-2ee6-4a4f-8c6b-aab31139823c', '2026-11-19 12:31:22.525884-03', '2026-11-19 12:31:22.525884-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La promesa del baile", "panels": [{"id": 1, "image": "assets/images/comics/ruisenor1.png", "imageDescription": "Un estudiante lee un libro mientras la hija del profesor le habla desde un balcón."}, {"id": 2, "image": "assets/images/comics/ruisenor2.png", "imageDescription": "El estudiante llora junto a un rosal sin rosas rojas."}, {"id": 3, "image": "assets/images/comics/ruisenor3.png", "imageDescription": "Un ruiseñor lo escucha desde una rama y se conmueve."}, {"id": 4, "image": "assets/images/comics/ruisenor4.png", "imageDescription": "El ruiseñor vuela hacia otros rosales para buscar una rosa roja."}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('7fb36dbb-32d2-47c2-831f-091b4553d43f', '2026-11-19 12:31:22.526894-03', '2026-11-19 12:31:22.526894-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La rosa roja", "panels": [{"id": 1, "image": "assets/images/comics/ruisenor5.png", "imageDescription": "El ruiseñor canta con el pecho en una espina de un rosal, bajo la luna."}, {"id": 2, "image": "assets/images/comics/ruisenor6.png", "imageDescription": "Al amanecer, una rosa roja brilla en el rosal y el ruiseñor yace en la hierba."}, {"id": 3, "image": "assets/images/comics/ruisenor7.png", "imageDescription": "El estudiante arranca la rosa y corre a la casa de la joven."}, {"id": 4, "image": "assets/images/comics/ruisenor8.png", "imageDescription": "La joven rechaza la rosa con gesto de desdén y el estudiante la tira a la calle."}]}', '4e9bbbf3-54f4-454d-ab79-7e6e98d71617', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('9552e62b-f025-4450-b8d2-76ba654603d3', '2026-11-19 12:31:22.530892-03', '2026-11-19 12:31:22.530892-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El molinero dijo que su hija hilaba oro.", "isTrue": true}, {"text": "El rey la encerró en un jardín.", "isTrue": false}, {"text": "La habitación estaba llena de paja.", "isTrue": true}], "passage_text": "Un molinero presumió ante el rey de que su hija podía convertir la paja en oro. El rey la encerró en una habitación llena de paja y le ordenó hilar oro antes de la mañana.", "time_per_statement": 7}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('35872653-6c05-4625-aa3d-59a00be43d1d', '2026-11-19 12:31:22.531925-03', '2026-11-19 12:31:22.531925-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "Primero recibió un collar.", "isTrue": true}, {"text": "La tercera noche pidió su primer hijo.", "isTrue": true}, {"text": "Siempre pidió dinero a cambio.", "isTrue": false}], "passage_text": "Un hombrecillo apareció y hiló la paja en oro a cambio de un collar. La segunda noche pidió un anillo y, la tercera noche, pidió su primer hijo.", "time_per_statement": 7}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('e9604810-9eb6-4732-bab3-cf99acf87a15', '2026-11-19 12:31:22.532893-03', '2026-11-19 12:31:22.532893-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¿Cómo convertiré toda esta paja en oro?", "isCorrect": true}, {"text": "¡Hilaré esta lana con mucha facilidad!", "isCorrect": false}, {"text": "¡Qué rica es la comida de palacio!", "isCorrect": false}, {"text": "¡Qué linda es esta habitación de flores!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/rumpel_molinera_llora.png", "imageDescription": "Una joven sentada en el suelo de una habitación llena de paja, junto a una rueca de hilar, llorando, con una pequeña ventana al fondo."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('08d1c5a9-d2c5-4b58-9aa5-35d503ac5968', '2026-11-19 12:31:22.533892-03', '2026-11-19 12:31:22.533892-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Nunca he bailado en mi vida!", "isCorrect": false}, {"text": "¡Qué bueno que nadie sabe que me llamo Rumpelstiltskin!", "isCorrect": true}, {"text": "¡Voy a regalar mi oro a todos los niños!", "isCorrect": false}, {"text": "¡Mi nombre es Pedro y vivo en el pueblo!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/rumpel_hombrecillo_baila.png", "imageDescription": "Un hombrecillo de nariz larga y gorro puntiagudo, bailando alrededor de una fogata en el bosque y cantando con alegría."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('44b31fe6-7cd6-4e39-abfd-5e3222c124a4', '2026-11-19 12:31:22.535893-03', '2026-11-19 12:31:22.535893-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Un mago", "El rey", "El molinero", "Rumpelstiltskin", "Un duende del bosque"], "imageSrc": "assets/images/pixelado/rumpel_personaje.png", "correctCharacter": "Rumpelstiltskin", "imageDescription": "Rumpelstiltskin, un hombrecillo de barba gris, nariz larga, gorro puntiagudo rojo y ropa vieja, sentado junto a una rueca."}], "total_time": 7}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('faa21144-d5ae-43d8-8638-136bdcccc8fc', '2026-11-19 12:31:22.537893-03', '2026-11-19 12:31:22.537893-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 921, "altText": "Hombrecillo hilando", "imageSrc": "assets/images/contra/rumpel_hombrecillo_hila.png", "isContradiction": false, "imageDescription": "Un hombrecillo de gorro rojo hilando junto a una rueca en una habitación con paja."}, {"id": 922, "altText": "Paja convertida en nieve", "imageSrc": "assets/images/contra/rumpel_paja_nieve.png", "isContradiction": true, "imageDescription": "Un hombrecillo hilando junto a una rueca y convirtiendo la paja en bolas de nieve."}, {"id": 923, "altText": "Carretes de oro", "imageSrc": "assets/images/contra/rumpel_carretes_oro.png", "isContradiction": false, "imageDescription": "Tres carretes de hilo de oro brillante sobre una mesa de madera."}, {"id": 924, "altText": "Paja y oro", "imageSrc": "assets/images/contra/rumpel_paja_y_oro.png", "isContradiction": false, "imageDescription": "Una habitación con paja amontonada en una esquina y carretes de oro apilados en la otra."}], "explanation": "La imagen contradictoria muestra al hombrecillo convirtiendo la paja en bolas de nieve.", "premiseText": "El hombrecillo hilaba la paja y la convertía en brillante oro."}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('cd232794-6351-4e49-883c-6a81d18d13a3', '2026-11-19 12:31:22.538892-03', '2026-11-19 12:31:22.538892-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 931, "altText": "Reina frente al hombrecillo", "imageSrc": "assets/images/contra/rumpel_reina_hombrecillo.png", "isContradiction": false, "imageDescription": "La reina con corona y su bebé en brazos, de pie frente al hombrecillo en una sala del castillo."}, {"id": 932, "altText": "Reina entregando al bebé", "imageSrc": "assets/images/contra/rumpel_reina_entrega_bebe.png", "isContradiction": true, "imageDescription": "La reina sonriendo y entregando al bebé al hombrecillo en una sala del castillo."}, {"id": 933, "altText": "Mensajero espiando", "imageSrc": "assets/images/contra/rumpel_mensajero_arbol.png", "isContradiction": false, "imageDescription": "Un mensajero con sombrero emplumado escondido tras un árbol, mirando hacia una fogata."}, {"id": 934, "altText": "Hombrecillo bailando", "imageSrc": "assets/images/contra/rumpel_baila_fogata.png", "isContradiction": false, "imageDescription": "Un hombrecillo bailando alrededor de una fogata en un claro del bosque de noche."}], "explanation": "La imagen contradictoria muestra a la reina entregando al bebé al hombrecillo con una sonrisa.", "premiseText": "La reina pudo salvar a su hijo adivinando el nombre del hombrecillo."}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('d09fd51f-a4e1-46cf-9544-bc8ea85c3530', '2026-11-19 12:31:22.540893-03', '2026-11-19 12:31:22.540893-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La paja y el oro", "fragments": [{"id": 1, "text": "Un molinero presume que su hija puede convertir la paja en oro."}, {"id": 2, "text": "El rey encierra a la joven en una habitación con paja y le exige hilar oro."}, {"id": 3, "text": "Un hombrecillo aparece y hila el oro a cambio de su collar."}, {"id": 4, "text": "La segunda noche, el hombrecillo vuelve y se lleva su anillo."}, {"id": 5, "text": "La tercera noche, la joven promete su primer hijo y el rey se casa con ella."}]}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('ae7dccd4-98c8-439f-9d8e-cdd21d3916bd', '2026-11-19 12:31:22.541975-03', '2026-11-19 12:31:22.541975-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El nombre secreto", "fragments": [{"id": 1, "text": "Cuando nace su hijo, la reina ve regresar al hombrecillo."}, {"id": 2, "text": "El hombrecillo le da tres días para adivinar su nombre."}, {"id": 3, "text": "La reina prueba con muchos nombres, pero ninguno es el correcto."}, {"id": 4, "text": "Un mensajero ve al hombrecillo bailando y cantando su nombre junto a una fogata."}, {"id": 5, "text": "La reina dice «Rumpelstiltskin» y el hombrecillo se va furioso."}]}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('1110edb1-fd47-4d65-a68d-12bf4a798202', '2026-11-19 12:31:22.542696-03', '2026-11-19 12:31:22.542696-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["plata", "pan", "oro", "hilo"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "El molinero presumió de que su hija podía convertir la paja en", "correctWord": "oro"}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('428e19eb-41f4-4976-a595-eca20245d2f7', '2026-11-19 12:31:22.544706-03', '2026-11-19 12:31:22.544706-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["cumpleaños", "nombre", "oficio", "país"], "timeLeft": 7.0, "textAfter": "del hombrecillo.", "textBefore": "Para quedarse con su hijo, la reina debía adivinar el", "correctWord": "nombre"}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('148555af-493e-4474-942c-ef7bb7c41c47', '2026-11-19 12:31:22.545707-03', '2026-11-19 12:31:22.545707-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La habitación de la paja", "imageUrl": "assets/images/testigo/rumpel_cuarto_paja.png", "questions": [{"prompt": "¿De qué color era el vestido de la joven?", "options": ["Rojo", "Blanco", "Verde", "Azul"], "correctOption": "Verde"}, {"prompt": "¿Cuántos carretes de oro había?", "options": ["Dos", "Cinco", "Uno", "Tres"], "correctOption": "Tres"}, {"prompt": "¿Qué tenía la ventana?", "options": ["Barrotes", "Un vidrio de colores", "Flores", "Cortinas rojas"], "correctOption": "Barrotes"}], "imageDescription": "Habitación de piedra con paja amontonada hasta el techo; una rueca de madera; una joven con vestido verde; una pequeña ventana con barrotes; tres carretes de oro sobre una mesa; una antorcha en la pared."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('f268b0b2-2129-4d36-ae04-e5d3439336cc', '2026-11-19 12:31:22.546706-03', '2026-11-19 12:31:22.546706-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La fogata del hombrecillo", "imageUrl": "assets/images/testigo/rumpel_bosque_fogata.png", "questions": [{"prompt": "¿De qué color era el gorro del hombrecillo?", "options": ["Azul", "Verde", "Negro", "Rojo"], "correctOption": "Rojo"}, {"prompt": "¿Qué hacía el mensajero?", "options": ["Bailaba también", "Cocinaba", "Se escondía tras un árbol", "Dormía junto al fuego"], "correctOption": "Se escondía tras un árbol"}, {"prompt": "¿Qué forma tenía la luna?", "options": ["Menguante", "Creciente", "Llena", "Nueva"], "correctOption": "Creciente"}], "imageDescription": "Claro del bosque de noche con una fogata; un hombrecillo con gorro puntiagudo rojo y barba gris bailando alrededor; un caldero; un mensajero con sombrero emplumado escondido tras un árbol; luna creciente."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('d81d9cb0-5824-43c6-bdfa-c829d06aadac', '2026-11-19 12:31:22.590579-03', '2026-11-19 12:31:22.590579-03', true, NULL, 'Desafío Emoticono Dialogo #2', '{"dialogues": [{"text": "¡Esta cama es demasiado pequeña!", "isCorrect": false}, {"text": "No pude dormir, había algo duro en mi cama.", "isCorrect": true}, {"text": "¡Dormí como un angelito toda la noche!", "isCorrect": false}, {"text": "¡Quiero más almohadas!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/guisante_princesa_cama.png", "imageDescription": "Una princesa en camisón sentada sobre una pila altísima de colchones, con cara de cansancio y algunas marcas moradas en los brazos, junto a la reina."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('4700e86a-7fef-4b77-94c5-a0a928dcdea2', '2026-11-19 12:31:22.548705-03', '2026-11-19 12:31:22.548705-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-2", "name": "Carrete de hilo de oro", "imageUrl": "assets/images/cazador-intrusos/hilo-dorado.png", "isIntruder": false}, {"id": "item-3", "name": "Paja", "imageUrl": "assets/images/cazador-intrusos/paja.png", "isIntruder": false}, {"id": "item-4", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-5", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-6", "name": "Rueca de hilar", "imageUrl": "assets/images/cazador-intrusos/rueca.png", "isIntruder": false, "imageDescription": "Rueca de madera antigua con rueda, fondo transparente."}], "title": "La habitación de la paja", "bgImageUrl": "assets/images/cazador-intrusos/rumpel-cuarto-bg.jpg", "textDescription": "En la habitación del rey había paja amontonada, una rueca de hilar y un carrete de hilo de oro.", "bgImageDescription": "Habitación de piedra con una pequeña ventana con barrotes y suelo de tierra; espacio libre para 6 objetos."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('cb8cb1b3-1dc5-4e63-9999-b01414f58fb6', '2026-11-19 12:31:22.549706-03', '2026-11-19 12:31:22.549706-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Audífonos inalámbricos", "imageUrl": "assets/images/cazador-intrusos/audifonos.png", "isIntruder": true}, {"id": "item-2", "name": "Calculadora solar", "imageUrl": "assets/images/cazador-intrusos/calculadora.png", "isIntruder": true}, {"id": "item-3", "name": "Radio a pilas", "imageUrl": "assets/images/cazador-intrusos/radio.png", "isIntruder": true}, {"id": "item-4", "name": "Collar", "imageUrl": "assets/images/cazador-intrusos/collar.png", "isIntruder": false, "imageDescription": "Collar de cuentas doradas con una piedra roja, fondo transparente."}, {"id": "item-5", "name": "Anillo", "imageUrl": "assets/images/cazador-intrusos/anillo.png", "isIntruder": false, "imageDescription": "Anillo dorado con una pequeña piedra azul, fondo transparente."}, {"id": "item-6", "name": "Consola de videojuegos", "imageUrl": "assets/images/cazador-intrusos/consola.png", "isIntruder": true}], "title": "El collar y el anillo", "bgImageUrl": "assets/images/cazador-intrusos/rumpel-pago-bg.jpg", "textDescription": "El hombrecillo recibió un collar y un anillo de la joven a cambio de hilar la paja en oro.", "bgImageDescription": "Mesa de madera en un cuarto de piedra, iluminada por una vela; espacio libre para 6 objetos."}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('a7e9aa60-7879-420d-83de-b3cb06def749', '2026-11-19 12:31:22.550737-03', '2026-11-19 12:31:22.550737-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/rumpel-cuarto-busca.jpg", "storyTitle": "Rumpelstiltskin", "targetArea": {"top": 45, "left": 8, "width": 30, "height": 50}, "textSnippet": "En un rincón de la habitación, bajo un gran montón de paja, esperaba la rueca de la joven molinera.", "imageDescription": "Habitación de piedra llena de paja. En la parte inferior izquierda, una rueca de madera grande entre la paja, de tono algo más oscuro y definido. Escena muy recargada: la habitación tiene paja amontonada, carretes de oro, cestas, taburetes, telas y otras ruecas pequeñas.", "targetObjectName": "Rueca"}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('4d7a83fe-3b49-4dba-a018-fdc64f2ea091', '2026-11-19 12:31:22.552737-03', '2026-11-19 12:31:22.552737-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/rumpel-fogata-busca.jpg", "storyTitle": "Rumpelstiltskin", "targetArea": {"top": 28, "left": 70, "width": 20, "height": 50}, "textSnippet": "Detrás de un tronco, el mensajero espiaba al hombrecillo que bailaba alrededor de la fogata.", "imageDescription": "Bosque de noche con una fogata en el centro. En la parte derecha, un mensajero con sombrero emplumado escondido tras un tronco, algo más iluminado que el bosque.", "targetObjectName": "Mensajero escondido"}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('177cb0bc-a8b0-4230-af21-eddd8ed08faa', '2026-11-19 12:31:22.553735-03', '2026-11-19 12:31:22.553735-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Paja y oro", "panels": [{"id": 1, "image": "assets/images/comics/rumpel1.png", "imageDescription": "El molinero habla con el rey y presume de su hija."}, {"id": 2, "image": "assets/images/comics/rumpel2.png", "imageDescription": "La joven llora en una habitación llena de paja."}, {"id": 3, "image": "assets/images/comics/rumpel3.png", "imageDescription": "Un hombrecillo aparece y hila la paja en un carrete de oro."}, {"id": 4, "image": "assets/images/comics/rumpel4.png", "imageDescription": "El rey ve la habitación llena de carretes de oro con gesto asombrado."}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('03f2b463-060d-46f9-8063-a7d5f53a1e49', '2026-11-19 12:31:22.554706-03', '2026-11-19 12:31:22.554706-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El nombre", "panels": [{"id": 1, "image": "assets/images/comics/rumpel5.png", "imageDescription": "La reina, con su bebé en brazos, ve aparecer al hombrecillo."}, {"id": 2, "image": "assets/images/comics/rumpel6.png", "imageDescription": "La reina escribe una larga lista de nombres junto a su mensajero."}, {"id": 3, "image": "assets/images/comics/rumpel7.png", "imageDescription": "El mensajero espía al hombrecillo bailando alrededor de la fogata."}, {"id": 4, "image": "assets/images/comics/rumpel8.png", "imageDescription": "La reina dice el nombre del hombrecillo y él patalea furioso."}]}', 'b18dca1e-e007-4663-98d2-a4d6e059f11f', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('edf4edd2-936f-4439-8b87-7c9fc0dab4ec', '2026-11-19 12:31:22.558705-03', '2026-11-19 12:31:22.558705-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "Los osos salieron a pasear.", "isTrue": true}, {"text": "Los osos prepararon helado.", "isTrue": false}, {"text": "Ricitos de Oro entró sin permiso.", "isTrue": true}], "passage_text": "Los tres osos prepararon avena y salieron a pasear mientras se enfriaba. Mientras tanto, Ricitos de Oro entró en su casa sin permiso.", "time_per_statement": 7}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c1650b4c-9221-4284-9e30-d242224aaf1f', '2026-11-19 12:31:22.55956-03', '2026-11-19 12:31:22.55956-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "El primer tazón estaba muy caliente.", "isTrue": true}, {"text": "El tercer tazón estaba muy frío.", "isTrue": false}, {"text": "Ricitos de Oro se comió el tercer tazón entero.", "isTrue": true}], "passage_text": "Ricitos de Oro probó tres tazones de avena. El primero estaba muy caliente, el segundo muy frío y el tercero justo bien, así que se lo comió todo.", "time_per_statement": 7}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('fa5431ce-e4a5-4982-8b3b-e7f6a82a956e', '2026-11-19 12:31:22.560984-03', '2026-11-19 12:31:22.560984-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Esta avena está justo como me gusta!", "isCorrect": true}, {"text": "¡No tengo hambre, me iré a casa!", "isCorrect": false}, {"text": "¡Esta avena está helada!", "isCorrect": false}, {"text": "¡Esta avena está demasiado caliente!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/ricitos_prueba_avena.png", "imageDescription": "Una niña de cabello rizado y dorado, con vestido azul y delantal, frente a una mesa con tres tazones de distintos tamaños, probando con una cuchara y con cara de gusto."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('135cb072-bb34-46cf-8b26-4a6118cc1847', '2026-11-19 12:31:22.564984-03', '2026-11-19 12:31:22.564984-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 941, "altText": "Ricitos probando el tazón pequeño", "imageSrc": "assets/images/contra/ricitos_prueba_pequeno.png", "isContradiction": false, "imageDescription": "Ricitos de Oro probando con una cuchara el tazón pequeño."}, {"id": 942, "altText": "Tres tazones de distinto tamaño", "imageSrc": "assets/images/contra/ricitos_tres_tazones.png", "isContradiction": false, "imageDescription": "Tres tazones de avena humeante, de tamaño grande, mediano y pequeño, sobre una mesa de madera."}, {"id": 943, "altText": "Tres cucharas", "imageSrc": "assets/images/contra/ricitos_tres_cucharas.png", "isContradiction": false, "imageDescription": "Tres cucharas de madera de distinto tamaño sobre una mesa."}, {"id": 944, "altText": "Ricitos con una pizza gigante", "imageSrc": "assets/images/contra/ricitos_pizza.png", "isContradiction": true, "imageDescription": "Ricitos de Oro de pie frente a una mesa con una pizza gigante."}], "explanation": "La imagen contradictoria muestra a Ricitos de Oro frente a una mesa con una pizza gigante.", "premiseText": "Ricitos de Oro encontró sobre la mesa tres tazones de avena: uno grande, uno mediano y uno pequeño."}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('4e87a853-9072-43d4-a848-43b7486d4fe7', '2026-11-19 12:31:22.566075-03', '2026-11-19 12:31:22.566075-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 951, "altText": "Ricitos dormida", "imageSrc": "assets/images/contra/ricitos_dormida_pequena.png", "isContradiction": false, "imageDescription": "Ricitos de Oro dormida en la cama más pequeña, con una colcha verde a rayas."}, {"id": 952, "altText": "Ricitos en una hamaca", "imageSrc": "assets/images/contra/ricitos_hamaca.png", "isContradiction": true, "imageDescription": "Ricitos de Oro durmiendo en una hamaca colgada entre dos árboles del bosque."}, {"id": 953, "altText": "Tres camas", "imageSrc": "assets/images/contra/ricitos_tres_camas.png", "isContradiction": false, "imageDescription": "Tres camas de distinto tamaño (grande, mediana y pequeña) en un dormitorio."}, {"id": 954, "altText": "Osos mirando", "imageSrc": "assets/images/contra/ricitos_osos_miran.png", "isContradiction": false, "imageDescription": "Los tres osos de pie junto a la cama pequeña, mirando a Ricitos dormida."}], "explanation": "La imagen contradictoria muestra a Ricitos de Oro durmiendo en una hamaca colgada de un árbol.", "premiseText": "Ricitos de Oro se quedó dormida en la camita pequeña del Osito."}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('dafd3ead-9008-493c-86c6-03bda6cef4f8', '2026-11-19 12:31:22.567984-03', '2026-11-19 12:31:22.567984-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La casa de los osos", "fragments": [{"id": 1, "text": "Los tres osos dejan sus tazones de avena enfriándose y salen a pasear."}, {"id": 2, "text": "Ricitos de Oro llega a la casa y entra sin pedir permiso."}, {"id": 3, "text": "Prueba tres tazones y se come la avena del Osito."}, {"id": 4, "text": "Se sienta en tres sillas y rompe la sillita del Osito."}, {"id": 5, "text": "Sube a la habitación y se queda dormida en la camita del Osito."}]}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('71bccaa0-964d-4d6f-ab6a-31798d6b9f8a', '2026-11-19 12:31:22.569075-03', '2026-11-19 12:31:22.569075-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El regreso de los osos", "fragments": [{"id": 1, "text": "Los osos regresan y notan que sus tazones han sido tocados."}, {"id": 2, "text": "Papá Oso ve que alguien ha movido su silla."}, {"id": 3, "text": "El Osito encuentra su sillita rota."}, {"id": 4, "text": "Los osos suben y descubren a Ricitos de Oro dormida en la camita."}, {"id": 5, "text": "Ricitos de Oro despierta, salta por la ventana y escapa corriendo."}]}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('3a2f9df5-4399-4351-b406-dd32258043dd', '2026-11-19 12:31:22.569982-03', '2026-11-19 12:31:22.569982-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["avena", "pastel", "pan", "jugo"], "timeLeft": 7.0, "textAfter": "! —gruñó Papá Oso.", "textBefore": "—¡Alguien ha probado mi", "correctWord": "avena"}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('57fadbaa-18fa-4f7b-8699-54f4437a5625', '2026-11-19 12:31:22.570984-03', '2026-11-19 12:31:22.570984-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["amarga", "quemada", "perfecta", "helada"], "timeLeft": 7.0, "textAfter": ".", "textBefore": "La avena del tercer tazón no estaba ni muy caliente ni muy fría, estaba", "correctWord": "perfecta"}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('34eec912-acb6-4c6e-8ed3-9c93c1d20f6a', '2026-11-19 12:31:22.572984-03', '2026-11-19 12:31:22.572984-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La mesa de los osos", "imageUrl": "assets/images/testigo/ricitos_mesa_osos.png", "questions": [{"prompt": "¿De qué color era el tazón pequeño?", "options": ["Azul", "Verde", "Rojo", "Amarillo"], "correctOption": "Amarillo"}, {"prompt": "¿Cuántas sillas había?", "options": ["Tres", "Seis", "Dos", "Cuatro"], "correctOption": "Tres"}, {"prompt": "¿Qué había colgado en la pared?", "options": ["Un espejo", "Una estantería", "Un cuadro de flores", "Un reloj de cuco"], "correctOption": "Un reloj de cuco"}], "imageDescription": "Una mesa de madera con tres tazones: uno grande azul, uno mediano rojo y uno pequeño amarillo; sube vapor de los tazones; tres sillas; una ventana con cortinas a cuadros; un reloj de cuco en la pared."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('1e5f7de7-dbb1-4810-ba85-18a0091e58da', '2026-11-19 12:31:22.573983-03', '2026-11-19 12:31:22.573983-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "El dormitorio de los osos", "imageUrl": "assets/images/testigo/ricitos_dormitorio_osos.png", "questions": [{"prompt": "¿En qué cama dormía la niña?", "options": ["En la mediana", "En el suelo", "En la más grande", "En la más pequeña"], "correctOption": "En la más pequeña"}, {"prompt": "¿Cómo era la colcha?", "options": ["Roja lisa", "Amarilla", "Verde a rayas", "Azul con flores"], "correctOption": "Verde a rayas"}, {"prompt": "¿Qué forma tenía la alfombra?", "options": ["Triangular", "Redonda", "Ovalada", "Cuadrada"], "correctOption": "Redonda"}], "imageDescription": "Dormitorio con tres camas de distinto tamaño; en la cama más pequeña duerme una niña de cabello dorado; colcha verde a rayas; ventana abierta con luna; alfombra redonda de color naranja."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('f0a97e49-07d2-4af7-b205-b09bca7ee9ed', '2026-11-19 12:31:22.591609-03', '2026-11-19 12:31:22.591609-03', true, NULL, 'Desafío Imagen Pixelada #1', '{"challenges": [{"options": ["Una esmeralda", "Una perla", "El guisante", "Una uva", "Una canica"], "imageSrc": "assets/images/pixelado/guisante_pequeno.png", "correctCharacter": "El guisante", "imageDescription": "Un pequeño guisante verde y redondo sobre un cojín de terciopelo rojo."}], "total_time": 7}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('47fb3d0d-ba84-4e6c-b02f-2a301c510f27', '2026-11-19 12:31:22.593608-03', '2026-11-19 12:31:22.593608-03', true, NULL, 'Desafío Imagen Pixelada #2', '{"challenges": [{"options": ["Un pastel", "La pila de colchones", "Una montaña", "Una escalera", "Una torre de libros"], "imageSrc": "assets/images/pixelado/guisante_colchones.png", "correctCharacter": "La pila de colchones", "imageDescription": "Una pila altísima de colchones y edredones de colores, con una pequeña escalera de madera apoyada a un lado."}], "total_time": 7}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '9acff047-4bce-4ab5-90f1-fa676ea47a78');
INSERT INTO public.games_bookminigame VALUES ('49db4cc1-bf91-4352-8000-62c175d681fc', '2026-11-19 12:31:22.574983-03', '2026-11-19 12:31:22.574983-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Manta roja", "imageUrl": "assets/images/cazador-intrusos/manta-roja.png", "isIntruder": false}, {"id": "item-2", "name": "Cama de madera", "imageUrl": "assets/images/cazador-intrusos/cama-madera.png", "isIntruder": false}, {"id": "item-3", "name": "Tazón de avena", "imageUrl": "assets/images/cazador-intrusos/tazon-avena.png", "isIntruder": false, "imageDescription": "Tazón de cerámica con avena humeante y una cuchara de madera, fondo transparente."}, {"id": "item-4", "name": "Televisor de pantalla plana", "imageUrl": "assets/images/cazador-intrusos/tv.png", "isIntruder": true}, {"id": "item-5", "name": "Microondas", "imageUrl": "assets/images/cazador-intrusos/microondas.png", "isIntruder": true}, {"id": "item-6", "name": "Silla de madera", "imageUrl": "assets/images/cazador-intrusos/silla-madera.png", "isIntruder": false, "imageDescription": "Silla de madera sencilla de respaldo bajo, fondo transparente."}], "title": "La cocina de los osos", "bgImageUrl": "assets/images/cazador-intrusos/ricitos-cocina-bg.jpg", "textDescription": "En la casita de los osos había tazones de avena, sillas de madera, una cama de madera y una manta roja.", "bgImageDescription": "Interior de una casita de bosque, con chimenea, ventana pequeña y piso de madera; espacio libre para 6 objetos."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('2c57f6ae-f69f-4801-8c3f-bc907eadc41f', '2026-11-19 12:31:22.576982-03', '2026-11-19 12:31:22.576982-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Semáforo", "imageUrl": "assets/images/cazador-intrusos/semaforo.png", "isIntruder": true}, {"id": "item-2", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}, {"id": "item-3", "name": "Casa de madera de los osos", "imageUrl": "assets/images/cazador-intrusos/casa-osos.png", "isIntruder": false, "imageDescription": "Casita de madera con techo de paja y chimenea, fondo transparente."}, {"id": "item-4", "name": "Mariposa", "imageUrl": "assets/images/cazador-intrusos/mariposa.png", "isIntruder": false}, {"id": "item-5", "name": "Flores", "imageUrl": "assets/images/cazador-intrusos/flores.png", "isIntruder": false}, {"id": "item-6", "name": "Monopatín", "imageUrl": "assets/images/cazador-intrusos/monopatin.png", "isIntruder": true}], "title": "El bosque de los osos", "bgImageUrl": "assets/images/cazador-intrusos/ricitos-bosque-bg.jpg", "textDescription": "Alrededor de la casa de los osos crecían flores, volaban mariposas y se alzaba una casa de madera.", "bgImageDescription": "Claro de bosque soleado con árboles altos y pasto verde; espacio libre para 6 objetos."}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('b5a0190e-0a24-420c-8030-aadcdde3dcfd', '2026-11-19 12:31:22.578985-03', '2026-11-19 12:31:22.578985-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/ricitos-mesa-busca.jpg", "storyTitle": "Ricitos de oro y los tres osos", "targetArea": {"top": 45, "left": 35, "width": 40, "height": 37.5}, "textSnippet": "Sobre la mesa de la cocina, el tazón más pequeño humeaba junto a una cuchara de madera.", "imageDescription": "Cocina de la casa de los osos con una mesa de madera. En el centro, un tazón pequeño humeante, de color amarillo apagado, junto a dos tazones más grandes. Escena muy recargada: la mesa tiene muchos platos, jarras, cucharas, frutas, manteles, tazones de distintos tamaños y una vela.", "targetObjectName": "Tazón pequeño"}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('6899ab76-a2b3-4c7b-a9d6-1d6242539232', '2026-11-19 12:31:22.579984-03', '2026-11-19 12:31:22.579984-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/ricitos-dormitorio-busca.jpg", "storyTitle": "Ricitos de oro y los tres osos", "targetArea": {"top": 55, "left": 65, "width": 25, "height": 40}, "textSnippet": "Junto a la ventana del dormitorio, la sillita rota del Osito esperaba ser arreglada.", "imageDescription": "Dormitorio de la casa de los osos con tres camas. En la parte inferior derecha, una sillita de madera rota con una pata suelta, algo más clara que el suelo.", "targetObjectName": "Sillita rota"}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('23c55910-6c60-4239-a72c-ff82ac952500', '2026-11-19 12:31:22.581569-03', '2026-11-19 12:31:22.581569-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "La avena", "panels": [{"id": 1, "image": "assets/images/comics/ricitos1.png", "imageDescription": "Tres osos salen de su casa en el bosque dejando la avena enfriándose."}, {"id": 2, "image": "assets/images/comics/ricitos2.png", "imageDescription": "Ricitos de Oro llega a la casa y mira por la ventana."}, {"id": 3, "image": "assets/images/comics/ricitos3.png", "imageDescription": "Ricitos de Oro prueba la avena del tazón pequeño con una cuchara."}, {"id": 4, "image": "assets/images/comics/ricitos4.png", "imageDescription": "Ricitos de Oro se sienta en la sillita del Osito, que se rompe."}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('ccf671a3-9233-4d73-bdd4-9bde9b80ad2b', '2026-11-19 12:31:22.582579-03', '2026-11-19 12:31:22.582579-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "La camita", "panels": [{"id": 1, "image": "assets/images/comics/ricitos5.png", "imageDescription": "Ricitos de Oro duerme en la camita del Osito."}, {"id": 2, "image": "assets/images/comics/ricitos6.png", "imageDescription": "Los tres osos regresan y miran sorprendidos la mesa."}, {"id": 3, "image": "assets/images/comics/ricitos7.png", "imageDescription": "Los osos entran al dormitorio y ven a Ricitos durmiendo."}, {"id": 4, "image": "assets/images/comics/ricitos8.png", "imageDescription": "Ricitos de Oro salta por la ventana y escapa."}]}', 'e9120f23-404e-44c5-83f8-a47a42da26a1', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('9f47e2d8-03b1-4e10-82ab-03ff9576ea5a', '2026-11-19 12:31:22.586577-03', '2026-11-19 12:31:22.586577-03', true, NULL, 'Desafío Rafaga Vf #1', '{"statements": [{"text": "El príncipe buscaba una princesa verdadera.", "isTrue": true}, {"text": "La joven llegó en un día soleado.", "isTrue": false}, {"text": "La joven dijo ser una princesa.", "isTrue": true}], "passage_text": "Un príncipe quería casarse con una princesa de verdad, pero no lograba encontrarla. Una noche de tormenta, una joven empapada llamó a la puerta del castillo y dijo que era una princesa.", "time_per_statement": 7}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('5b06fa95-5a26-46ef-adcf-d8246b07cf75', '2026-11-19 12:31:22.587577-03', '2026-11-19 12:31:22.587577-03', true, NULL, 'Desafío Rafaga Vf #2', '{"statements": [{"text": "La reina puso un guisante en la cama.", "isTrue": true}, {"text": "Se usaron cinco colchones.", "isTrue": false}, {"text": "La joven durmió mal.", "isTrue": true}], "passage_text": "La reina puso un guisante en la cama de la joven y encima apiló veinte colchones. Por la mañana, la joven dijo que había dormido muy mal.", "time_per_statement": 7}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'e2b3f729-4edb-480b-876a-17c183a6b201');
INSERT INTO public.games_bookminigame VALUES ('c135ca6d-8700-4da2-a49c-93368c8a4b02', '2026-11-19 12:31:22.588579-03', '2026-11-19 12:31:22.588579-03', true, NULL, 'Desafío Emoticono Dialogo #1', '{"dialogues": [{"text": "¡Soy una princesa de verdad! ¿Me dan refugio?", "isCorrect": true}, {"text": "¡Hoy es un día muy soleado!", "isCorrect": false}, {"text": "¡Busco a mi gato perdido!", "isCorrect": false}, {"text": "¡Vengo a vender manzanas!", "isCorrect": false}], "emotionImage": "assets/images/emoticono/guisante_princesa_empapada.png", "imageDescription": "Una joven empapada por la lluvia, con el cabello mojado y el vestido arrugado, en la puerta de un castillo de noche, con relámpagos en el cielo."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'd26b3f60-9429-48ce-b6b6-c40aa3c02272');
INSERT INTO public.games_bookminigame VALUES ('2d8e57b9-829e-4339-8d7a-5853f82256b0', '2026-11-19 12:31:22.594609-03', '2026-11-19 12:31:22.594609-03', true, NULL, 'Desafío Encuentra Contradiccion #1', '{"timeLimit": 7, "challenges": [{"id": 1, "images": [{"id": 961, "altText": "Reina con colchones", "imageSrc": "assets/images/contra/guisante_reina_colchones.png", "isContradiction": false, "imageDescription": "La reina con vestido morado indicando a los criados que apilen colchones."}, {"id": 962, "altText": "Pila alta de colchones", "imageSrc": "assets/images/contra/guisante_pila_alta.png", "isContradiction": false, "imageDescription": "Una pila de colchones tan alta que casi llega al techo de la habitación."}, {"id": 963, "altText": "Reina con una piedra", "imageSrc": "assets/images/contra/guisante_reina_piedra.png", "isContradiction": true, "imageDescription": "La reina colocando una gran piedra gris sobre una cama."}, {"id": 964, "altText": "Guisante verde", "imageSrc": "assets/images/contra/guisante_verde_cojin.png", "isContradiction": false, "imageDescription": "Un guisante verde y brillante sobre una tabla de madera."}], "explanation": "La imagen contradictoria muestra a la reina poniendo una gran piedra en la cama.", "premiseText": "La reina puso un pequeño guisante en la cama y lo cubrió con veinte colchones."}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('89e47a23-1146-4666-990c-25d3fbc5defa', '2026-11-19 12:31:22.595577-03', '2026-11-19 12:31:22.595577-03', true, NULL, 'Desafío Encuentra Contradiccion #2', '{"timeLimit": 7, "challenges": [{"id": 2, "images": [{"id": 971, "altText": "Joven mojada", "imageSrc": "assets/images/contra/guisante_joven_mojada.png", "isContradiction": false, "imageDescription": "Una joven con vestido azul empapado de lluvia en la puerta de un castillo."}, {"id": 972, "altText": "Joven con sombrilla en un día soleado", "imageSrc": "assets/images/contra/guisante_joven_sombrilla.png", "isContradiction": true, "imageDescription": "Una joven con vestido seco y una sombrilla, llegando al castillo en un día de sol."}, {"id": 973, "altText": "Relámpago sobre el castillo", "imageSrc": "assets/images/contra/guisante_relampago_castillo.png", "isContradiction": false, "imageDescription": "Un relámpago iluminando un castillo con dos torres en una noche de tormenta."}, {"id": 974, "altText": "Rey con farol", "imageSrc": "assets/images/contra/guisante_rey_farol.png", "isContradiction": false, "imageDescription": "El rey con corona abriendo la puerta con un farol en la mano bajo la lluvia."}], "explanation": "La imagen contradictoria muestra a la joven llegando en un día soleado con una sombrilla y el vestido seco.", "premiseText": "La joven llegó a la puerta del castillo en una noche de tormenta, empapada por la lluvia."}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'aeb088b2-e0ed-43b9-a9dc-619cf4118899');
INSERT INTO public.games_bookminigame VALUES ('36ade6b2-3d48-4c1c-85fc-c4f4be038cff', '2026-11-19 12:31:22.597577-03', '2026-11-19 12:31:22.597577-03', true, NULL, 'Desafío Reconstruccion Manuscrito #1', '{"challenges": [{"id": 1, "title": "La princesa verdadera", "fragments": [{"id": 1, "text": "Un príncipe viaja por el mundo buscando una princesa verdadera."}, {"id": 2, "text": "Regresa al castillo sin encontrarla y se siente muy triste."}, {"id": 3, "text": "Una noche de tormenta, una joven empapada llama a la puerta del castillo."}, {"id": 4, "text": "La joven asegura ser una princesa y el rey la deja pasar."}, {"id": 5, "text": "La reina decide ponerla a prueba."}]}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('e99afd9c-b534-4918-9d05-9802809b6d2a', '2026-11-19 12:31:22.598579-03', '2026-11-19 12:31:22.598579-03', true, NULL, 'Desafío Reconstruccion Manuscrito #2', '{"challenges": [{"id": 2, "title": "El guisante", "fragments": [{"id": 1, "text": "La reina coloca un guisante en una cama vacía."}, {"id": 2, "text": "Encima del guisante, apila veinte colchones y veinte edredones."}, {"id": 3, "text": "La joven sube por una escalera a dormir en la cama."}, {"id": 4, "text": "Por la mañana dice que no pudo dormir por algo duro."}, {"id": 5, "text": "El príncipe se casa con ella y el guisante se guarda en un museo."}]}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '99e994f2-ebfd-4fcd-a7d5-18b1e35d1bd3');
INSERT INTO public.games_bookminigame VALUES ('2fc92bb3-8689-41fe-bc10-afc65ad19459', '2026-11-19 12:31:22.600392-03', '2026-11-19 12:31:22.600392-03', true, NULL, 'Desafío Completa Dialogo #1', '{"levels": [{"id": 1, "options": ["zapato", "anillo", "botón", "guisante"], "timeLeft": 7.0, "textAfter": "debajo de veinte colchones.", "textBefore": "La reina puso un pequeño", "correctWord": "guisante"}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('922c0a70-6204-4313-9123-50d23846f394', '2026-11-19 12:31:22.601404-03', '2026-11-19 12:31:22.601404-03', true, NULL, 'Desafío Completa Dialogo #2', '{"levels": [{"id": 2, "options": ["pequeño", "blando", "dulce", "duro"], "timeLeft": 7.0, "textAfter": "en mi cama.", "textBefore": "—No pude dormir en toda la noche; había algo muy", "correctWord": "duro"}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'f1a5f0d2-5698-4bd5-ae04-a424ffee28f8');
INSERT INTO public.games_bookminigame VALUES ('e317d3d1-e67f-45aa-abcd-ec2872a97e4d', '2026-11-19 12:31:22.603403-03', '2026-11-19 12:31:22.603403-03', true, NULL, 'Desafío Testigo Ocular #1', '{"id": 1, "title": "La puerta del castillo", "imageUrl": "assets/images/testigo/guisante_puerta_tormenta.png", "questions": [{"prompt": "¿De qué color era el vestido de la joven?", "options": ["Azul", "Blanco", "Rojo", "Verde"], "correctOption": "Azul"}, {"prompt": "¿Qué sostenía el rey?", "options": ["Un paraguas", "Un farol", "Una espada", "Un libro"], "correctOption": "Un farol"}, {"prompt": "¿Cuántas torres tenía el castillo?", "options": ["Dos", "Una", "Tres", "Cuatro"], "correctOption": "Dos"}], "imageDescription": "Noche de tormenta; un castillo con dos torres; una joven con vestido azul empapado y zapatos con barro; el rey con corona dorada sostiene un farol encendido; un relámpago amarillo en el cielo; charcos en el suelo."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('d8115ab8-4bbc-4315-8e80-a6b580c2e9ef', '2026-11-19 12:31:22.604402-03', '2026-11-19 12:31:22.604402-03', true, NULL, 'Desafío Testigo Ocular #2', '{"id": 2, "title": "La cama alta", "imageUrl": "assets/images/testigo/guisante_dormitorio_alto.png", "questions": [{"prompt": "¿Cómo se subía a la cama?", "options": ["De un salto", "Con un taburete", "Con una escalera de madera", "Con una cuerda"], "correctOption": "Con una escalera de madera"}, {"prompt": "¿De qué color era el vestido de la reina?", "options": ["Verde", "Rojo", "Amarillo", "Morado"], "correctOption": "Morado"}, {"prompt": "¿Qué había sobre la mesita?", "options": ["Un reloj", "Un libro", "Una vela", "Un florero"], "correctOption": "Una vela"}], "imageDescription": "Habitación con una cama altísima formada por muchos colchones apilados; una escalera de madera apoyada a un lado; la reina con vestido morado; una vela encendida sobre una mesita; ventana con luna."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'ccbc6e66-4484-469e-b8d4-9c1cdcdc608d');
INSERT INTO public.games_bookminigame VALUES ('1ff6f164-dd12-49c7-86ea-b590bdd2fab6', '2026-11-19 12:31:22.606403-03', '2026-11-19 12:31:22.606403-03', true, NULL, 'Desafío Cazador Intrusos #1', '{"id": 1, "items": [{"id": "item-1", "name": "Escalera de madera", "imageUrl": "assets/images/cazador-intrusos/escalera-madera.png", "isIntruder": false, "imageDescription": "Escalera de madera pequeña de seis peldaños, fondo transparente."}, {"id": "item-2", "name": "Vela encendida", "imageUrl": "assets/images/cazador-intrusos/vela.png", "isIntruder": false}, {"id": "item-3", "name": "Guisante", "imageUrl": "assets/images/cazador-intrusos/guisante.png", "isIntruder": false, "imageDescription": "Guisante verde y redondo, fondo transparente."}, {"id": "item-4", "name": "Teléfono móvil", "imageUrl": "assets/images/cazador-intrusos/telefono-movil.png", "isIntruder": true}, {"id": "item-5", "name": "Computadora portátil", "imageUrl": "assets/images/cazador-intrusos/laptop.png", "isIntruder": true}, {"id": "item-6", "name": "Pila de colchones", "imageUrl": "assets/images/cazador-intrusos/colchones.png", "isIntruder": false, "imageDescription": "Pila alta de colchones de colores, fondo transparente."}], "title": "La habitación de la princesa", "bgImageUrl": "assets/images/cazador-intrusos/guisante-dormitorio-bg.jpg", "textDescription": "En el dormitorio de la prueba había un guisante, una pila de colchones, una escalera de madera y una vela.", "bgImageDescription": "Dormitorio de castillo con ventana alta, paredes de piedra y alfombra; espacio libre para 6 objetos."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('b8c08b04-8fa3-4488-bf46-8805b004894d', '2026-11-19 12:31:22.607403-03', '2026-11-19 12:31:22.607403-03', true, NULL, 'Desafío Cazador Intrusos #2', '{"id": 2, "items": [{"id": "item-1", "name": "Capa de viaje", "imageUrl": "assets/images/cazador-intrusos/capa.png", "isIntruder": false}, {"id": "item-2", "name": "Impresora", "imageUrl": "assets/images/cazador-intrusos/impresora.png", "isIntruder": true}, {"id": "item-3", "name": "Farol", "imageUrl": "assets/images/cazador-intrusos/farol.png", "isIntruder": false, "imageDescription": "Farol antiguo de hierro con una vela encendida dentro, fondo transparente."}, {"id": "item-4", "name": "Radio a pilas", "imageUrl": "assets/images/cazador-intrusos/radio.png", "isIntruder": true}, {"id": "item-5", "name": "Corona del rey", "imageUrl": "assets/images/cazador-intrusos/corona-rey.png", "isIntruder": false}, {"id": "item-6", "name": "Nave espacial", "imageUrl": "assets/images/cazador-intrusos/nave-espacial.png", "isIntruder": true}], "title": "El castillo en la tormenta", "bgImageUrl": "assets/images/cazador-intrusos/guisante-castillo-bg.jpg", "textDescription": "Bajo la tormenta, en la entrada del castillo, aparecían una corona, una capa de viaje y un farol encendido.", "bgImageDescription": "Entrada de un castillo en una noche lluviosa, con puerta de madera y charcos; espacio libre para 6 objetos."}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '4de853f2-e390-44b2-ae92-453baf779be5');
INSERT INTO public.games_bookminigame VALUES ('5c14af38-9de6-44e0-bfc7-3a849ee8a6dd', '2026-11-19 12:31:22.609402-03', '2026-11-19 12:31:22.609402-03', true, NULL, 'Desafío Busca Imagen #1', '{"id": 1, "imageUrl": "assets/images/busca-imagen/guisante-cama-busca.jpg", "storyTitle": "La princesa y el guisante", "targetArea": {"top": 55, "left": 30, "width": 40, "height": 37.5}, "textSnippet": "En la base de la gigantesca pila de colchones, entre las tablas de la cama, descansaba un pequeño guisante verde.", "imageDescription": "Primer plano de la base de una cama altísima de madera. En la parte inferior, entre las tablas, un guisante verde apagado, enorme en este primer plano, que destaca levemente de la madera. Escena muy recargada: el suelo está lleno de colchones, edredones, almohadas, bolas de lana, botones y cuentas redondas verdes.", "targetObjectName": "Guisante"}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('00ed257c-0372-403a-b157-65241b7ab806', '2026-11-19 12:31:22.610401-03', '2026-11-19 12:31:22.610401-03', true, NULL, 'Desafío Busca Imagen #2', '{"id": 2, "imageUrl": "assets/images/busca-imagen/guisante-puerta-busca.jpg", "storyTitle": "La princesa y el guisante", "targetArea": {"top": 20, "left": 68, "width": 20, "height": 50}, "textSnippet": "Junto a la puerta del castillo, un farol encendido iluminaba la lluvia.", "imageDescription": "Puerta de castillo de noche con lluvia. En la parte derecha, un farol de hierro alto con la vela encendida, cuyo resplandor cálido lo distingue de la pared.", "targetObjectName": "Farol"}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, 'ba7e283a-7dce-47a9-ac50-d525798b5830');
INSERT INTO public.games_bookminigame VALUES ('c4be332d-e431-4e84-8e11-dd601e3f96f1', '2026-11-19 12:31:22.611404-03', '2026-11-19 12:31:22.611404-03', true, NULL, 'Desafío Comics Desordenados #1', '{"id": 1, "title": "Una noche de tormenta", "panels": [{"id": 1, "image": "assets/images/comics/guisante1.png", "imageDescription": "Un príncipe mira por la ventana del castillo, triste, sin haber encontrado una princesa verdadera."}, {"id": 2, "image": "assets/images/comics/guisante2.png", "imageDescription": "Un relámpago ilumina a una joven empapada frente a la puerta."}, {"id": 3, "image": "assets/images/comics/guisante3.png", "imageDescription": "El rey abre la puerta con un farol en la mano."}, {"id": 4, "image": "assets/images/comics/guisante4.png", "imageDescription": "La joven entra al castillo, cubierta con una manta, ante la mirada de la reina."}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');
INSERT INTO public.games_bookminigame VALUES ('c780fb61-a029-40a4-a55a-2ed1c51faa85', '2026-11-19 12:31:22.612433-03', '2026-11-19 12:31:22.612433-03', true, NULL, 'Desafío Comics Desordenados #2', '{"id": 2, "title": "El guisante", "panels": [{"id": 1, "image": "assets/images/comics/guisante5.png", "imageDescription": "La reina coloca un guisante sobre la cama vacía."}, {"id": 2, "image": "assets/images/comics/guisante6.png", "imageDescription": "Los criados apilan veinte colchones sobre el guisante."}, {"id": 3, "image": "assets/images/comics/guisante7.png", "imageDescription": "La joven sube por una escalera a la altísima cama."}, {"id": 4, "image": "assets/images/comics/guisante8.png", "imageDescription": "A la mañana siguiente, la joven bosteza y cuenta que no durmió, mientras el príncipe sonríe."}]}', 'eb9d5819-90c0-4b08-9fdf-6d220afcdb17', NULL, '61146aca-d995-4f2e-86b7-9b5b3c894511');


