INSERT INTO public.mochila_item VALUES ('0eb9860d-afe6-40be-a8f2-2b684d58b576', '2026-11-19 12:31:24.992367-03', '2026-11-19 12:31:24.992367-03', NULL, 'Candado de adivinanzas', 'Un candado mágico de seguridad que sólo responde ante la agudeza mental y la respuesta correcta.', 'assets/images/items/candado.png', 'purchase', 150, true, 'f91e20ed-66d8-484c-b8c9-a8be862a0e6d');
