INSERT INTO public.mochila_item VALUES ('8181512f-0eb4-42f8-86c6-22b70f5e9c0e', '2026-11-19 12:31:25.030368-03', '2026-11-19 12:31:25.030368-03', NULL, 'Cuerda de rescate', 'Una cuerda resistente ideal para ayudar a quienes han quedado atrapados en estrechos ductos de ventilación.', 'assets/images/items/cuerda.png', 'reading', NULL, true, '1c177207-1c00-4208-b2d0-a641a78f4258');
INSERT INTO public.mochila_item VALUES ('eaa8d34e-1dfb-46d1-aab9-9e2849017874', '2026-11-19 12:31:25.039369-03', '2026-11-19 12:31:25.039369-03', NULL, 'Patines de ruedas', 'Un par de patines ligeros con cintas decorativas que permiten huir haciendo curvas a gran velocidad.', 'assets/images/items/patines.png', 'purchase', 150, true, '1c177207-1c00-4208-b2d0-a641a78f4258');
INSERT INTO public.mochila_item VALUES ('6906fd5b-3926-4434-8e56-6042c09bad68', '2026-11-19 12:31:25.0473-03', '2026-11-19 12:31:25.0473-03', NULL, 'Peine de nenúfar', 'Un delicado peine tallado en hoja de agua que domina las plumas encrespadas y crea estilos despeinados elegantes.', 'assets/images/items/peine_nenufar.png', 'reading', NULL, true, '8287b2a4-aad3-47e0-95e4-d70e13bd182c');
INSERT INTO public.mochila_item VALUES ('05b2379e-1b2d-45e1-a94c-00b5974c96c9', '2026-11-19 12:31:25.0543-03', '2026-11-19 12:31:25.0543-03', NULL, 'Delantal de bolsillos infinitos', 'Un delantal sorprendente capaz de recuperar cualquier objeto extraviado dentro de sus múltiples compartimentos.', 'assets/images/items/delantal.png', 'purchase', 150, true, '8287b2a4-aad3-47e0-95e4-d70e13bd182c');


